function mediaItemsFromInput(input) {
  return [...(input?.files || [])].map((file) => ({
    name: file.name,
    type: file.type || "",
    byteSize: file.size,
    lastModified: file.lastModified,
    uploadSelectionKey: window.TennisNotePersonalJournal?.selectionKey(file) || "",
    url: URL.createObjectURL(file),
  }));
}

function mediaItemsFromNames(names = []) {
  return names.map((name) => {
    const isVideo = /\.(mp4|mov|webm|m4v)$/i.test(name);
    const isImage = /\.(jpg|jpeg|png|gif|webp)$/i.test(name);
    return {
      name,
      type: isVideo ? "video/demo" : isImage ? "image/demo" : "",
      url: "",
    };
  });
}

function normalizeMediaItems(log) {
  if (Array.isArray(log.mediaItems) && log.mediaItems.length) return log.mediaItems;
  return mediaItemsFromNames(log.mediaNames || []);
}

function journalMediaPreviewUrl(value = "") {
  if (!value) return "";
  try {
    const url = new URL(value, window.location.href);
    return ["https:", "blob:"].includes(url.protocol) ? url.href : "";
  } catch { return ""; }
}

function journalMediaUnavailableMessage() {
  return "첨부 원본을 표시할 수 없습니다. 파일을 다시 첨부해 주세요.";
}

function journalServerMediaRetryMessage() {
  return "저장된 첨부의 재생에 문제가 있습니다. 원본은 보존됩니다. 다시 열어 확인해 주세요.";
}

function journalMediaFailureKind(media) {
  const code = Number(media?.error?.code) || 0;
  return code === 3 || code === 4 ? "decoder" : "get";
}

async function handleJournalMediaPreviewError(event) {
  const media = event.target;
  if (!media?.matches?.("[data-journal-media-preview]") || media.dataset.previewFailed || media.dataset.previewRetrying) return;
  const detail = media.closest("#journalDetailContent");
  const log = state.practiceLogs.find((item) => item.id === detail?.dataset.journalEntryId);
  const item = log?.mediaItems?.[Number(media.dataset.journalMediaIndex)];
  if (item?.serverMediaId && item.storagePath && !media.dataset.previewRetried) {
    media.dataset.previewRetried = "true";
    media.dataset.previewRetrying = "true";
    try {
      const url = await window.TennisNotePersonalJournal.refreshMediaUrl(item);
      if (!media.isConnected || detail.dataset.journalEntryId !== log.id) return;
      media.src = url;
      media.load?.();
      return;
    } catch { item.mediaFailureKind = "signed_url"; /* 기존 첨부를 보존한다. */ }
    finally { delete media.dataset.previewRetrying; }
  }
  if (!media.isConnected) return;
  if (item && item.mediaFailureKind !== "signed_url") item.mediaFailureKind = journalMediaFailureKind(media);
  // Preserve the failed node for decoder diagnostics, without claiming the server object was lost.
  media.dataset.previewFailed = "true";
  media.hidden = true;
  const notice = document.createElement("p");
  notice.setAttribute("role", "status");
  notice.textContent = item?.serverMediaId ? journalServerMediaRetryMessage() : journalMediaUnavailableMessage();
  media.after(notice);
}

function renderMediaPreview(mediaItems = [], compact = false) {
  if (!mediaItems.length) return "";
  return `
    <div class="journal-media-grid ${compact ? "compact" : ""}">
      ${mediaItems
        .map((item, index) => {
          if (item.error) return `<p role="status">${escapeHtml(item.error)}</p>`;
          const url = journalMediaPreviewUrl(item.url);
          const isVideo = item.type?.startsWith("video") || /\.(mp4|mov|webm|m4v)$/i.test(item.name || "");
          const isImage = item.type?.startsWith("image") || /\.(jpg|jpeg|png|gif|webp)$/i.test(item.name || "");
          if (url && isVideo) {
            return `
              <figure class="journal-media-item video">
                <video data-journal-media-preview data-journal-media-index="${index}" src="${escapeHtml(url)}" controls playsinline preload="metadata"></video>
                <figcaption>${escapeHtml(item.name)}</figcaption>
              </figure>`;
          }
          if (url && isImage) {
            return `
              <figure class="journal-media-item image">
                <img data-journal-media-preview data-journal-media-index="${index}" src="${escapeHtml(url)}" alt="${escapeHtml(item.name)}" loading="lazy" />
                <figcaption>${escapeHtml(item.name)}</figcaption>
              </figure>`;
          }
          return `<div class="journal-media-item"><b class="media-chip">${escapeHtml(item.name)}</b><p role="status">${item.serverMediaId ? "저장된 첨부를 다시 확인하는 중입니다." : journalMediaUnavailableMessage()}</p></div>`;
        })
        .join("")}
    </div>`;
}

function curriculumById(id, fallback) {
  const canonicalId = curriculumCatalog.aliases?.[id] || id;
  return curriculumSteps.find((step) => step.id === canonicalId) || fallback || curriculumSteps[0];
}

function latestCurriculumLog() {
  return state.lessonLogs.find((log) => log.nextCurriculumId || log.curriculum?.id) || state.lessonLogs[0] || null;
}

function activeCurriculumStep() {
  const latest = latestCurriculumLog();
  return curriculumById(latest?.nextCurriculumId || latest?.curriculum?.id, latest?.curriculum);
}

function curriculumStageCards() {
  const active = activeCurriculumStep();
  const track = curriculumSkillTracks.find((item) => item.steps.some((step) => step.id === active.id));
  const trackSteps = track?.steps?.length ? track.steps : curriculumSteps;
  const activeIndex = Math.max(0, trackSteps.findIndex((step) => step.id === active.id));
  const review = trackSteps[Math.max(0, activeIndex - 1)] || active;
  const next = curriculumById(active.nextLessonId, trackSteps[Math.min(trackSteps.length - 1, activeIndex + 1)] || active);
  return [
    { label: "현재 단계", step: active, tone: "current" },
