function memberHoldingPolicy() {
  const fallback = {
    personalMaxDays: 7,
    fourWeekPersonalMaxDays: 7,
    threeMonthPersonalMaxDays: 14,
    couponPersonalMaxDays: 0,
    injuryMaxDays: 30,
    emergencyRetroactiveDays: 3,
    evidenceRequired: true,
    evidenceRetentionDays: 30,
  };
  let saved = fallback;
  try {
    const snapshot = JSON.parse(localStorage.getItem(adminStorageKey) || "null");
    saved = { ...fallback, ...(state.holdingPolicySettings || {}), ...(snapshot?.holdingPolicySettings || {}) };
  } catch {
    saved = fallback;
  }
  const ticketTitle = String(currentHoldingTicket()?.title || "");
  const personalMaxDays = /쿠폰/.test(ticketTitle)
    ? Number(saved.couponPersonalMaxDays) || 0
    : /3개월|12주/.test(ticketTitle)
      ? Number(saved.threeMonthPersonalMaxDays) || 14
      : Number(saved.fourWeekPersonalMaxDays ?? saved.personalMaxDays) || 7;
  return { ...saved, personalMaxDays };
}

function currentHoldingTicket(ticketId = state.selectedHoldingTicketId) {
  const liveTicket = currentLiveTickets().find((ticket) => String(ticket.id) === String(ticketId || ""))
    || currentLiveTicket();
  if (liveTicket) return liveTicket;
  if (state.member && state.ticketSyncStatus?.tone === "demo") {
    return {
      id: "demo-ticket-holding",
      branchId: "demo-branch",
      title: state.profile.ticket || "정기권",
      status: "active",
      total: 10,
      remaining: state.remaining,
      used: Math.max(0, 10 - state.remaining),
      startsOn: "2026-07-01",
      expiresOn: "2026-07-31",
      statusLabel: "데모 이용중",
    };
  }
  return null;
}

function memberHoldingRequests(ticketId = state.selectedHoldingTicketId) {
  const shared = loadSharedData();
  const memberName = state.member?.name || state.profile.name;
  return (shared.holdingRequests || []).filter((request) => (
    request.member === memberName
    && (!ticketId || String(request.ticketId || "") === String(ticketId))
  ));
}

function holdingStatusLabel(status) {
  if (status === "approved") return "승인";
  if (status === "rejected") return "반려";
  if (status === "cancelled") return "취소";
  return "검토중";
}

const memberRefundRequestFlow = {
  ticket: null,
  preview: null,
  request: null,
  loading: false,
  submitting: false,
  operationKey: "",
  message: "",
  tone: "neutral",
};

function memberRefundRequestForTicket(ticketId) {
  return (state.refundRequests || []).find((request) => String(request.ticketId || "") === String(ticketId || "")) || null;
}

function memberRefundRequestStatus(status = "") {
  const labels = {
    submitted: ["접수 완료", "관리자가 결제와 이용 횟수를 확인합니다."],
    reviewing: ["검토 중", "관리자가 환불 정책과 계산값을 확인하고 있습니다."],
    approved: ["승인됨", "관리자가 결제수단에 맞는 환불 처리를 준비합니다."],
    executing: ["처리 중", "PG 취소 또는 계좌이체 송금 확인을 진행하고 있습니다."],
    completed: ["환불 완료", "환불과 회원권 반영이 완료되었습니다."],
    rejected: ["요청 반려", "관리자 안내를 확인해 주세요."],
    failed: ["처리 확인 필요", "환불은 자동 재실행되지 않습니다. 관리자 확인이 필요합니다."],
  };
  const [label, detail] = labels[String(status || "")] || ["상태 확인", "최신 요청 상태를 확인해 주세요."];
  return { label, detail };
}

function memberRefundErrorText(code = "") {
  const labels = {
    member_login_required: "회원 로그인 후 이용해 주세요.",
    payment_not_owned: "내 결제와 회원권 연결을 확인하지 못했습니다.",
    payment_not_refundable: "현재 환불을 요청할 수 없는 결제 상태입니다.",
    refund_reason_required: "환불 요청 사유를 2자 이상 입력해 주세요.",
    refund_preview_changed: "이용 횟수 또는 계산 금액이 바뀌었습니다. 최신 계산값을 다시 확인해 주세요.",
    ticket_usage_changed: "회원권 이용 횟수가 바뀌었습니다. 최신 계산값을 다시 확인해 주세요.",
    policy_fallback_confirmation_required: "현재 정책 기준 계산 확인이 필요합니다.",
    nothing_to_refund: "계산된 환불 예상액이 없어 요청할 수 없습니다.",
    refund_request_submit_failed: "환불 요청을 접수하지 못했습니다. 결제 상태를 다시 확인해 주세요.",
  };
  return labels[code] || "환불 요청 상태를 확인하지 못했습니다. 잠시 후 다시 확인해 주세요.";
}

function newMemberRefundOperationKey() {
  const value = window.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `member-refund:${value}`;
}

function renderMemberRefundRequestSheet() {
  const target = $("#memberRefundRequestContent");
  const form = $("#memberRefundRequestForm");
  const reason = $("#memberRefundRequestReason");
  const fallback = $("#memberRefundPolicyFallback");
  const submit = $("#submitMemberRefundRequest");
  const message = $("#memberRefundRequestMessage");
  if (!target || !form) return;
  const request = memberRefundRequestFlow.request;
  if (memberRefundRequestFlow.loading) {
    target.innerHTML = '<p class="member-refund-loading" role="status">결제와 회원권의 최신 환불 예상액을 확인하고 있습니다.</p>';
  } else if (request) {
    const status = memberRefundRequestStatus(request.status);
    target.innerHTML = `<article class="member-refund-status-card" data-status="${escapeHtml(request.status || "submitted")}">
      <span>환불 요청 상태</span><strong>${escapeHtml(status.label)}</strong><p>${escapeHtml(status.detail)}</p>
      ${request.expectedRefundAmount ? `<small>접수 당시 예상 환불액 ${Number(request.expectedRefundAmount).toLocaleString("ko-KR")}원</small>` : ""}
      ${request.rejectionReason ? `<small class="is-danger">반려 사유: ${escapeHtml(request.rejectionReason)}</small>` : ""}
    </article>`;
  } else if (memberRefundRequestFlow.preview) {
    const preview = memberRefundRequestFlow.preview;
    target.innerHTML = `<article class="member-refund-preview">
      <div><span>${escapeHtml(preview.productName || "회원권")}</span><strong>예상 환불액 ${Number(preview.refundAmount || 0).toLocaleString("ko-KR")}원</strong></div>
      <dl><div><dt>결제금액</dt><dd>${Number(preview.paidAmount || 0).toLocaleString("ko-KR")}원</dd></div><div><dt>사용 회차</dt><dd>총 ${Number(preview.totalSessions || 0)}회 중 ${Number(preview.usedSessions || 0)}회</dd></div><div><dt>사용·위약금 등 차감</dt><dd>-${(Number(preview.usedAmount || 0) + Number(preview.penaltyAmount || 0) + Number(preview.reservationFee || 0)).toLocaleString("ko-KR")}원</dd></div></dl>
      <p>요청 접수만으로 결제 취소나 계좌 송금, 회원권 변경은 실행되지 않습니다. 관리자가 최신 이용 내역과 정책을 다시 확인한 뒤 처리합니다.</p>
    </article>`;
  } else {
    target.innerHTML = '<p class="member-refund-loading is-danger">환불 예상액을 불러오지 못했습니다.</p>';
  }
  const editable = Boolean(memberRefundRequestFlow.preview && !request && !memberRefundRequestFlow.loading);
  if (reason) reason.disabled = !editable || memberRefundRequestFlow.submitting;
  if (fallback) {
    fallback.closest("label").hidden = !memberRefundRequestFlow.preview?.requiresPolicyFallbackConfirmation || !editable;
    fallback.disabled = !editable || memberRefundRequestFlow.submitting;
  }
  if (submit) {
    submit.hidden = !editable;
    submit.disabled = !editable || memberRefundRequestFlow.submitting;
    submit.textContent = memberRefundRequestFlow.submitting ? "접수 중" : "환불 요청 접수";
  }
  if (message) {
    message.textContent = memberRefundRequestFlow.message || "";
    message.className = `form-message ${memberRefundRequestFlow.tone === "danger" ? "danger" : memberRefundRequestFlow.tone === "good" ? "good" : ""}`;
  }
}

async function syncMemberRefundRequests() {
  const client = window.TennisNoteDataClient;
  if (!client?.invokeFunction || !client.getSession?.()?.access_token) return false;
  try {
    const result = await client.invokeFunction("portone-payment/refund-request-member-list", { body: {} });
    state.refundRequests = Array.isArray(result?.requests) ? result.requests : [];
    return true;
  } catch {
    return false;
  }
}

async function openMemberRefundRequest(ticketId) {
  const ticket = (state.liveTickets || []).find((item) => String(item.id || "") === String(ticketId || ""));
  if (!ticket?.providerPaymentId || ticket.paymentStatus !== "verified") {
    showToast("환불 가능한 결제와 회원권 연결을 확인해 주세요.");
    return;
  }
  Object.assign(memberRefundRequestFlow, {
    ticket,
    preview: null,
    request: memberRefundRequestForTicket(ticket.id),
    loading: !memberRefundRequestForTicket(ticket.id),
    submitting: false,
    operationKey: newMemberRefundOperationKey(),
    message: "",
    tone: "neutral",
  });
  $("#memberRefundRequestReason").value = "";
  $("#memberRefundPolicyFallback").checked = false;
  openAppSheet("memberRefundRequestSheet", { initialFocus: "#memberRefundRequestReason, [data-close-member-refund-request]" });
  renderMemberRefundRequestSheet();
  if (memberRefundRequestFlow.request) return;
  try {
    const result = await window.TennisNoteDataClient.invokeFunction("portone-payment/refund-request-preview", {
      body: { paymentId: ticket.providerPaymentId },
    });
    memberRefundRequestFlow.preview = result?.preview || null;
    memberRefundRequestFlow.message = "예상 금액과 정책을 확인하고 요청 사유를 입력해 주세요.";
  } catch (error) {
    memberRefundRequestFlow.message = memberRefundErrorText(error?.payload?.code || error?.message);
    memberRefundRequestFlow.tone = "danger";
  } finally {
    memberRefundRequestFlow.loading = false;
    renderMemberRefundRequestSheet();
  }
}

async function submitMemberRefundRequest() {
  const ticket = memberRefundRequestFlow.ticket;
  const preview = memberRefundRequestFlow.preview;
  const reason = $("#memberRefundRequestReason")?.value.trim() || "";
  if (!ticket || !preview || memberRefundRequestFlow.submitting) return;
  if (reason.length < 2) {
    memberRefundRequestFlow.message = memberRefundErrorText("refund_reason_required");
    memberRefundRequestFlow.tone = "danger";
    renderMemberRefundRequestSheet();
    return;
  }
  if (preview.requiresPolicyFallbackConfirmation && !$("#memberRefundPolicyFallback")?.checked) {
    memberRefundRequestFlow.message = memberRefundErrorText("policy_fallback_confirmation_required");
    memberRefundRequestFlow.tone = "danger";
    renderMemberRefundRequestSheet();
    return;
  }
  memberRefundRequestFlow.submitting = true;
  memberRefundRequestFlow.message = "환불 요청을 안전하게 접수하고 있습니다.";
  memberRefundRequestFlow.tone = "neutral";
  renderMemberRefundRequestSheet();
  try {
    const result = await window.TennisNoteDataClient.invokeFunction("portone-payment/refund-request-submit", {
      body: {
        paymentId: ticket.providerPaymentId,
        operationKey: memberRefundRequestFlow.operationKey,
        reason,
        expectedRefundAmount: Number(preview.refundAmount || 0),
        expectedUsedSessions: Number(preview.usedSessions || 0),
        acceptPolicyFallback: Boolean($("#memberRefundPolicyFallback")?.checked),
      },
    });
    memberRefundRequestFlow.request = { ...result.request, ticketId: ticket.id, expectedRefundAmount: preview.refundAmount };
    state.refundRequests = [memberRefundRequestFlow.request, ...(state.refundRequests || []).filter((item) => String(item.ticketId || "") !== String(ticket.id))];
    memberRefundRequestFlow.message = "환불 요청이 접수되었습니다. 실제 환불은 관리자 확인 뒤 진행됩니다.";
    memberRefundRequestFlow.tone = "good";
    renderProducts();
  } catch (error) {
    const code = error?.payload?.code || error?.message || "refund_request_submit_failed";
    memberRefundRequestFlow.message = memberRefundErrorText(code);
    memberRefundRequestFlow.tone = "danger";
    if (["refund_preview_changed", "ticket_usage_changed"].includes(code)) memberRefundRequestFlow.preview = null;
  } finally {
    memberRefundRequestFlow.submitting = false;
    renderMemberRefundRequestSheet();
  }
}

function membershipTicketCard(ticket = {}, options = {}) {
  const currentTicketIds = options.currentTicketIds || new Set();
  const compact = Boolean(options.compact);
  const totalSessions = Math.max(0, Number(ticket.total || 0));
  const remainingSessions = Math.max(0, Number(ticket.remaining || 0));
  const usedSessions = Math.max(0, Number(ticket.used ?? totalSessions - remainingSessions));
  const progress = totalSessions ? Math.min(100, Math.max(0, (usedSessions / totalSessions) * 100)) : 0;
  const derivedState = window.TennisNoteTicketState?.derive?.(ticket) || ticket.status || "current";
  const isPendingTicket = derivedState === "pending_payment";
  const isUpcomingTicket = derivedState === "upcoming";
  const isRefundHeld = Boolean(ticket.refundHoldId);
  const isCurrentTicket = currentTicketIds.has(String(ticket.id || "")) || String(ticket.id || "").startsWith("demo-");
  const isLowTicket = isCurrentTicket && remainingSessions <= 2;
  const statusLabel = isRefundHeld
    ? "환불 접수 · 송금 대기"
    : window.TennisNoteTicketState?.label?.(ticket)
      || (isPendingTicket ? "결제 대기" : isUpcomingTicket ? "시작 예정" : ticket.statusLabel || "사용 중");
  const ticketPeriod = ticket.expiresOn
    ? `${ticket.startsOn || "시작일 확인"} ~ ${ticket.expiresOn}`
    : "이용 기간 확인 중";
  const holding = isCurrentTicket ? memberHoldingRequests(ticket.id)[0] : null;
  const pendingPaymentId = ticket.providerPaymentId || "";
  const canResumePayment = pendingPaymentId && Number(ticket.paymentAmount || 0) > 0;
  const isCancellingPendingPayment = Boolean(pendingPaymentId && pendingPaymentCancelInFlight.has(pendingPaymentId));
  const pendingPaymentActions = isPendingTicket
    ? `<div class="membership-pending-actions">
        <button class="small-button" type="button" data-resume-pending-ticket="${escapeHtml(ticket.id)}" ${canResumePayment ? "" : "disabled"}>결제 계속</button>
        <button class="small-button" type="button" data-check-pending-ticket="${escapeHtml(ticket.id)}" ${pendingPaymentId ? "" : "disabled"}>상태 확인</button>
        <button class="small-button danger-button" type="button" data-cancel-pending-ticket="${escapeHtml(ticket.id)}" ${pendingPaymentId && !isCancellingPendingPayment ? "" : "disabled"}>${isCancellingPendingPayment ? "취소 중" : "대기 취소"}</button>
      </div>`
    : "";
  const holdingAction = isCurrentTicket && !isPendingTicket
    ? `<button class="membership-status-note" type="button" data-open-holding-request="${escapeHtml(ticket.id)}">${holding ? `이용 보류 · ${escapeHtml(holdingStatusLabel(holding.status))}` : "기간 보류 신청"}</button>`
    : "";
  return `
    <article class="membership-ticket-unit ${compact ? "is-compact" : ""}" data-member-ticket-id="${escapeHtml(ticket.id || "")}" ${options.primary ? "data-primary-member-ticket" : ""}>
      <div class="membership-primary-card ${isPendingTicket || isUpcomingTicket ? "is-pending" : ""} ${isLowTicket ? "is-low" : ""}">
        <div class="membership-primary-head">
          <span>${isUpcomingTicket || isPendingTicket ? "다음 회원권" : "현재 회원권"}</span>
          <small>${escapeHtml(statusLabel)}</small>
        </div>
        <strong>${escapeHtml(ticket.title || "회원권")}</strong>
        <div class="membership-remaining-row">
          <span>남은 횟수</span>
          <b>${remainingSessions}<em>회</em></b>
        </div>
        ${compact ? "" : `<div class="membership-progress" role="progressbar" aria-valuemin="0" aria-valuemax="${totalSessions || 1}" aria-valuenow="${usedSessions}" aria-label="회원권 사용 진행률"><span style="width: ${progress}%"></span></div>`}
        <small class="membership-period">${escapeHtml(ticketPeriod)}${compact ? "" : ` · 총 ${totalSessions} / 사용 ${usedSessions}`}</small>
      </div>
      ${pendingPaymentActions}
      ${isRefundHeld ? '<p class="membership-status-note">송금 완료 또는 접수취소 전까지 수업 차감과 예약 변경이 잠시 정지됩니다.</p>' : ""}
      ${holdingAction}
    </article>`;
}

function latestPreviousMembershipTicket() {
  return [...(state.liveTickets || []), ...(state.expiredTickets || [])]
    .filter((ticket) => ["active", "paused", "expired"].includes(String(ticket.status || "").toLowerCase()))
    .sort((left, right) => String(right.expiresOn || right.createdAt || "").localeCompare(String(left.expiresOn || left.createdAt || "")))[0] || null;
}

function membershipTicketCanKeepSchedule(ticket) {
  if (!ticket || !["active", "paused"].includes(String(ticket.status || "").toLowerCase())) return false;
  return !ticket.expiresOn || String(ticket.expiresOn) >= localDateKey();
}

function renderCurrentTicketPanel() {
  const target = $("#currentTicketPanel");
  if (!target) return;
  const currentTickets = currentLiveTickets();
  const upcomingTickets = upcomingLiveTickets();
  const refundHeldTickets = refundHeldLiveTickets();
  const demoTicket = !currentTickets.length && !upcomingTickets.length && !refundHeldTickets.length ? currentHoldingTicket() : null;
  const visibleTickets = [...currentTickets, ...refundHeldTickets, ...upcomingTickets];
  if (demoTicket) visibleTickets.push(demoTicket);
  const currentTicketIds = new Set(currentTickets.map((ticket) => String(ticket.id || "")));
  const primaryTicket = visibleTickets[0] || null;
  const primaryRefundRequest = primaryTicket ? memberRefundRequestForTicket(primaryTicket.id) : null;
  const lifecycle = memberPurchaseLifecycle();
  const previousTicket = lifecycle === "returning" ? latestPreviousMembershipTicket() : null;
  const otherTickets = visibleTickets.slice(1);
  const primaryCard = primaryTicket
    ? membershipTicketCard(primaryTicket, { currentTicketIds, primary: true })
    : previousTicket
      ? `<article class="membership-empty-ticket membership-previous-ticket">
          <span>이전 회원권</span>
          <strong>${escapeHtml(previousTicket.title || "회원권")}</strong>
          <small>마지막 이용 ${escapeHtml(previousTicket.expiresOn || "기간 확인")}</small>
          <p>다시 시작하시겠어요? 이전 수업 조건을 불러왔습니다.</p>
        </article>`
      : `<article class="membership-empty-ticket"><strong>아직 등록된 회원권이 없습니다</strong><span>상품과 선생님·시간을 한 번에 선택할 수 있습니다.</span></article>`;
  const otherTicketList = otherTickets.length
    ? `<details class="membership-other-tickets" ${currentTickets.length > 1 ? "open" : ""}>
        <summary>${currentTickets.length > 1 ? "함께 사용 중인" : "다른"} 회원권 ${otherTickets.length}개</summary>
        <div>${otherTickets.map((ticket) => membershipTicketCard(ticket, { currentTicketIds, compact: true })).join("")}</div>
      </details>`
    : "";
  const primaryAction = primaryTicket
    ? primaryTicket.refundHoldId
      ? '<button class="primary-button" type="button" disabled>환불 송금 대기</button>'
      : `<button class="primary-button" type="button" data-renew-ticket="${escapeHtml(primaryTicket.id || "")}">연장</button>`
    : previousTicket
      ? `<button class="primary-button" type="button" data-reregister-ticket="${escapeHtml(previousTicket.id || "")}">재등록</button>`
      : '<button class="primary-button" type="button" data-open-purchase-flow="new_purchase">등록</button>';
  const secondaryAction = primaryTicket
    ? primaryTicket.refundHoldId
      ? ""
      : '<button class="small-button membership-secondary-action" type="button" data-open-purchase-flow="add_coach">다른 코치·이용권 추가</button>'
    : previousTicket
      ? '<button class="small-button membership-secondary-action" type="button" data-open-purchase-flow="new_purchase">다른 상품으로 등록</button>'
      : "";
  target.innerHTML = `
    ${primaryCard}
    <div class="membership-action-row ${primaryTicket ? "has-ticket" : "is-empty"}">
      ${primaryAction}
      ${secondaryAction}
      <details class="membership-more-actions">
        <summary>더보기</summary>
        <div>
          <button class="small-button" type="button" data-open-discount-coupon-wallet>쿠폰함</button>
          <button class="small-button" type="button" data-open-membership-history>이용 내역</button>
          ${primaryTicket?.providerPaymentId && primaryTicket.paymentStatus === "verified" && !primaryTicket.refundHoldId
            ? `<button class="small-button" type="button" data-open-member-refund-request="${escapeHtml(primaryTicket.id || "")}">${primaryRefundRequest ? `환불 요청 · ${escapeHtml(memberRefundRequestStatus(primaryRefundRequest.status).label)}` : "환불 요청"}</button>`
            : ""}
        </div>
      </details>
    </div>
    ${otherTicketList}
    ${currentTickets.length > 1 ? `<p class="membership-multiple-note">현재 회원권 ${currentTickets.length}개가 모두 적용되어 있습니다. 수업에 연결된 회원권에서만 횟수가 차감됩니다.</p>` : ""}`;
}

function holdingRequestDays(startDate, endDate) {
  const start = new Date(`${startDate}T00:00:00`);
  const end = new Date(`${endDate}T00:00:00`);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) return 0;
  return Math.floor((end - start) / 86400000) + 1;
}

function updateHoldingEvidenceFields() {
  const injury = $("#holdingRequestType")?.value === "injury";
  if ($("#holdingEvidenceFields")) $("#holdingEvidenceFields").hidden = !injury;
  if (!injury) {
    if ($("#holdingEvidenceFile")) $("#holdingEvidenceFile").value = "";
    if ($("#holdingSensitiveConsent")) $("#holdingSensitiveConsent").checked = false;
  }
  const policy = memberHoldingPolicy();
  const personalOption = $("#holdingRequestType option[value='personal']");
  if (personalOption) personalOption.disabled = Number(policy.personalMaxDays) <= 0;
  if (!injury && Number(policy.personalMaxDays) <= 0) {
    $("#holdingRequestType").value = "injury";
    return updateHoldingEvidenceFields();
  }
  if ($("#holdingPolicySummary")) {
    $("#holdingPolicySummary").textContent = injury
      ? `부상 홀딩 최대 ${policy.injuryMaxDays}일 · 증빙 확인 필요`
      : `개인 사유 홀딩 최대 ${policy.personalMaxDays}일`;
  }
}

function openHoldingRequestModal(ticketId = "") {
  state.selectedHoldingTicketId = ticketId || currentLiveTicket()?.id || "";
  if (!currentHoldingTicket()) return;
  const today = new Date();
  $("#holdingRequestForm")?.reset();
  $("#holdingStartDate").value = today.toISOString().slice(0, 10);
  $("#holdingEndDate").value = new Date(today.getTime() + 6 * 86400000).toISOString().slice(0, 10);
  $("#holdingRequestMessage").textContent = "승인되면 해당 기간만큼 회원권 종료일이 연장됩니다.";
  updateHoldingEvidenceFields();
  $("#holdingRequestModal").hidden = false;
  void ensureMemberHoldingData();
}

function closeHoldingRequestModal() {
  $("#holdingRequestModal").hidden = true;
}

function safeHoldingFileName(fileName = "evidence") {
  const extension = `${fileName}`.split(".").pop().toLowerCase().replace(/[^a-z0-9]/g, "") || "bin";
  return `evidence.${extension}`;
}

async function submitHoldingRequest(event) {
  event.preventDefault();
  const ticket = currentHoldingTicket();
  if (!ticket) return;
  const requestType = $("#holdingRequestType").value;
  const startDate = $("#holdingStartDate").value;
  const endDate = $("#holdingEndDate").value;
  const reason = $("#holdingReason").value.trim();
  const file = $("#holdingEvidenceFile").files?.[0] || null;
  const consent = $("#holdingSensitiveConsent").checked;
  const policy = memberHoldingPolicy();
  const days = holdingRequestDays(startDate, endDate);
  const maxDays = requestType === "injury" ? Number(policy.injuryMaxDays) : Number(policy.personalMaxDays);
  if (requestType === "personal" && maxDays <= 0) {
    message.textContent = "쿠폰제는 개인 사유 홀딩을 제공하지 않습니다. 부상·입원은 증빙과 함께 신청할 수 있습니다.";
    return;
  }
  const message = $("#holdingRequestMessage");
  if (!days || days > maxDays) {
    message.textContent = `${requestType === "injury" ? "부상" : "개인 사유"} 홀딩은 최대 ${maxDays}일까지 신청할 수 있습니다.`;
    return;
  }
  if (requestType === "injury" && policy.evidenceRequired && !file) {
    message.textContent = "부상 홀딩은 진단서 또는 진료확인서를 첨부해 주세요.";
    return;
  }
  const allowedEvidenceTypes = ["application/pdf", "image/jpeg", "image/png", "image/webp"];
  if (file && !allowedEvidenceTypes.includes(file.type)) {
    message.textContent = "PDF·JPG·PNG·WEBP 파일만 첨부할 수 있습니다.";
    return;
  }
  if (file && file.size > 5 * 1024 * 1024) {
    message.textContent = "첨부파일은 5MB 이하만 가능합니다.";
    return;
  }
  if (requestType === "injury" && !consent) {
    message.textContent = "건강정보 처리 안내를 확인하고 동의해 주세요.";
    return;
  }
  if (requestType === "personal" && memberHoldingRequests().some((request) => request.ticketId === ticket.id && request.type === "personal" && request.status === "approved")) {
    message.textContent = "이 회원권은 개인 사유 홀딩을 이미 사용했습니다.";
    return;
  }
  if (memberHoldingRequests().some((request) => request.ticketId === ticket.id && request.status === "pending")) {
    message.textContent = "이미 검토 중인 홀딩 요청이 있습니다.";
    return;
  }

  const requestId = globalThis.crypto?.randomUUID?.() || `holding-${Date.now()}`;
  const client = window.TennisNoteDataClient;
  let evidencePath = "";
  const isLive = !ticket.id.startsWith("demo-") && state.member?.profileId && client?.getSession?.()?.access_token;
  try {
    if (isLive && requestType === "injury" && file) {
      evidencePath = `${state.member.profileId}/${requestId}/${safeHoldingFileName(file.name)}`;
      await client.uploadObject("tennisnote-private-holding-evidence", evidencePath, file);
    }
    if (isLive) {
      await client.insertRows("tn_holding_requests", {
        id: requestId,
        branch_id: ticket.branchId,
        user_id: state.member.profileId,
        ticket_id: ticket.id,
        request_type: requestType,
        requested_start_on: startDate,
        requested_end_on: endDate,
        reason_summary: reason,
        evidence_object_path: evidencePath,
        evidence_status: requestType === "injury" ? "uploaded" : "not_required",
        sensitive_consent_at: requestType === "injury" ? new Date().toISOString() : null,
        evidence_purge_due_at: requestType === "injury" ? new Date(Date.now() + Number(policy.evidenceRetentionDays) * 86400000).toISOString() : null,
      });
    }
  } catch {
    if (evidencePath && client?.deleteObject) {
      await client.deleteObject("tennisnote-private-holding-evidence", evidencePath).catch(() => {});
    }
    message.textContent = "서버 신청을 저장하지 못했습니다. 관리자에게 문의해 주세요.";
    return;
  }

  const shared = loadSharedData();
  shared.holdingRequests = shared.holdingRequests || [];
  shared.holdingRequests.unshift({
    id: requestId,
    member: state.member?.name || state.profile.name,
    ticketId: ticket.id,
    ticketTitle: ticket.title,
    type: requestType,
    typeLabel: requestType === "injury" ? "부상·입원" : "개인 사유",
    startDate,
    endDate,
    days,
    reason,
    evidencePath: isLive ? evidencePath : "",
    evidenceLabel: requestType === "injury" ? "증빙 첨부" : "증빙 없음",
    status: "pending",
    source: isLive ? "server" : "demo",
    createdAt: new Date().toISOString(),
  });
  saveSharedData(shared);
  state.ticketHistory.unshift({ text: `홀딩 신청 · ${startDate}~${endDate} · 관리자 검토중`, tone: "wait" });
  saveSnapshot();
  window.TennisNoteInputGuard?.markSaved?.("#holdingRequestModal");
  closeHoldingRequestModal();
  state.selectedHoldingTicketId = "";
  renderCurrentTicketPanel();
}

