async function syncMemberEnrollmentFromServer(profile = null) {
  const client = window.TennisNoteDataClient;
  const profileId = profile?.id || state.member?.profileId || "";
  if (!client?.selectRows || !client.readiness?.().ready || !profileId) return false;
  try {
    const rows = await client.selectRows("tn_member_enrollments", {
      select: "id,user_id,branch_id,requested_product_id,form_version,status,applicant_name,phone,birth_year,neighborhood,gender,experience_level,lesson_goal,preferred_schedule,group_size,partner_name,partner_phone,partner_birth_year,partner_neighborhood,partner_gender,submitted_at,approved_at,updated_at",
      filters: { user_id: profileId },
      limit: 20,
    });
    state.memberEnrollment = (rows || [])
      .filter((row) => row.form_version === memberEnrollmentFormVersion)
      .sort((left, right) => new Date(right.submitted_at || 0) - new Date(left.submitted_at || 0))[0] || null;
    return true;
  } catch {
    state.memberEnrollment = null;
    return false;
  }
}

async function submitMemberEnrollment(event) {
  event.preventDefault();
  const product = membershipProducts().find((item) => item.id === state.pendingPurchaseProductId);
  const message = $("#memberEnrollmentMessage");
  if (!product || !message) return;
  const isGroup = isGroupMembershipProduct(product);
  const birthYear = Number($("#enrollmentBirthYear")?.value || 0);
  const partnerBirthYear = Number($("#enrollmentPartnerBirthYear")?.value || 0) || null;
  const maxBirthYear = new Date().getFullYear() - 5;
  const payload = {
    target_product_id: product.id,
    target_form_version: memberEnrollmentFormVersion,
    target_applicant_name: $("#enrollmentName")?.value.trim() || "",
    target_phone: $("#enrollmentPhone")?.value.trim() || "",
    target_birth_year: birthYear,
    target_neighborhood: $("#enrollmentNeighborhood")?.value.trim() || "",
    target_gender: $("#enrollmentGender")?.value || "",
    target_experience_level: memberEnrollmentLegacyDefaults.experienceLevel,
    target_lesson_goal: memberEnrollmentLegacyDefaults.lessonGoal,
    target_preferred_schedule: memberEnrollmentLegacyDefaults.preferredSchedule,
    target_partner_name: isGroup ? $("#enrollmentPartnerName")?.value.trim() || "" : "",
    target_partner_phone: isGroup ? $("#enrollmentPartnerPhone")?.value.trim() || "" : "",
    target_partner_birth_year: isGroup ? partnerBirthYear : null,
    target_partner_neighborhood: isGroup ? $("#enrollmentPartnerNeighborhood")?.value.trim() || "" : "",
    target_partner_gender: isGroup ? $("#enrollmentPartnerGender")?.value || "" : "",
    target_privacy_consent: Boolean($("#enrollmentPrivacyConsent")?.checked),
    target_terms_consent: Boolean($("#enrollmentTermsConsent")?.checked),
  };
  if (!payload.target_applicant_name || payload.target_phone.replace(/\D/g, "").length < 9) {
    message.textContent = "이름과 연락처를 확인해 주세요.";
    return;
  }
  if (birthYear < 1900 || birthYear > maxBirthYear) {
    message.textContent = "출생연도를 확인해 주세요.";
    return;
  }
  if (isGroup && (!payload.target_partner_name || payload.target_partner_phone.replace(/\D/g, "").length < 9)) {
    message.textContent = "2대1 파트너 이름과 연락처를 입력해 주세요.";
    return;
  }
  if (!payload.target_privacy_consent || !payload.target_terms_consent) {
    message.textContent = "필수 안내 두 가지를 확인하고 동의해 주세요.";
    return;
  }

  const submitButton = $("#memberEnrollmentForm button[type='submit']");
  if (submitButton) submitButton.disabled = true;
  message.textContent = "가입서를 안전하게 저장하는 중입니다.";
  try {
    const client = window.TennisNoteDataClient;
    if (hasLiveMemberSession() && client?.rpc) {
      await client.rpc("tn_submit_member_enrollment", payload);
      if (state.member) state.member.memberKind = state.member.memberKind === "lesson_member" ? "lesson_member" : "lesson_pending";
      await syncMemberEnrollmentFromServer();
    } else {
      state.memberEnrollment = {
        id: `demo-enrollment-${Date.now()}`,
        user_id: state.member?.profileId || "demo-member",
        requested_product_id: product.id,
        form_version: memberEnrollmentFormVersion,
        status: "submitted",
        applicant_name: payload.target_applicant_name,
        phone: payload.target_phone,
        birth_year: payload.target_birth_year,
        neighborhood: payload.target_neighborhood,
        gender: payload.target_gender,
        experience_level: payload.target_experience_level,
        lesson_goal: payload.target_lesson_goal,
        preferred_schedule: payload.target_preferred_schedule,
        group_size: isGroup ? 2 : 1,
        partner_name: payload.target_partner_name,
        partner_phone: payload.target_partner_phone,
        submitted_at: new Date().toISOString(),
      };
      if (state.member) state.member.memberKind = "lesson_pending";
    }
    state.profile.name = payload.target_applicant_name;
    // An enrollment answer does not verify or replace canonical identity contact.
    if (!hasLiveMemberSession()) state.profile.phone = payload.target_phone;
    state.ticketHistory.unshift({ text: `${product.title} 수강 가입서 제출 완료`, tone: "done" });
    saveSnapshot();
    renderAll();
    window.TennisNoteInputGuard?.markSaved?.("#memberEnrollmentModal");
    closeMemberEnrollmentModal();
    if (hasLiveMemberSession()) {
      await startProductPayment(product.id, { skipEnrollmentGate: true });
    } else {
      state.pendingPaymentCheckStatus = { tone: "done", text: "데모 가입서 제출 완료 · 실제 로그인 후 결제로 이어집니다." };
      renderAll();
      setView("shopView");
    }
  } catch (error) {
    message.textContent = memberEnrollmentErrorMessage(error);
  } finally {
    if (submitButton) submitButton.disabled = false;
  }
}

const membershipPurchaseSteps = ["상품", "코치·시간", "결제"];

function purchaseFlowState() {
  if (!state.purchaseFlow || typeof state.purchaseFlow !== "object") {
    state.purchaseFlow = {
      open: false,
      step: 1,
      familyId: "four-week",
      productId: "",
      renewalTicketId: "",
      purchasePurpose: "",
      showMoreSlots: false,
      showAllProducts: false,
      productFrequency: 1,
      productScheduleScope: "weekday",
      scheduleMode: "keep",
      scheduleWeekStart: "",
      scheduleAvailableOnly: false,
      coachRoleId: "",
      coachName: "",
      preferredDate: "",
      preferredDay: "",
      preferredTime: "",
      preferredSchedules: [],
      discountIssueId: "",
      discountSelectionMode: "auto",
      completionStatus: "",
    };
  }
  state.purchaseFlow.familyId = membershipProductFamilyDefinition(state.purchaseFlow.familyId).id;
  state.purchaseFlow.purchasePurpose = String(state.purchaseFlow.purchasePurpose || "");
  state.purchaseFlow.showMoreSlots = state.purchaseFlow.showMoreSlots === true;
  state.purchaseFlow.showAllProducts = state.purchaseFlow.showAllProducts === true;
  state.purchaseFlow.productFrequency = Math.max(1, Math.min(3, Number(state.purchaseFlow.productFrequency) || 1));
  state.purchaseFlow.productScheduleScope = ["weekday", "weekend"].includes(state.purchaseFlow.productScheduleScope)
    ? state.purchaseFlow.productScheduleScope
    : "weekday";
  state.purchaseFlow.scheduleWeekStart = String(state.purchaseFlow.scheduleWeekStart || "");
  state.purchaseFlow.scheduleAvailableOnly = state.purchaseFlow.scheduleAvailableOnly === true;
  state.purchaseFlow.preferredDate = String(state.purchaseFlow.preferredDate || "");
  state.purchaseFlow.preferredSchedules = Array.isArray(state.purchaseFlow.preferredSchedules)
    ? state.purchaseFlow.preferredSchedules
      .filter((schedule) => schedule && typeof schedule === "object")
      .map((schedule) => ({
        lessonDate: String(schedule.lessonDate || schedule.lesson_date || ""),
        day: String(schedule.day || schedule.preferredDay || ""),
        startTime: String(schedule.startTime || schedule.preferredTime || "").slice(0, 5),
        coachRoleId: String(schedule.coachRoleId || schedule.coach_role_id || ""),
        coachName: String(schedule.coachName || ""),
        durationMinutes: Math.max(10, Number(schedule.durationMinutes) || 20),
      }))
      .filter((schedule) => schedule.lessonDate && schedule.startTime && schedule.coachRoleId)
    : [];
  state.purchaseFlow.discountIssueId = String(state.purchaseFlow.discountIssueId || "");
  state.purchaseFlow.discountSelectionMode = state.purchaseFlow.discountSelectionMode === "manual" ? "manual" : "auto";
  state.purchaseFlow.paymentErrorCode = String(state.purchaseFlow.paymentErrorCode || "");
  state.purchaseFlow.paymentErrorMessage = String(state.purchaseFlow.paymentErrorMessage || "");
  return state.purchaseFlow;
}

function purchaseFlowSourceTicket() {
  const flow = purchaseFlowState();
  return (state.liveTickets || []).find((ticket) => String(ticket.id || "") === String(flow.renewalTicketId || "")) || null;
}

function purchaseFlowProduct() {
  const flow = purchaseFlowState();
  return membershipProducts().find((product) => (
    String(product.id || "") === String(flow.productId || "")
    && isDirectPurchaseMembershipProduct(product)
  )) || null;
}

function purchaseTicketLesson(ticket = {}) {
  return (state.liveLessons || []).find((lesson) => (
    String(lesson.ticketId || lesson.memberTicketId || lesson.member_ticket_id || "") === String(ticket.id || "")
    && !["cancelled", "canceled", "absent"].includes(String(lesson.status || "").toLowerCase())
  )) || null;
}

function purchaseDirectoryContext(product = purchaseFlowProduct()) {
  const sourceTicket = purchaseFlowSourceTicket();
  const branchId = String(product?.branchId || sourceTicket?.branchId || sourceTicket?.branch_id || "");
  const week = purchaseScheduleWeek();
  const rangeStart = new Date(`${week.startDate}T12:00:00`);
  const rangeEnd = new Date(rangeStart);
  rangeEnd.setDate(rangeStart.getDate() + memberScheduleWorkspaceDays);
  const from = localDateKey(rangeStart);
  const to = localDateKey(rangeEnd);
  return {
    branchId,
    from,
    to,
    key: `${branchId}:${from}:${to}`,
  };
}

function purchaseDirectoryForCurrentProduct(product = purchaseFlowProduct()) {
  const context = purchaseDirectoryContext(product);
  if (!memberPurchaseDirectoryCache || memberPurchaseDirectoryCache.key !== context.key) return null;
  return memberPurchaseDirectoryCache.directory || null;
}

function normalizePurchaseDirectoryCoach(coach = {}, coachIndex = 0) {
  const availability = Array.isArray(coach.availability) ? coach.availability : [];
  const workBlocks = availability
    .filter((block) => String(block.type || "available") === "available")
    .map((block, blockIndex) => ({
      id: `${coach.roleId || coach.id || "coach"}-purchase-${blockIndex}`,
      days: [days[Number(block.dayOfWeek) === 0 ? 6 : Number(block.dayOfWeek) - 1]].filter(Boolean),
      start: String(block.startTime || "").slice(0, 5),
      end: String(block.endTime || "").slice(0, 5),
      label: "근무",
    }))
    .filter((block) => block.days.length && minutesFromTime(block.start) < minutesFromTime(block.end));
  const blockedBlocks = availability
    .filter((block) => String(block.type || "") === "blocked")
    .map((block, blockIndex) => ({
      id: `${coach.roleId || coach.id || "coach"}-purchase-blocked-${blockIndex}`,
      days: [days[Number(block.dayOfWeek) === 0 ? 6 : Number(block.dayOfWeek) - 1]].filter(Boolean),
      start: String(block.startTime || "").slice(0, 5),
      end: String(block.endTime || "").slice(0, 5),
      label: block.note || "브레이크·상담",
    }))
    .filter((block) => block.days.length && minutesFromTime(block.start) < minutesFromTime(block.end));
  const serverLaneOrder = Number(coach.laneOrder);
  const laneOrder = Number.isFinite(serverLaneOrder) ? serverLaneOrder : 1000 + coachIndex;
  return normalizeMemberCoach({
    id: coach.roleId || coach.id,
    serverRoleId: coach.roleId || coach.id,
    roleId: coach.roleId || coach.id,
    branchId: coach.branchId || "",
    name: coach.name || "이름 없음",
    status: "approved",
    employmentStatus: "active",
    laneOrder,
    scheduleLaneOrder: laneOrder,
    workBlocks,
    blockedBlocks,
  });
}

function purchaseDirectoryCoaches(product = purchaseFlowProduct()) {
  const directory = purchaseDirectoryForCurrentProduct(product);
  return (directory?.coaches || []).map(normalizePurchaseDirectoryCoach);
}

function purchaseSchedulePolicy(product = purchaseFlowProduct()) {
  const fallback = loadAdminSchedulePolicy();
  const directory = purchaseDirectoryForCurrentProduct(product);
  if (!directory) return fallback;
  const breakRules = (directory.breakRules || []).map((rule, ruleIndex) => ({
    id: rule.id || `purchase-break-${ruleIndex}`,
    days: [days[Number(rule.dayOfWeek) === 0 ? 6 : Number(rule.dayOfWeek) - 1]].filter(Boolean),
    start: String(rule.startTime || "").slice(0, 5),
    end: String(rule.endTime || "").slice(0, 5),
    label: rule.label || "브레이크타임",
  })).filter((rule) => rule.days.length && minutesFromTime(rule.start) < minutesFromTime(rule.end));
  return {
    ...fallback,
    openStart: String(directory.openStart || fallback.openStart || "06:40").slice(0, 5),
    openEnd: String(directory.openEnd || fallback.openEnd || "22:00").slice(0, 5),
    breakRules,
    coaches: purchaseDirectoryCoaches(product),
  };
}

function purchaseOccupancyLessons(product = purchaseFlowProduct()) {
  const directory = purchaseDirectoryForCurrentProduct(product);
  if (!directory) return state.liveLessons || [];
  return (directory.occupancy || []).map((occupied, index) => ({
    id: `purchase-occupancy-${index}-${occupied.lessonDate || ""}-${occupied.startTime || ""}-${occupied.coachRoleId || ""}`,
    lessonDate: String(occupied.lessonDate || ""),
    time: String(occupied.startTime || "").slice(0, 5),
    coachRoleId: String(occupied.coachRoleId || ""),
    coach_role_id: String(occupied.coachRoleId || ""),
    durationMinutes: Math.max(10, Number(occupied.durationMinutes) || 20),
    status: "occupied",
    serverStatus: "occupied",
  }));
}

function purchaseCoachOptions() {
  if (state.dataMode === "live") {
    return purchaseDirectoryCoaches()
      .filter((coach) => ["active", "approved"].includes(String(coach.status || "active").toLowerCase()))
      .filter((coach) => String(coach.employmentStatus || coach.employment_status || "active").toLowerCase() === "active")
      .filter((coach) => !coach.archivedAt && !coach.archived_at && !coach.deletedAt && !coach.deleted_at)
      .sort((left, right) => memberScheduleLaneOrder(left) - memberScheduleLaneOrder(right));
  }
  const policy = loadAdminSchedulePolicy();
  return (policy.coaches || [])
    .filter((coach) => ["active", "approved"].includes(String(coach.status || "active").toLowerCase()))
    .filter((coach) => String(coach.employmentStatus || coach.employment_status || "active").toLowerCase() === "active")
    .filter((coach) => !coach.archivedAt && !coach.archived_at && !coach.deletedAt && !coach.deleted_at)
    .sort((left, right) => memberScheduleLaneOrder(left) - memberScheduleLaneOrder(right));
}

function purchaseProductAllowsCoach(product = {}, coachRoleId = "") {
  const roleId = String(coachRoleId || "");
  if (!roleId) return false;
  const coachSaleMode = String(product.coachSaleMode || "all_active") === "selected" ? "selected" : "all_active";
  if (coachSaleMode === "all_active") return true;
  return product.coachSaleAvailability?.[roleId] === true;
}

function purchaseProductDisplayTitle(product = {}) {
  const title = String(product.title || "회원권");
  if (membershipProductFamilyId(product) !== "coupon") return title;
  return title.replace(/(^|\s)(평일|주말)(?=\s|$)/g, " ").replace(/\s{2,}/g, " ").trim() || "쿠폰 레슨";
}

function couponEquivalentProducts(product = {}) {
  if (membershipProductFamilyId(product) !== "coupon") return [product];
  const offerKey = couponProductOfferKey(product);
  return membershipProductsForFamily("coupon").filter((candidate) => couponProductOfferKey(candidate) === offerKey);
}

function purchaseProductScheduleScopes(product = {}) {
  const products = membershipProductFamilyId(product) === "coupon" ? couponEquivalentProducts(product) : [product];
  const scopes = new Set();
  products.forEach((candidate) => {
    const scope = membershipProductFacet(candidate, "scheduleScope");
    if (scope === "mixed") {
      scopes.add("weekday");
      scopes.add("weekend");
    } else {
      scopes.add(scope);
    }
  });
  return scopes;
}

function purchaseProductForScheduleSlot(product = {}, slot = {}) {
  if (membershipProductFamilyId(product) !== "coupon") return product;
  const targetScope = ["토", "일"].includes(slot.day) ? "weekend" : "weekday";
  const equivalents = couponEquivalentProducts(product);
  return equivalents.find((candidate) => membershipProductFacet(candidate, "scheduleScope") === "mixed")
    || equivalents.find((candidate) => membershipProductFacet(candidate, "scheduleScope") === targetScope)
    || null;
}

function purchaseDateDay(dateKey = "") {
  const value = new Date(`${dateKey}T12:00:00`);
  if (Number.isNaN(value.getTime())) return "";
  return days[value.getDay() === 0 ? 6 : value.getDay() - 1] || "";
}

function purchaseDateLabel(dateKey = "") {
  const [, month, date] = String(dateKey).split("-");
  const day = purchaseDateDay(dateKey);
  return month && date ? `${Number(month)}/${Number(date)}(${day})` : day;
}

function purchaseProductFrequency(product = {}) {
  return Math.max(1, Number(product.frequencyPerWeek || product.frequency_per_week) || 1);
}

function purchaseWeekStartDate(dateKey = "") {
  const value = new Date(`${dateKey || localDateKey()}T12:00:00`);
  if (Number.isNaN(value.getTime())) return purchaseWeekStartDate(localDateKey());
  const day = value.getDay();
  value.setDate(value.getDate() + (day === 0 ? -6 : 1 - day));
  return localDateKey(value);
}

function purchaseWeekDates(weekStart = "") {
  const start = new Date(`${purchaseWeekStartDate(weekStart)}T12:00:00`);
  return Array.from({ length: 7 }, (_, index) => {
    const value = new Date(start);
    value.setDate(start.getDate() + index);
    return localDateKey(value);
  });
}

function purchaseScheduleScopeDates(product = purchaseFlowProduct(), weekStart = purchaseFlowState().scheduleWeekStart) {
  const scopes = purchaseProductScheduleScopes(product || {});
  return purchaseWeekDates(weekStart).filter((dateKey) => {
    const weekend = ["토", "일"].includes(purchaseDateDay(dateKey));
    return scopes.has(weekend ? "weekend" : "weekday");
  });
}

function purchaseScheduleSelectionWeek(schedules = purchaseSelectedSchedules()) {
  return schedules.length ? purchaseWeekStartDate(schedules[0].lessonDate) : "";
}

function purchaseEffectiveStartDate() {
  const sourceTicket = purchaseFlowSourceTicket();
  if (purchaseFlowState().purchasePurpose !== "renew_same" || !sourceTicket?.expiresOn) return localDateKey();
  const nextDate = new Date(`${sourceTicket.expiresOn}T12:00:00`);
  if (Number.isNaN(nextDate.getTime())) return localDateKey();
  nextDate.setDate(nextDate.getDate() + 1);
  return [localDateKey(), localDateKey(nextDate)].sort().slice(-1)[0] || localDateKey();
}

function purchaseScheduleWeek() {
  return memberScheduleWeekForOffset(memberWeekOffsetForDate(purchaseEffectiveStartDate()));
}

function purchaseAvailabilityRange() {
  const today = purchaseEffectiveStartDate();
  const workspace = purchaseDirectoryForCurrentProduct() || memberScheduleV2WorkspaceCache?.workspace || {};
  const start = [today, String(workspace.from || "")].filter(Boolean).sort().slice(-1)[0] || today;
  const defaultEndDate = new Date(`${start}T12:00:00`);
  defaultEndDate.setDate(defaultEndDate.getDate() + 20);
  const defaultEnd = localDateKey(defaultEndDate);
  const end = workspace.to && String(workspace.to) < defaultEnd ? String(workspace.to) : defaultEnd;
  return { start, end };
}

function purchaseScheduleOperationForDate(dateKey = "") {
  const directory = purchaseDirectoryForCurrentProduct();
  const operationDays = Array.isArray(directory?.operationDays) ? directory.operationDays : state.scheduleOperationDays || [];
  return operationDays.find((operation) => String(operation.date || "") === dateKey) || null;
}

function purchaseOperationAllowsSlot(operation, time, durationMinutes) {
  if (!operation) return true;
  const mode = String(operation.mode || "normal");
  if (mode === "closed") return false;
  if (mode !== "shortened") return true;
  const start = String(operation.startTime || operation.start_time || "").slice(0, 5);
  const end = String(operation.endTime || operation.end_time || "").slice(0, 5);
  if (!start || !end) return false;
  return minutesFromTime(time) >= minutesFromTime(start)
    && minutesFromTime(time) + durationMinutes <= minutesFromTime(end);
}

function purchaseHasCoachLessonAtDate(scheduleLessons, lessonDate, time, coach, durationMinutes, policy) {
  const slotStart = minutesFromTime(time);
  const slotEnd = slotStart + durationMinutes;
  return scheduleLessons.some((lesson) => {
    if (lesson.status === "available" || String(lesson.lessonDate || "") !== lessonDate) return false;
    const lessonStatus = String(lesson.serverStatus || lesson.status || "").toLowerCase();
    if (["cancelled", "canceled", "absence", "absent", "makeup_due"].includes(lessonStatus)) return false;
    const lessonCoachRoleId = String(lesson.coachRoleId || lesson.coach_role_id || memberLessonCoach(lesson, policy).id || "");
    const coachRoleId = String(coach.serverRoleId || coach.roleId || coach.id || "");
    if (lessonCoachRoleId !== coachRoleId) return false;
    const lessonStart = minutesFromTime(lesson.time);
    const lessonEnd = lessonStart + lessonDuration(lesson);
    return slotStart < lessonEnd && slotEnd > lessonStart;
  });
}

function purchaseScheduleAvailabilityState() {
  if (state.dataMode !== "live" || !state.member?.profileId) return "ready";
  const context = purchaseDirectoryContext();
  if (memberPurchaseDirectoryLoad.key !== context.key || memberPurchaseDirectoryLoad.status === "idle") return "loading";
  if (memberPurchaseDirectoryLoad.status === "error") return "error";
  if (memberPurchaseDirectoryLoad.status !== "ready") return "loading";
  const directory = purchaseDirectoryForCurrentProduct();
  if (!Array.isArray(directory?.coaches) || !directory.coaches.length) return "coach_error";
  return "ready";
}

function purchaseUsesFlexibleCouponSchedule(product = purchaseFlowProduct(), flow = purchaseFlowState()) {
  return Boolean(
    product
    && membershipProductFacet(product, "productKind") === "coupon"
    && flow.purchasePurpose !== "one_day"
  );
}

function purchaseRequiredScheduleCount(product = purchaseFlowProduct()) {
  if (!product) return 1;
  if (purchaseUsesFlexibleCouponSchedule(product)) return 0;
  if (membershipProductFacet(product, "productKind") === "coupon") return 1;
  return Math.max(1, Number(product.frequencyPerWeek) || 1);
}

function purchaseSelectedSchedules(product = purchaseFlowProduct()) {
  const flow = purchaseFlowState();
  const durationMinutes = Math.max(10, Number(product?.lessonMinutes) || 20);
  const coachRoleId = String(flow.coachRoleId || "");
  return flow.preferredSchedules
    .filter((schedule) => !coachRoleId || String(schedule.coachRoleId) === coachRoleId)
    .map((schedule) => ({ ...schedule, durationMinutes }));
}

function clearPurchaseSchedules() {
  const flow = purchaseFlowState();
  flow.preferredSchedules = [];
  flow.preferredDate = "";
  flow.preferredDay = "";
  flow.preferredTime = "";
}

function syncLegacyPurchaseScheduleFields() {
  const flow = purchaseFlowState();
  const first = flow.preferredSchedules[0] || null;
  flow.preferredDate = first?.lessonDate || "";
  flow.preferredDay = first?.day || purchaseDateDay(first?.lessonDate || "");
  flow.preferredTime = first?.startTime || "";
}

function purchaseAvailableScheduleSlots(product = purchaseFlowProduct()) {
  if (!product || purchaseScheduleAvailabilityState() !== "ready") return [];
  const policy = purchaseSchedulePolicy(product);
  const sourceTicket = purchaseFlowSourceTicket();
  const durationMinutes = Math.max(10, Number(product.lessonMinutes) || 20);
  const scopes = purchaseProductScheduleScopes(product);
  const scheduleLessons = purchaseOccupancyLessons(product);
  const { start, end } = purchaseAvailabilityRange();
  const now = Date.now();
  const sourceCoachId = purchaseFlowState().purchasePurpose === "renew_same"
    ? String(sourceTicket?.coachRoleId || "")
    : "";
  const coaches = purchaseCoachOptions().filter((coach) => {
    const roleId = String(coach.serverRoleId || coach.roleId || coach.id || "");
    if (!purchaseProductAllowsCoach(product, roleId)) return false;
    if (!sourceCoachId) return true;
    return roleId === sourceCoachId;
  });
  const slots = [];
  for (let dateKey = start; dateKey <= end;) {
    const day = purchaseDateDay(dateKey);
    const dateScope = ["토", "일"].includes(day) ? "weekend" : "weekday";
    const operation = purchaseScheduleOperationForDate(dateKey);
    if (scopes.has(dateScope)
      && !(durationMinutes === 30 && dateScope === "weekend")
      && operation?.mode !== "closed") {
      coaches.forEach((coach) => {
        memberCoachBookableTimes(coach, day, durationMinutes).forEach((time) => {
          if (new Date(`${dateKey}T${time}:00`).getTime() <= now) return;
          if (!purchaseOperationAllowsSlot(operation, time, durationMinutes)) return;
          if (memberBreakRuleOverlaps(policy, day, time, durationMinutes)) return;
          if (!isMemberCoachWorking(coach, day, time, durationMinutes)) return;
          if (purchaseHasCoachLessonAtDate(scheduleLessons, dateKey, time, coach, durationMinutes, policy)) return;
          if (!purchaseSlotInsideAnchorWindow(scheduleLessons, product, dateKey, time, coach, policy)) return;
          const roleId = String(coach.serverRoleId || coach.roleId || coach.id || "");
          if (!roleId) return;
          slots.push({
            id: `purchase-slot-${dateKey}-${time}-${roleId}`,
            lessonDate: dateKey,
            day,
            time,
            coachRoleId: roleId,
            coachName: coach.name || "담당 코치",
          });
        });
      });
    }
    const next = new Date(`${dateKey}T12:00:00`);
    next.setDate(next.getDate() + 1);
    dateKey = localDateKey(next);
  }
  return slots.sort((left, right) => (
    `${left.lessonDate} ${left.time}`.localeCompare(`${right.lessonDate} ${right.time}`)
    || left.coachName.localeCompare(right.coachName, "ko")
  ));
}

function purchaseEarliestScheduleWeekStart(coachRoleId = "", product = purchaseFlowProduct()) {
  const targetCoachRoleId = String(coachRoleId || "");
  const firstAvailable = purchaseAvailableScheduleSlots(product).find((slot) => (
    !targetCoachRoleId || String(slot.coachRoleId) === targetCoachRoleId
  ));
  return purchaseWeekStartDate(firstAvailable?.lessonDate || purchaseAvailabilityRange().start);
}

function alignPurchaseScheduleWeekToAvailability(product = purchaseFlowProduct()) {
  const flow = purchaseFlowState();
  const selectedWeek = purchaseScheduleSelectionWeek(purchaseSelectedSchedules(product));
  if (selectedWeek) {
    const changed = flow.scheduleWeekStart !== selectedWeek;
    flow.scheduleWeekStart = selectedWeek;
    return changed;
  }
  if (!product || purchaseScheduleAvailabilityState() !== "ready") return false;
  const coachRoleId = String(flow.coachRoleId || "");
  const currentWeek = purchaseWeekStartDate(flow.scheduleWeekStart || purchaseAvailabilityRange().start);
  const matchingSlots = purchaseAvailableScheduleSlots(product).filter((slot) => (
    !coachRoleId || String(slot.coachRoleId) === coachRoleId
  ));
  const currentWeekHasSlot = matchingSlots.some((slot) => purchaseWeekStartDate(slot.lessonDate) === currentWeek);
  const nextWeek = currentWeekHasSlot
    ? currentWeek
    : purchaseWeekStartDate(matchingSlots[0]?.lessonDate || purchaseAvailabilityRange().start);
  const changed = flow.scheduleWeekStart !== nextWeek;
  flow.scheduleWeekStart = nextWeek;
  return changed;
}

function purchaseScheduleKey(schedule = {}) {
  return `${schedule.lessonDate || ""}:${String(schedule.startTime || schedule.time || "").slice(0, 5)}:${schedule.coachRoleId || ""}`;
}

function purchaseSchedulesAvailableNow(product = purchaseFlowProduct()) {
  const selectedSchedules = purchaseSelectedSchedules(product);
  if (!selectedSchedules.length || purchaseScheduleAvailabilityState() !== "ready") return false;
  const availableKeys = new Set(purchaseAvailableScheduleSlots(product).map((slot) => purchaseScheduleKey({
    lessonDate: slot.lessonDate,
    startTime: slot.time,
    coachRoleId: slot.coachRoleId,
  })));
  return selectedSchedules.every((schedule) => availableKeys.has(purchaseScheduleKey(schedule)));
}

function reconcilePurchaseSchedulesAfterRefresh(product = purchaseFlowProduct()) {
  const flow = purchaseFlowState();
  if (!product || !flow.preferredSchedules.length || purchaseScheduleAvailabilityState() !== "ready") return 0;
  const availableSlots = purchaseAvailableScheduleSlots(product);
  const availableKeys = new Set(availableSlots.map((slot) => purchaseScheduleKey({
    lessonDate: slot.lessonDate,
    startTime: slot.time,
    coachRoleId: slot.coachRoleId,
  })));
  const previous = [...flow.preferredSchedules];
  flow.preferredSchedules = previous.filter((schedule) => availableKeys.has(purchaseScheduleKey(schedule)));
  const removedCount = previous.length - flow.preferredSchedules.length;
  if (!removedCount) return 0;
  const selectedCoachSlots = availableSlots.filter((slot) => String(slot.coachRoleId) === String(flow.coachRoleId || ""));
  const firstAvailable = selectedCoachSlots[0] || availableSlots[0] || null;
  if (!flow.preferredSchedules.length && firstAvailable) {
    flow.scheduleWeekStart = purchaseWeekStartDate(firstAvailable.lessonDate);
  }
  syncLegacyPurchaseScheduleFields();
  saveSnapshot();
  return removedCount;
}

function purchaseCoachSelectionHtml(product = purchaseFlowProduct()) {
  const flow = purchaseFlowState();
  const status = purchaseScheduleAvailabilityState();
