  const amount = purchasePaymentAmount(product, paymentMethod.id);
  const validityLabel = Number(product.validityDays || 0) > 0 ? `사용 ${Number(product.validityDays)}일` : "";
  const lessonFormat = Number(product.groupSize || 1) > 1 ? `${Number(product.groupSize)}대1` : "1대1";
  return `
    <button class="purchase-product-option ${selected ? "is-selected" : ""}" type="button" data-purchase-product="${escapeHtml(product.id || "")}" aria-pressed="${selected}">
      <span>${escapeHtml(membershipProductFamilyDisplayLabel(family.id))} · ${escapeHtml(lessonFormat)} · ${escapeHtml(product.badge || `${product.tickets || 0}회`)}</span>
      <strong>${escapeHtml(purchaseProductDisplayTitle(product))}</strong>
      ${validityLabel ? `<small>${escapeHtml(validityLabel)}</small>` : ""}
      <b>${escapeHtml(paymentMethod.shortLabel)} ${escapeHtml(formatWon(amount))}</b>
    </button>`;
}

function memberPurchaseLifecycle() {
  if (currentLiveTickets().length) return "active";
  return latestPreviousMembershipTicket() ? "returning" : "new";
}

function purchasePurposeOptionsHtml() {
  const flow = purchaseFlowState();
  const activeTickets = currentLiveTickets();
  if (!activeTickets.length) {
    const returningTicket = latestPreviousMembershipTicket();
    const returning = Boolean(returningTicket);
    const oneDay = flow.familyId === "one-day" || membershipProductFamilyId(purchaseFlowProduct() || {}) === "one-day";
    const explicitNewPurchase = flow.purchasePurpose === "new_purchase";
    flow.purchasePurpose = oneDay ? "one_day" : explicitNewPurchase ? "new_purchase" : returning ? "renew_same" : "new_purchase";
    if (returning && flow.purchasePurpose === "renew_same" && !flow.renewalTicketId) flow.renewalTicketId = returningTicket.id || "";
    const renewal = returning && flow.purchasePurpose === "renew_same";
    const returningLabel = returning ? "재등록" : "등록";
    return `<input type="hidden" value="${escapeHtml(flow.purchasePurpose)}" /><p class="purchase-policy-note"><strong>${renewal ? returningLabel : oneDay ? "원데이" : returning ? "새 회원권 추가" : "등록"}</strong> · ${renewal ? "이전 이용 기록은 보존하고, 결제가 확인되면 같은 회원권에 횟수가 바로 추가됩니다." : returning ? "기존 이용 기록은 그대로 두고 선택한 상품을 새로 추가합니다." : "모든 활성 코치의 실제 가능한 시간을 확인할 수 있습니다."}</p>`;
  }
  const renewing = flow.purchasePurpose === "renew_same";
  const selectedTicket = purchaseFlowSourceTicket() || activeTickets[0] || null;
  const lesson = purchaseTicketLesson(selectedTicket || {});
  const coachName = selectedTicket?.coach || memberScheduleTicketCoachName(selectedTicket || {}) || "담당 코치";
  const scheduleLabel = selectedTicket && membershipProductFamilyId(selectedTicket) === "coupon"
