  const visibleFamilies = flow.purchasePurpose === "renew_same" && sourceTicket
    ? membershipPresetDefinitions.filter((family) => (
      sourceFamilyId === "coupon" ? family.id === "coupon" : ["four-week", "three-month"].includes(family.id)
    ))
