function purchaseStepCanContinue() {
  const flow = purchaseFlowState();
  const product = purchaseFlowProduct();
  const purposeReady = ["renew_same", "add_coach", "new_purchase", "one_day"].includes(flow.purchasePurpose);
  if (!purposeReady || !product || !isPaymentGatewayReady(normalizeSelectedPaymentMethod())) return false;
  if (flow.purchasePurpose === "renew_same" && purchaseFlowSourceTicket() && flow.scheduleMode === "keep") return true;
  if (purchaseUsesFlexibleCouponSchedule(product, flow)) return purchaseFlexibleCouponCoachIsReady(product);
  const schedules = purchaseSelectedSchedules(product);
  const requiredCount = purchaseRequiredScheduleCount(product);
  const selectedWeeks = new Set(schedules.map((schedule) => purchaseWeekStartDate(schedule.lessonDate)));
  return Boolean(
    flow.coachRoleId
    && schedules.length === requiredCount
    && selectedWeeks.size === 1
    && purchaseSchedulesAvailableNow(product)
    && schedules.every((schedule) => (
      schedule.lessonDate
      && schedule.day
      && schedule.startTime
      && String(schedule.coachRoleId) === String(flow.coachRoleId)
    ))
  );
}

function purchaseContinueReason() {
  const flow = purchaseFlowState();
  const product = purchaseFlowProduct();
  if (membershipPurchasePaymentInFlight) return "중복 주문 없이 결제 상태를 확인하고 있습니다.";
  if (!["renew_same", "add_coach", "new_purchase", "one_day"].includes(flow.purchasePurpose)) {
    return "연장 또는 새 이용권을 선택해 주세요.";
  }
  if (!product) return "상품을 선택해 주세요.";
  if (flow.purchasePurpose === "renew_same" && purchaseFlowSourceTicket() && flow.scheduleMode === "keep") {
    return isPaymentGatewayReady(normalizeSelectedPaymentMethod())
      ? "선택 내용을 확인한 뒤 결제할 수 있습니다."
      : "토스페이 결제를 준비하고 있습니다. 잠시 후 다시 확인해 주세요.";
  }
  const availabilityState = purchaseScheduleAvailabilityState();
  if (availabilityState === "loading") return "선생님과 가능한 시간을 최신 시간표에서 확인하고 있습니다.";
  if (availabilityState === "error" || availabilityState === "coach_error") return "선생님·시간 정보를 다시 불러온 뒤 결제할 수 있습니다.";
  if (!flow.coachRoleId) return "선생님을 선택해 주세요.";
  if (purchaseUsesFlexibleCouponSchedule(product, flow)) {
    return purchaseFlexibleCouponCoachIsReady(product)
      ? "결제 후 시간표에서 원하는 시간을 예약할 수 있습니다."
      : "선택한 담당 코치를 다시 확인해 주세요.";
  }
  const schedules = purchaseSelectedSchedules(product);
  const requiredCount = purchaseRequiredScheduleCount(product);
  if (schedules.length !== requiredCount) return `요일·시간을 ${requiredCount}개 선택해 주세요.`;
  if (!purchaseSchedulesAvailableNow(product)) return "선택한 시간이 바뀌었습니다. 최신 가능한 시간을 다시 선택해 주세요.";
  if (!isPaymentGatewayReady(normalizeSelectedPaymentMethod())) return "토스페이 결제를 준비하고 있습니다. 잠시 후 다시 확인해 주세요.";
  return "선택 내용을 확인한 뒤 결제할 수 있습니다.";
}

function purchaseSinglePageHtml() {
  const flow = purchaseFlowState();
  const product = purchaseFlowProduct();
  const sourceTicket = purchaseFlowSourceTicket();
  const keepRenewalSchedule = Boolean(
    product
    && sourceTicket
    && flow.purchasePurpose === "renew_same"
    && flow.scheduleMode === "keep"
    && membershipProductFacet(product, "productKind") !== "coupon"
  );
  const flexibleCoupon = purchaseUsesFlexibleCouponSchedule(product, flow);
  const lesson = sourceTicket ? purchaseTicketLesson(sourceTicket) : null;
  const selectedSchedules = purchaseSelectedSchedules(product);
  const selectedCoachName = flow.coachName || sourceTicket?.coach || memberScheduleTicketCoachName(sourceTicket || {}) || "";
  const scheduleSummary = keepRenewalSchedule
    ? `${memberCoachShortName(selectedCoachName || "담당 코치")} 코치 · ${lesson ? `${lesson.day || ""} ${lesson.time || ""}`.trim() : "현재 시간"} · 기존 시간 유지`
    : flexibleCoupon
      ? selectedCoachName ? `${memberCoachShortName(selectedCoachName)} 코치 · 결제 후 자유 예약` : "담당 코치를 선택해 주세요"
      : selectedSchedules.length
      ? `${memberCoachShortName(selectedCoachName || "선택한 코치")} 코치 · ${selectedSchedules.map((schedule) => `${purchaseDateLabel(schedule.lessonDate)} ${schedule.startTime}`).join(" · ")}`
      : "선생님과 시간을 선택해 주세요";
  return `
    ${purchasePurposeOptionsHtml()}
    <section class="purchase-selection-summary" aria-label="결제 선택 내용">
      <button class="purchase-selection-row" type="button" data-open-purchase-product aria-haspopup="dialog">
        <span><small>상품</small><strong>${escapeHtml(product ? purchaseProductDisplayTitle(product) : "상품을 선택해 주세요")}</strong></span><em>다시 선택</em>
      </button>
      ${product ? `<button class="purchase-selection-row" type="button" ${keepRenewalSchedule ? "data-edit-purchase-renewal-schedule" : "data-open-purchase-schedule"} aria-haspopup="dialog">
        <span><small>${flexibleCoupon ? "담당 코치" : "선생님·시간"}</small><strong>${escapeHtml(scheduleSummary)}</strong></span><em>변경</em>
      </button>
      <div class="purchase-selection-payment">${purchaseStepThreeHtml()}</div>` : ""}
    </section>`;
}

function renderMembershipPurchaseFlow() {
  const flow = purchaseFlowState();
  const container = $("#membershipPurchaseFlow");
  const browser = $("#membershipProductBrowser");
  const currentMembershipDetails = $("#currentMembershipDetails");
  const supportDetails = $("#membershipSupportDetails");
  if (!container) return;
  const purchaseFlowVisible = Boolean(flow.open && activeMemberViewId() === "shopView");
  document.body.classList.toggle("purchase-flow-open", purchaseFlowVisible);
  container.hidden = !flow.open;
  if (browser) browser.hidden = flow.open;
  if (currentMembershipDetails) currentMembershipDetails.hidden = flow.open;
  if (supportDetails) supportDetails.hidden = flow.open || supportDetails.dataset.hasContent !== "true";
  if (!flow.open) return;
  const sourceTicket = purchaseFlowSourceTicket();
  if ($("#membershipPurchaseFlowEyebrow")) $("#membershipPurchaseFlowEyebrow").textContent = flow.purchasePurpose === "renew_same"
    ? "회원권 연장"
    : sourceTicket && memberPurchaseLifecycle() === "returning" ? "회원권 재등록" : "회원권 등록";
  if ($("#membershipPurchaseFlowTitle")) $("#membershipPurchaseFlowTitle").textContent = flow.step === 4 ? "신청이 접수되었습니다" : "선택 내용을 확인하세요";
  if ($("#membershipPurchaseProgress")) {
    $("#membershipPurchaseProgress").hidden = true;
    $("#membershipPurchaseProgress").innerHTML = "";
  }
  const stepHtml = flow.step === 4 ? purchaseStepFourHtml() : purchaseSinglePageHtml();
  const canPay = purchaseStepCanContinue();
  const selectedProduct = purchaseFlowProduct();
  const payButtonLabel = membershipPurchasePaymentInFlight
    ? "처리 중"
    : selectedProduct ? `${formatWon(purchasePaymentAmount(selectedProduct, normalizeSelectedPaymentMethod()))} 결제` : "결제";
  const controls = flow.step === 4 ? "" : `
    <div class="purchase-step-actions">
      <button class="small-button" type="button" data-close-purchase-flow>취소</button>
      <div class="purchase-pay-action">
        <button class="primary-button" type="button" data-purchase-pay aria-describedby="purchasePayReason" ${canPay && !membershipPurchasePaymentInFlight ? "" : "disabled"}>${escapeHtml(payButtonLabel)}</button>
        <small id="purchasePayReason" role="status">${escapeHtml(purchaseContinueReason())}</small>
      </div>
    </div>`;
  if ($("#membershipPurchaseStep")) $("#membershipPurchaseStep").innerHTML = `${stepHtml}${controls}`;
  renderPurchasePaymentMethodSheet();
  if (!$("#purchaseProductSheet")?.hidden) renderPurchaseProductSheet();
  if (flow.step !== 4 && normalizeSelectedPaymentMethod() !== "bank_transfer") preloadPortOneSdk();
}

async function openMembershipPurchaseEntry({ purpose = "new_purchase", productId = "", renewalTicketId = "", trigger = null, preserveExplicitPurpose = false, openProductSheet = false } = {}) {
  if (membershipPurchaseEntryInFlight) return false;
  membershipPurchaseEntryInFlight = true;
  const button = trigger instanceof HTMLElement ? trigger : null;
  const originalLabel = button?.textContent || "";
  if (button) {
    button.disabled = true;
    button.setAttribute("aria-busy", "true");
    button.textContent = "회원권 확인 중";
  }
  try {
    setView("shopView", { replaceHistory: true });
    const ready = await ensureMembershipPurchaseData();
    const directProducts = membershipProducts().filter(isDirectPurchaseMembershipProduct);
    if (!ready || !directProducts.length) {
      const message = !ready
        ? "회원권 정보를 불러오지 못했습니다. 연결을 확인한 뒤 다시 시도해 주세요."
        : "현재 구매 가능한 회원권이 없습니다. 관리자에게 문의해 주세요.";
      state.pendingPaymentCheckStatus = { tone: "alert", text: message };
      renderProducts();
      showToast(message);
      return false;
    }
    let selectedProductId = productId;
    if (purpose === "one_day") {
      const oneDayProduct = directProducts
        .filter((product) => membershipProductFamilyId(product) === "one-day")
        .sort((left, right) => Number(left.displayOrder || 999) - Number(right.displayOrder || 999))[0] || null;
      if (!oneDayProduct) {
        const message = "현재 예약 가능한 원데이 상품이 없습니다. 관리자에게 문의해 주세요.";
        state.pendingPaymentCheckStatus = { tone: "alert", text: message };
        renderProducts();
        showToast(message);
        return false;
      }
      selectedProductId = oneDayProduct.id;
    }
    openMembershipPurchaseFlow(renewalTicketId, selectedProductId, purpose, { preserveExplicitPurpose });
    if (openProductSheet) openPurchaseProductSheet();
    return true;
  } catch {
    const message = "회원권 구매 화면을 열지 못했습니다. 잠시 후 다시 시도해 주세요.";
    state.pendingPaymentCheckStatus = { tone: "alert", text: message };
    window.dispatchEvent(new CustomEvent("tennisnote:client-error", {
      detail: { category: "runtime", stage: "purchase_entry", code: "purchase_entry_failed", message },
    }));
    renderProducts();
    showToast(message);
    return false;
  } finally {
    membershipPurchaseEntryInFlight = false;
    if (button?.isConnected) {
      button.disabled = false;
      button.removeAttribute("aria-busy");
      button.textContent = originalLabel;
    }
  }
}

async function openOneDayPurchaseFlow(trigger = null) {
  return openMembershipPurchaseEntry({ purpose: "one_day", trigger });
}

function openMembershipPurchaseFlow(renewalTicketId = "", productId = "", requestedPurpose = "", options = {}) {
  const flow = purchaseFlowState();
  const activeTickets = currentLiveTickets();
  const returningSource = !activeTickets.length
    && !["add_coach", "one_day"].includes(requestedPurpose)
    && !(requestedPurpose === "new_purchase" && options.preserveExplicitPurpose === true)
    ? latestPreviousMembershipTicket()
    : null;
  const requestedSource = (state.liveTickets || []).find((ticket) => String(ticket.id || "") === String(renewalTicketId || "")) || null;
  const sourceTicket = requestedSource
    || returningSource
    || (!["add_coach", "new_purchase", "one_day"].includes(requestedPurpose) ? activeTickets[0] || null : null);
  if (
    requestedPurpose === "renew_same"
    && sourceTicket
    && String(sourceTicket.productKind || "regular").toLowerCase() === "regular"
    && !["snapshot_exact", "ticket_exact"].includes(String(sourceTicket.weeklyFrequencyStatus || ""))
  ) {
    showToast("기존 회원권의 주당 횟수 기록이 일치하지 않아 연장할 수 없습니다. 관리자 확인 후 다시 시도해 주세요.");
    return false;
  }
  const sourceCanKeepSchedule = membershipTicketCanKeepSchedule(sourceTicket);
  const products = membershipProducts();
  const exactProduct = products.find((product) => (
    String(product.id || "") === String(productId || sourceTicket?.productId || "")
    && isDirectPurchaseMembershipProduct(product)
  )) || null;
  const inferredSourceFamilyId = sourceTicket ? membershipProductFamilyId({
    title: sourceTicket.title || "",
    group: sourceTicket.group || "",
    productKind: sourceTicket.productKind || "regular",
    mode: sourceTicket.productKind === "coupon" ? "pass" : "fixed",
    groupSize: sourceTicket.groupSize || 1,
    lessonMinutes: sourceTicket.lessonMinutes || 20,
    scheduleScope: sourceTicket.scheduleScope || (/주말/.test(sourceTicket.title || "") ? "weekend" : "weekday"),
  }) : "";
  const matchingProduct = exactProduct
    || (sourceTicket ? recommendedMembershipProducts(products, inferredSourceFamilyId, sourceTicket)[0] : null)
    || null;
  const lesson = sourceTicket ? purchaseTicketLesson(sourceTicket) : null;
  flow.open = true;
  flow.renewalTicketId = sourceTicket?.id || "";
  flow.productId = matchingProduct?.id || "";
  flow.familyId = matchingProduct
    ? membershipProductFamilyId(matchingProduct)
    : requestedPurpose === "one_day" ? "one-day" : activeMembershipPresetId() || "four-week";
  flow.step = 1;
  flow.purchasePurpose = ["renew_same", "add_coach", "new_purchase", "one_day"].includes(requestedPurpose)
    ? requestedPurpose
    : sourceTicket ? "renew_same" : "new_purchase";
  flow.showMoreSlots = false;
  flow.showAllProducts = false;
  flow.productFrequency = matchingProduct ? purchaseProductFrequency(matchingProduct) : 1;
  flow.productScheduleScope = matchingProduct && ["weekday", "weekend"].includes(membershipProductFacet(matchingProduct, "scheduleScope"))
    ? membershipProductFacet(matchingProduct, "scheduleScope")
    : "weekday";
  flow.scheduleMode = purchaseUsesFlexibleCouponSchedule(matchingProduct, flow)
    ? "flex"
    : sourceCanKeepSchedule && matchingProduct ? "keep" : "change";
  flow.scheduleWeekStart = purchaseWeekStartDate(lesson?.lessonDate || purchaseEffectiveStartDate());
  flow.scheduleAvailableOnly = true;
  flow.coachRoleId = sourceTicket?.coachRoleId || "";
  flow.coachName = sourceTicket?.coach || memberScheduleTicketCoachName(sourceTicket || {}) || "";
  flow.preferredDate = lesson?.lessonDate || "";
  flow.preferredDay = lesson?.day || "";
  flow.preferredTime = lesson?.time || "";
  flow.preferredSchedules = [];
  flow.discountIssueId = "";
  flow.discountSelectionMode = "auto";
  flow.paymentErrorCode = "";
  flow.paymentErrorMessage = "";
  flow.completionStatus = "";
  state.membershipFilters = { ...membershipProductFamilyDefinition(flow.familyId).filters };
  state.membershipSelectedFamilyId = flow.familyId;
  saveSnapshot();
  const historyState = typeof history.state === "object" && history.state ? history.state : {};
  if (!historyState.tennisNotePurchase) {
    history.pushState({
      ...historyState,
      tennisNoteMode: "member",
      tennisNoteView: "shopView",
      tennisNotePurchase: true,
    }, "", window.location.href);
  }
  renderMembershipPurchaseFlow();
  void ensureMembershipPurchaseData().then(() => {
    if (!purchaseFlowState().open) return false;
    renderMembershipPurchaseFlow();
    return refreshPurchaseScheduleAvailability();
  });
  window.requestAnimationFrame(() => $("#membershipPurchaseFlow")?.scrollIntoView({ block: "start" }));
}

function closeMembershipPurchaseFlow(options = {}) {
  if (options.fromHistory !== true && history.state?.tennisNotePurchase) {
    history.back();
    return;
  }
  const flow = purchaseFlowState();
  flow.open = false;
  flow.step = 1;
  flow.completionStatus = "";
  saveSnapshot();
  renderProducts();
  if (options.skipScroll === true) return;
  window.requestAnimationFrame(() => {
    const target = $("#membershipProductBrowser");
    target?.scrollIntoView({ behavior: "smooth", block: "start" });
  });
}

function purchaseSlotInsideAnchorWindow(scheduleLessons, product, lessonDate, time, coach, policy) {
  const configuredGap = Object.prototype.hasOwnProperty.call(product, "makeupAnchorMinutes")
    ? product.makeupAnchorMinutes
    : policy.makeupAnchorGapMinutes ?? 40;
  if (configuredGap === null || String(configuredGap).toLowerCase() === "unlimited") return true;
  const gapMinutes = Math.min(100, Math.max(0, Number(configuredGap) || 0));
  const coachRoleId = String(coach.serverRoleId || coach.roleId || coach.id || "");
  const anchors = scheduleLessons.filter((lesson) => {
    if (String(lesson.lessonDate || "") !== String(lessonDate || "")) return false;
    const lessonStatus = String(lesson.serverStatus || lesson.status || "").toLowerCase();
    if (["cancelled", "canceled", "absence", "absent", "makeup_due", "available"].includes(lessonStatus)) return false;
    const lessonCoachRoleId = String(lesson.coachRoleId || lesson.coach_role_id || memberLessonCoach(lesson, policy).id || "");
    return lessonCoachRoleId === coachRoleId;
  });
  if (!anchors.length) return false;
  const slotStart = minutesFromTime(time);
  const slotEnd = slotStart + Math.max(1, numericValue(product.lessonMinutes, 20));
  return anchors.some((lesson) => {
    const anchorStart = minutesFromTime(lesson.time);
    const anchorEnd = anchorStart + lessonDuration(lesson);
    const gapAfterAnchor = slotStart >= anchorEnd ? slotStart - anchorEnd : Number.POSITIVE_INFINITY;
    const gapBeforeAnchor = slotEnd <= anchorStart ? anchorStart - slotEnd : Number.POSITIVE_INFINITY;
    return gapAfterAnchor <= gapMinutes || gapBeforeAnchor <= gapMinutes;
  });
}

function selectPurchasePurpose(purpose = "") {
  const flow = purchaseFlowState();
  flow.showMoreSlots = false;
  flow.showAllProducts = false;
  const activeTickets = currentLiveTickets();
  if (purpose === "renew_same") {
    const sourceTicket = activeTickets.find((ticket) => String(ticket.id) === String(flow.renewalTicketId)) || activeTickets[0] || null;
    if (!sourceTicket) return;
    const lesson = purchaseTicketLesson(sourceTicket);
    flow.purchasePurpose = "renew_same";
    flow.renewalTicketId = sourceTicket.id || "";
    flow.scheduleMode = "keep";
    flow.coachRoleId = sourceTicket.coachRoleId || "";
    flow.coachName = sourceTicket.coach || memberScheduleTicketCoachName(sourceTicket) || "";
    flow.preferredDate = lesson?.lessonDate || "";
    flow.preferredDay = lesson?.day || "";
    flow.preferredTime = lesson?.time || "";
    flow.preferredSchedules = [];
    const matchingProduct = membershipProducts().find((product) => String(product.id) === String(sourceTicket.productId || ""))
      || recommendedMembershipProducts(membershipProducts(), membershipProductFamilyId(sourceTicket), sourceTicket)[0];
    if (matchingProduct) {
      flow.productId = matchingProduct.id;
      flow.familyId = membershipProductFamilyId(matchingProduct);
      flow.scheduleMode = purchaseUsesFlexibleCouponSchedule(matchingProduct, flow) ? "flex" : "keep";
      flow.productFrequency = purchaseProductFrequency(matchingProduct);
      if (["weekday", "weekend"].includes(membershipProductFacet(matchingProduct, "scheduleScope"))) {
        flow.productScheduleScope = membershipProductFacet(matchingProduct, "scheduleScope");
      }
    }
  } else if (purpose === "add_coach") {
    flow.purchasePurpose = "add_coach";
    flow.renewalTicketId = "";
    flow.scheduleMode = "change";
    flow.coachRoleId = "";
    flow.coachName = "";
    clearPurchaseSchedules();
  }
  saveSnapshot();
  renderMembershipPurchaseFlow();
  void refreshPurchaseScheduleAvailability();
}

function selectPurchaseRenewalTicket(ticketId = "") {
  const flow = purchaseFlowState();
  flow.renewalTicketId = ticketId;
  selectPurchasePurpose("renew_same");
}

function selectPurchaseFamily(familyId = "") {
  const family = membershipProductFamilyDefinition(familyId);
  const flow = purchaseFlowState();
  flow.familyId = family.id;
  if (family.id === "one-day") flow.purchasePurpose = "one_day";
  else if (flow.purchasePurpose === "one_day") flow.purchasePurpose = currentLiveTickets().length ? "add_coach" : "new_purchase";
  flow.productId = "";
  flow.showAllProducts = false;
  flow.discountIssueId = "";
  flow.discountSelectionMode = "auto";
  clearPurchasePaymentError();
  const keepingRenewal = flow.purchasePurpose === "renew_same" && Boolean(purchaseFlowSourceTicket());
  if (!keepingRenewal) {
    flow.coachRoleId = "";
    flow.coachName = "";
    clearPurchaseSchedules();
  }
  flow.showMoreSlots = false;
  state.membershipFilters = { ...family.filters };
  state.membershipSelectedFamilyId = family.id;
  saveSnapshot();
  if (flow.open) renderMembershipPurchaseFlow();
  else renderProducts();
}

function selectPurchaseProduct(productId = "") {
  const product = membershipProducts().find((item) => (
    String(item.id || "") === String(productId || "")
    && isDirectPurchaseMembershipProduct(item)
  ));
  if (!product) return;
  const flow = purchaseFlowState();
  const productChanged = String(flow.productId || "") !== String(product.id || "");
  if (productChanged) {
    flow.showMoreSlots = false;
    flow.discountIssueId = "";
    flow.discountSelectionMode = "auto";
    clearPurchasePaymentError();
  }
  flow.productId = product.id;
  flow.familyId = membershipProductFamilyId(product);
  flow.productFrequency = purchaseProductFrequency(product);
  if (["weekday", "weekend"].includes(membershipProductFacet(product, "scheduleScope"))) {
    flow.productScheduleScope = membershipProductFacet(product, "scheduleScope");
  }
  if (flow.familyId === "one-day") {
    flow.purchasePurpose = "one_day";
    flow.renewalTicketId = "";
    flow.scheduleMode = "change";
  } else if (flow.purchasePurpose === "one_day") {
    flow.purchasePurpose = currentLiveTickets().length ? "add_coach" : "new_purchase";
  }
  if (purchaseUsesFlexibleCouponSchedule(product, flow)) {
    flow.scheduleMode = "flex";
    clearPurchaseSchedules();
  } else if (flow.purchasePurpose !== "renew_same" || !flow.renewalTicketId) {
    flow.scheduleMode = "change";
  }
  if (productChanged && !flow.renewalTicketId) {
    flow.coachRoleId = "";
    flow.coachName = "";
    clearPurchaseSchedules();
  }
  if (!flow.open) {
    openMembershipPurchaseFlow("", product.id);
    return;
  }
  saveSnapshot();
  renderMembershipPurchaseFlow();
  void refreshPurchaseScheduleAvailability();
  if (productChanged && product.branchId) {
    void syncMemberPaymentOptionsFromServer(product.branchId).then(() => renderMembershipPurchaseFlow());
  }
}

function movePurchaseStep(direction = 1) {
  const flow = purchaseFlowState();
  if (direction > 0 && !purchaseStepCanContinue()) return;
  flow.step = Math.min(3, Math.max(1, flow.step + direction));
  saveSnapshot();
  renderMembershipPurchaseFlow();
  if (flow.step === 2) void refreshPurchaseScheduleAvailability();
  window.requestAnimationFrame(() => $("#membershipPurchaseFlow")?.scrollIntoView({ block: "start" }));
}

async function refreshPurchaseScheduleAvailability(options = {}) {
  if (state.dataMode !== "live" || !state.member?.profileId) return true;
  const client = window.TennisNoteDataClient;
  const product = purchaseFlowProduct();
  const context = purchaseDirectoryContext(product);
  if (!client?.rpc || !client.getSession?.()?.access_token || !context.branchId) {
    memberPurchaseDirectoryLoad = {
      key: context.key,
      status: "error",
      error: "member_purchase_directory_unavailable",
    };
    renderMembershipPurchaseFlow();
    return false;
  }

  const cached = memberPurchaseDirectoryCache;
  if (!options.force && cached?.key === context.key && Date.now() - cached.loadedAt < 10_000) {
    memberPurchaseDirectoryLoad = { key: context.key, status: "ready", error: "" };
    const removedCount = reconcilePurchaseSchedulesAfterRefresh(product);
    const weekChanged = alignPurchaseScheduleWeekToAvailability(product);
    if (weekChanged) saveSnapshot();
    if (removedCount) showToast("마감되거나 변경된 시간을 해제했습니다. 가능한 시간을 다시 선택해 주세요.");
    const flow = purchaseFlowState();
    if (flow.open && flow.step !== 4) renderMembershipPurchaseFlow();
    if (!$("#purchaseScheduleSheet")?.hidden) renderPurchaseScheduleSheet();
    return true;
  }

  const requestId = ++memberPurchaseDirectoryRequestSequence;
  memberPurchaseDirectoryLoad = { key: context.key, status: "loading", error: "" };
  if (purchaseFlowState().open && purchaseFlowState().step !== 4) renderMembershipPurchaseFlow();
  if (!$("#purchaseScheduleSheet")?.hidden) renderPurchaseScheduleSheet();
  try {
    const directory = await client.rpc("tn_member_purchase_coach_directory", {
      target_branch_id: context.branchId,
      target_from: context.from,
      target_to: context.to,
    });
    if (requestId !== memberPurchaseDirectoryRequestSequence
      || purchaseDirectoryContext(purchaseFlowProduct()).key !== context.key) return false;
    if (!directory
      || String(directory.branchId || "") !== context.branchId
      || !Array.isArray(directory.coaches)
      || !Array.isArray(directory.occupancy)
      || !Array.isArray(directory.operationDays)
      || !Array.isArray(directory.breakRules)) {
      throw new Error("member_purchase_directory_response_invalid");
    }
    memberPurchaseDirectoryCache = {
      key: context.key,
      loadedAt: Date.now(),
      directory,
    };
    memberPurchaseDirectoryLoad = { key: context.key, status: "ready", error: "" };
    const removedCount = reconcilePurchaseSchedulesAfterRefresh(product);
    const weekChanged = alignPurchaseScheduleWeekToAvailability(product);
    if (weekChanged) saveSnapshot();
    if (removedCount) showToast("마감되거나 변경된 시간을 해제했습니다. 가능한 시간을 다시 선택해 주세요.");
  } catch (error) {
    if (requestId !== memberPurchaseDirectoryRequestSequence) return false;
    memberPurchaseDirectoryLoad = {
      key: context.key,
      status: "error",
      error: error?.payload?.code || error?.message || "member_purchase_directory_failed",
    };
    console.warn("Tennis Note purchase directory failed", memberPurchaseDirectoryLoad.error);
  }
  const flow = purchaseFlowState();
  if (flow.open && flow.step !== 4) renderMembershipPurchaseFlow();
  if (!$("#purchaseScheduleSheet")?.hidden) renderPurchaseScheduleSheet();
  return purchaseScheduleAvailabilityState() === "ready";
}

function completeMembershipPurchaseFlow(message = "결제가 접수되었습니다") {
  const flow = purchaseFlowState();
  flow.open = true;
  flow.step = 4;
  flow.completionStatus = message;
  saveSnapshot();
  renderMembershipPurchaseFlow();
}

function restorePurchaseDataAfterFailedRefresh(previous = {}) {
  state.liveMembershipProducts = previous.products || [];
  state.livePaymentOptions = previous.paymentOptions || state.livePaymentOptions;
  state.discountCoupons = previous.discountCoupons || [];
  state.memberEnrollment = previous.memberEnrollment ?? state.memberEnrollment;
  state.membershipPricingQuotes = previous.pricingQuotes || {};
  memberPurchaseDataLoaded = previous.loaded === true;
}

async function revalidatePurchaseBeforePrepare(productId = "") {
  const flow = purchaseFlowState();
  const previousProduct = purchaseFlowProduct();
  const previousMethodId = normalizeSelectedPaymentMethod();
  const previousAmount = previousProduct ? purchasePaymentAmount(previousProduct, previousMethodId) : 0;
  const previousCouponId = String(flow.discountIssueId || "");
  const previousScheduleKeys = new Set(purchaseSelectedSchedules(previousProduct).map(purchaseScheduleKey));
  const previousData = {
    products: state.liveMembershipProducts,
    paymentOptions: state.livePaymentOptions,
    discountCoupons: state.discountCoupons,
    memberEnrollment: state.memberEnrollment,
    pricingQuotes: state.membershipPricingQuotes,
    loaded: memberPurchaseDataLoaded,
  };
  const dataReady = await ensureMembershipPurchaseData({ force: true });
  if (!dataReady) {
    restorePurchaseDataAfterFailedRefresh(previousData);
    setPurchaseRevalidationNotice("purchase_revalidation_network_failed", "상품과 가격을 다시 확인하지 못했습니다. 선택은 보존했으며 연결 후 다시 시도할 수 있습니다.");
    return false;
  }

  const currentProduct = membershipProducts().find((product) => (
    String(product.id || "") === String(productId || "")
    && isDirectPurchaseMembershipProduct(product)
  )) || null;
  if (!currentProduct) {
    flow.productId = "";
    flow.coachRoleId = "";
    flow.coachName = "";
    flow.discountIssueId = "";
    clearPurchaseSchedules();
    setPurchaseRevalidationNotice("active_product_not_found", "선택한 상품의 판매가 종료되었습니다. 상품만 다시 선택해 주세요.");
    return false;
  }

  const currentMethodId = normalizeSelectedPaymentMethod();
  if (currentMethodId !== previousMethodId) {
    flow.discountIssueId = "";
    flow.discountSelectionMode = "auto";
    setPurchaseRevalidationNotice("payment_method_not_available", "선택한 결제 방법을 현재 사용할 수 없습니다. 결제 방법만 다시 확인해 주세요.");
    return false;
  }

  if (previousCouponId && !purchaseDiscountCoupons(currentProduct, currentMethodId).some((coupon) => String(coupon.id || "") === previousCouponId)) {
    flow.discountIssueId = "";
    flow.discountSelectionMode = "manual";
    setPurchaseRevalidationNotice("discount_coupon_not_available", "선택한 쿠폰을 더 이상 사용할 수 없습니다. 쿠폰만 해제했으며 나머지 선택은 유지했습니다.");
    return false;
  }

  const currentAmount = purchasePaymentAmount(currentProduct, currentMethodId);
  if (Number(previousAmount) > 0 && Number(currentAmount) !== Number(previousAmount)) {
    setPurchaseRevalidationNotice("product_price_mismatch", `상품 가격 또는 할인이 변경되었습니다. 새 결제금액 ${formatWon(currentAmount)}을 확인한 뒤 다시 결제해 주세요.`);
    return false;
  }

  const directoryReady = await refreshPurchaseScheduleAvailability({ force: true });
  if (!directoryReady) {
    setPurchaseRevalidationNotice("purchase_directory_refresh_failed", "선생님과 시간을 다시 확인하지 못했습니다. 선택은 보존했으며 연결 후 다시 시도할 수 있습니다.");
    return false;
  }
  const sourceTicket = purchaseFlowSourceTicket();
  const keepsExistingSchedule = flow.purchasePurpose === "renew_same" && sourceTicket && flow.scheduleMode === "keep";
  const coachStillAvailable = keepsExistingSchedule || purchaseCoachOptions().some((coach) => {
    const roleId = String(coach.serverRoleId || coach.roleId || coach.id || "");
    return roleId === String(flow.coachRoleId || "") && purchaseProductAllowsCoach(currentProduct, roleId);
  });
  if (!coachStillAvailable) {
    flow.coachRoleId = "";
    flow.coachName = "";
    clearPurchaseSchedules();
    setPurchaseRevalidationNotice("approved_branch_coach_required", "선택한 코치의 예약이 중지되었습니다. 다른 코치의 시간만 다시 선택해 주세요.");
    return false;
  }

  if (!keepsExistingSchedule && !purchaseUsesFlexibleCouponSchedule(currentProduct, flow)) {
    const currentScheduleKeys = new Set(purchaseSelectedSchedules(currentProduct).map(purchaseScheduleKey));
    const removedSchedule = [...previousScheduleKeys].some((key) => !currentScheduleKeys.has(key));
    if (removedSchedule || !purchaseSchedulesAvailableNow(currentProduct)) {
      setPurchaseRevalidationNotice("purchase_slot_occupied", "선택한 시간 중 마감된 시간이 있습니다. 선택한 시간만 다시 골라 주세요.");
      return false;
    }
  }
  clearPurchasePaymentError();
  saveSnapshot();
  renderMembershipPurchaseFlow();
  return true;
}

async function applyPaymentPreparationFailure(error) {
  const code = paymentServerErrorCode(error);
  const flow = purchaseFlowState();
  const scheduleCodes = new Set([
    "purchase_slot_temporarily_held",
    "purchase_slot_outside_adjacent_anchor",
    "purchase_slot_outside_anchor_window",
    "purchase_slot_anchor_required",
    "purchase_slot_occupied",
    "purchase_slot_must_be_future",
    "purchase_slot_blocked",
    "coach_not_working",
    "lesson_time_grid_invalid",
    "purchase_slot_hold_failed",
  ]);
  if (["approved_branch_coach_required", "product_coach_sale_disabled", "purchase_coach_required"].includes(code)) {
    flow.coachRoleId = "";
    flow.coachName = "";
    clearPurchaseSchedules();
  } else if (scheduleCodes.has(code)) {
    clearPurchaseSchedules();
    await refreshPurchaseScheduleAvailability({ force: true }).catch(() => false);
  } else if (["active_product_not_found", "product_sale_feature_disabled", "product_price_not_ready"].includes(code)) {
    flow.productId = "";
    flow.coachRoleId = "";
    flow.coachName = "";
    flow.discountIssueId = "";
    clearPurchaseSchedules();
  } else if (code === "product_price_mismatch") {
    await ensureMembershipPurchaseData({ force: true }).catch(() => false);
  } else if (code.startsWith("discount_coupon_")) {
    flow.discountIssueId = "";
    flow.discountSelectionMode = "manual";
  }
  saveSnapshot();
  return code;
}

async function submitMembershipPurchaseFlow() {
  if (membershipPurchasePaymentInFlight) return;
  const product = purchaseFlowProduct();
  if (!product || !purchaseStepCanContinue()) return;
  membershipPurchasePaymentInFlight = true;
  renderMembershipPurchaseFlow();
  try {
    if (state.dataMode === "live") {
      const ready = await revalidatePurchaseBeforePrepare(product.id);
      if (!ready || !purchaseStepCanContinue()) {
        if (!purchaseFlowState().paymentErrorMessage) showToast("결제 전 최신 선택 내용을 다시 확인해 주세요.");
        return;
      }
    }
    await startProductPayment(product.id);
  } finally {
    membershipPurchasePaymentInFlight = false;
    if (purchaseFlowState().open) renderMembershipPurchaseFlow();
  }
}

