async function syncPersonalJournalFromServer() {
  const api = window.TennisNotePersonalJournal;
  if (!state.member?.profileId || !api) return false;
  const owner = state.member.profileId;
  let loaded;
  try {
    loaded = await api.load();
  } catch (error) {
    if (state.member?.profileId !== owner) return false;
    personalJournalReadError = { owner, message: api.errorMessage(error, "list") };
    renderPracticeLogs();
    renderSelectedJournalDayPanel();
    return false;
  }
  if (state.member?.profileId !== owner) { api.release(loaded.logs); return false; }
  personalJournalReadError = null;
  const keys = new Set(loaded.logs.map((log) => log.personalClientKey).filter(Boolean));
  const local = state.practiceLogs.filter((log) => !log.serverJournalId && !keys.has(log.personalClientKey));
  const completedSelections = new Map(state.practiceLogs.flatMap((log) => (log.mediaItems || [])
    .filter((item) => item.serverMediaId && item.uploadSelectionKey)
    .map((item) => [item.serverMediaId, item.uploadSelectionKey])));
  api.release(state.practiceLogs.filter((log) => log.serverJournalId));
  state.practiceLogs = [...loaded.logs.map((log) => ({ ...log, personalOwnerId: owner,
    mediaItems: (log.mediaItems || []).map((item) => ({ ...item,
      ...(completedSelections.has(item.serverMediaId) ? { uploadSelectionKey: completedSelections.get(item.serverMediaId) } : {}) })) })), ...local];
  saveSnapshot();
  renderPracticeLogs();
  renderSelectedJournalDayPanel();
  return true;
}

async function savePracticeLog() {
  const memoInput = $("#practiceMemo");
  if (!memoInput.value.trim()) {
    personalJournalStatus("오늘 운동 기록을 입력해 주세요.");
    memoInput.setAttribute("aria-invalid", "true");
    memoInput.setAttribute("aria-describedby", "personalJournalStatus");
    memoInput.focus({ preventScroll: true });
    memoInput.scrollIntoView({ block: "center", behavior: "smooth" });
    return false;
  }
  memoInput.removeAttribute("aria-invalid");
  const existing = state.practiceLogs.find((log) => log.id === (state.personalEditingId || state.personalDraftId));
  const selectedFiles = [...($("#practiceMedia")?.files || [])];
  const recoverySourceId = state.personalRecoverySourceId || "";
  const priorMedia = existing?.mediaItems || [];
  const sameSelection = (item, file) => {
    if (item.uploadSelectionKey && item.uploadSelectionKey === window.TennisNotePersonalJournal.selectionKey(file)) return true;
    const receipt = window.TennisNotePersonalJournal.completedReceipt(file, existing?.serverJournalId);
    return Boolean(receipt && item.serverMediaId === receipt.mediaId && item.storagePath === receipt.storagePath);
  };
  const mediaItems = selectedFiles.map((file) => {
    const prior = priorMedia.find((item) => sameSelection(item, file));
    return prior || mediaItemsFromInput({ files: [file] })[0];
  });
  const combinedMedia = [...priorMedia.filter((item) => !selectedFiles.some((file) => sameSelection(item, file))), ...mediaItems];
  const requestFeedback = $("#requestCoachFeedback")?.checked;
  const journalDate = $("#journalDate")?.value || localDateKey();
  const log = {
    ...(existing || {}),
    id: existing?.id || state.personalDraftId || window.TennisNotePersonalJournal.key(),
    date: new Date(`${journalDate}T00:00:00`).toLocaleDateString("ko-KR"),
    journalDate,
    type: $("#practiceType").value,
    memo: $("#practiceMemo").value.trim(),
    next: $("#practiceNext").value.trim(),
    mediaNames: combinedMedia.map((item) => item.name),
    mediaItems: combinedMedia,
    feedbackQuestion: $("#feedbackQuestion")?.value.trim() || "",
    feedbackStatus: requestFeedback ? "코치 피드백 요청" : "개인 기록",
    coachFeedback: "",
    submittedAt: existing?.submittedAt || new Date().toISOString(),
  };
  state.personalDraftId = log.id;
  const hasLiveSession = Boolean(state.member?.profileId && window.TennisNoteDataClient?.getSession?.()?.access_token);
  if (!hasLiveSession && state.dataMode === "live") {
    personalJournalStatus("로그인이 필요합니다. 입력 내용은 유지됩니다.");
    return false;
  }
  if (hasLiveSession) {
    if (existing?.personalOwnerId && existing.personalOwnerId !== state.member.profileId) {
      personalJournalStatus("다른 계정의 기록은 변경할 수 없습니다."); return false;
    }
    log.personalOwnerId = state.member.profileId;
    log.personalClientKey ||= log.id;
    const checkpoint = (pendingLog) => {
      const index = state.practiceLogs.findIndex((item) => item.id === pendingLog.id);
      if (index < 0) state.practiceLogs.unshift(pendingLog);
      else state.practiceLogs[index] = pendingLog;
      state.personalEditingId = pendingLog.id;
      saveSnapshot();
    };
    try {
      await window.TennisNotePersonalJournal.save(log, selectedFiles, checkpoint);
      if (recoverySourceId) {
        state.practiceLogs = state.practiceLogs.filter((item) => item.id !== recoverySourceId);
      }
      if (!await syncPersonalJournalFromServer()) {
        showToast("기록과 첨부는 서버에 저장됐습니다. 목록 확인이 지연되어 다시 열 때 확인합니다.");
      }
    } catch (error) {
      personalJournalStatus(window.TennisNotePersonalJournal.errorMessage(error));
      return false;
    }
  } else {
    const index = state.practiceLogs.findIndex((item) => item.id === log.id);
    if (index < 0) state.practiceLogs.unshift(log); else state.practiceLogs[index] = log;
    if (requestFeedback) pushPracticeFeedbackToShared(log);
  }
  state.selectedJournalDate = journalDate;
  state.activeJournalMonth = journalDate.slice(0, 7);
  state.personalEditingId = null;
  state.personalDraftId = null;
  state.personalRecoverySourceId = null;
  if ($("#practiceMedia")) $("#practiceMedia").value = "";
  personalJournalStatus();
  renderJournalCalendar();
  saveSnapshot();
  return true;
}

function editPersonalJournal(id) {
