function createPaymentRecord(product, overrides = {}) {
  const methodId = overrides.methodId || state.selectedPaymentMethod;
  const paymentAmount = purchasePaymentAmount(product, methodId);
  const request = {
    productId: product.id,
    productTitle: product.title,
    amountLabel: paymentAmount ? `${paymentAmount.toLocaleString("ko-KR")}원` : "무료",
    coach: product.coach,
    method: overrides.method || (paymentAmount ? "결제 확인 대기" : "관리자 상담 필요"),
    status: overrides.status || (paymentAmount ? `${product.flow} · 결제 확인 대기` : `${product.flow} · 관리자 확인 필요`),
    discount: product.discount,
    settlementBaseLabel: product.settlementBase ? `${product.settlementBase.toLocaleString("ko-KR")}원` : "관리자 확인",
    paymentId: overrides.paymentId || "",
    serverPaymentId: overrides.serverPaymentId || "",
    bankTransferAccount: overrides.bankTransferAccount || null,
    serverSynced: overrides.serverSynced === true || Boolean(overrides.serverPaymentId),
    cancellable: overrides.cancellable === true,
  };
  const existingIndex = state.paymentRequests.findIndex((item) => (
    request.paymentId && String(item.paymentId || "") === String(request.paymentId)
  ));
  if (existingIndex >= 0) {
    const existing = state.paymentRequests.splice(existingIndex, 1)[0];
    state.paymentRequests.unshift({ ...existing, ...request });
  } else {
    state.paymentRequests.unshift(request);
  }
  pushPaymentRequestToShared(request);
}

function paymentServerErrorCode(error) {
  const payload = error?.payload || {};
  const nested = payload?.error || {};
  const raw = [payload.code, nested.code, error?.code, error?.message, nested.message, payload.message]
    .filter(Boolean)
    .map(String);
  const combined = raw.join(" ");
  if (/RECORD_NOT_FOUND|storeId\s+is\s+not\s+correct|store[_ ]?id.*(incorrect|invalid|not found)/i.test(combined)) {
    return "portone_store_config_invalid";
  }
  if (/channel.*(not found|incorrect|invalid)|CHANNEL_NOT_FOUND/i.test(combined)) {
    return "portone_channel_config_invalid";
  }
  const directCode = raw.find((value) => /^[a-z][a-z0-9_]{2,119}$/i.test(value));
  return directCode ? directCode.toLowerCase() : "payment_provider_error";
}

function reportPaymentProviderError(error, stage = "payment_provider") {
  const code = paymentServerErrorCode(error);
  window.dispatchEvent(new CustomEvent("tennisnote:client-error", {
    detail: {
      category: "runtime",
      stage,
      code,
      message: paymentServerErrorMessage({ payload: { code } }),
      provider: "portone",
      native: nativeAppPlatform() !== "web",
    },
  }));
  return code;
}

function safePaymentHistoryStatus(value = "") {
  const text = String(value || "").trim();
  if (!text) return "";
  if (/^[{[]|RECORD_NOT_FOUND|storeId\s+is\s+not\s+correct|CHANNEL_NOT_FOUND/i.test(text)) {
    return paymentServerErrorMessage({ message: text });
  }
  return text.slice(0, 240);
}

