    const serverRequests = rows
      .filter((row) => row?.paymentId)
      .map((row) => {
        const methodId = String(row.method || "").toLowerCase();
        const methodLabel = paymentMethodDefinitions.find((method) => method.id === methodId)?.label
          || (methodId === "bank_transfer" ? "계좌이체" : "결제");
        const status = String(row.status || "ready").toLowerCase();
        const bankState = String(row.bankTransferState || "").toLowerCase();
        const dueAtMillis = Date.parse(String(row.depositDueAt || ""));
        const expired = methodId === "bank_transfer" && Number.isFinite(dueAtMillis) && Date.now() > dueAtMillis;
        return {
          paymentId: String(row.paymentId || ""),
          serverPaymentId: String(row.localPaymentId || ""),
          productId: String(row.productId || ""),
          productTitle: String(row.productTitle || "회원권"),
          amountLabel: Number(row.amount || 0) > 0 ? `${Number(row.amount).toLocaleString("ko-KR")}원` : "금액 확인",
          coach: "담당 코치 확인",
          method: methodLabel,
          status: bankState === "confirmation_failed"
            ? "입금 확인 · 회원권 처리 확인 필요"
            : bankState === "confirming"
              ? "입금·회원권 처리 중"
              : status === "verified"
                ? "결제 확인 · 회원권 처리 확인 필요"
            : expired
              ? "입금기한 지남 · 입금했다면 관리자 문의"
              : status === "failed" ? "결제 실패 · 취소 후 다시 시도" : "입금 확인 대기 · 취소 가능",
          serverSynced: true,
          cancellable: ["ready", "failed"].includes(status) && !["confirming", "confirmed", "confirmation_failed"].includes(bankState),
          createdAt: String(row.createdAt || ""),
          depositDueAt: String(row.depositDueAt || ""),
        };
      });
    const pendingIds = new Set(serverRequests.map((request) => request.paymentId));
    const localRequests = (state.paymentRequests || []).filter((request) => (
      request.serverSynced !== true && !pendingIds.has(String(request.paymentId || ""))
    ));
    state.paymentRequests = [...serverRequests, ...localRequests];

    const shared = loadSharedData();
    const sharedLocalRequests = (shared.paymentRequests || []).filter((request) => (
      request.serverSynced !== true && !pendingIds.has(String(request.paymentId || ""))
    ));
    shared.paymentRequests = [...serverRequests, ...sharedLocalRequests];
    saveSharedData(shared);
    return true;
  } catch {
    return false;
  }
}

async function prepareServerPayment(product, paymentId, methodId = state.selectedPaymentMethod) {
  const client = window.TennisNoteDataClient;
  if (!client?.invokeFunction || !client.getSession?.()?.access_token) {
    throw new Error("login_required");
  }
  const paymentAmount = purchasePaymentAmount(product, methodId);
  const enforcedMethodId = paymentMethodIdForRequest(methodId);
  if (!isPaymentGatewayReady(enforcedMethodId)) throw new Error("payment_channel_not_ready");
  const purchaseFlow = purchaseFlowState();
  const flexibleCoupon = purchaseFlow.productId === product.id && purchaseUsesFlexibleCouponSchedule(product, purchaseFlow);
  const keepsExistingRenewalSchedule = purchaseFlow.productId === product.id
    && purchaseFlow.purchasePurpose === "renew_same"
    && purchaseFlow.scheduleMode === "keep";
  return client.invokeFunction("portone-payment/prepare", {
    body: {
      paymentId,
      branchId: product.branchId || null,
      productKey: product.id,
      productTitle: product.title,
      amount: paymentAmount,
      originalAmount: product.cardAmount || product.listAmount || paymentAmount,
      cashPrice: product.cashAmount || product.settlementBase || paymentAmount,
      settlementBaseAmount: product.settlementBase || product.cashAmount || paymentAmount,
      finalAmount: paymentAmount,
      priceType: enforcedMethodId === "bank_transfer" ? "cash" : "card",
      totalSessions: product.tickets || 1,
      lessonMinutes: Number(product.lessonMinutes) || (product.title.includes("30") || product.detail.includes("30") ? 30 : 20),
      machineMinutes: Number(product.lessonMinutes) || (product.title.includes("30") || product.detail.includes("30") ? 30 : 20),
      productKind: product.productKind === "pass" || product.mode === "coupon" || product.mode === "pass" ? "coupon" : product.mode === "add" ? "add" : product.mode === "renewal" ? "renewal" : "regular",
      groupSize: Number(product.groupSize) || (product.title.includes("2대1") || product.detail.includes("2대1") || product.detail.includes("2:1") ? 2 : 1),
      validityDays: Number(product.validityDays) || 35,
      graceDays: Number(product.graceDays) || 0,
      method: enforcedMethodId,
      groupAccountId: Number(product.groupSize) === 2 ? state.groupAccount?.id || null : null,
      coachRoleId: purchaseFlow.productId === product.id ? purchaseFlow.coachRoleId || null : null,
      preferredDate: purchaseFlow.productId === product.id && !flexibleCoupon && !keepsExistingRenewalSchedule ? purchaseFlow.preferredDate || null : null,
      preferredDay: purchaseFlow.productId === product.id && !flexibleCoupon && !keepsExistingRenewalSchedule ? purchaseFlow.preferredDay || null : null,
      preferredTime: purchaseFlow.productId === product.id && !flexibleCoupon && !keepsExistingRenewalSchedule ? purchaseFlow.preferredTime || null : null,
      preferredSchedules: purchaseFlow.productId === product.id && !flexibleCoupon && !keepsExistingRenewalSchedule
        ? purchaseSelectedSchedules(product).map((schedule) => ({
          lessonDate: schedule.lessonDate,
          day: schedule.day,
          startTime: schedule.startTime,
          durationMinutes: schedule.durationMinutes,
          coachRoleId: schedule.coachRoleId,
        }))
        : [],
      scheduleMode: purchaseFlow.productId === product.id ? flexibleCoupon ? "flex" : purchaseFlow.scheduleMode || "change" : "change",
      renewalSourceTicketId: purchaseFlow.productId === product.id && purchaseFlow.purchasePurpose === "renew_same"
        ? purchaseFlow.renewalTicketId || null
        : null,
      purchasePurpose: purchaseFlow.productId === product.id ? purchaseFlow.purchasePurpose || "new_purchase" : "new_purchase",
      discountIssueId: purchaseFlow.productId === product.id ? purchaseFlow.discountIssueId || null : null,
    },
  });
}

async function verifyServerPayment(paymentId) {
  const client = window.TennisNoteDataClient;
  if (!client?.invokeFunction || !client.getSession?.()?.access_token) {
    throw new Error("login_required");
  }
  return client.invokeFunction("portone-payment/verify", {
    body: { paymentId },
  });
}

async function reconcileRejectedServerPayment(paymentId) {
  if (!paymentId) return;
  const client = window.TennisNoteDataClient;
  try {
    await verifyServerPayment(paymentId);
  } catch {
    // Terminal provider states are persisted before the server returns a verification error.
  }
  try {
    await client?.invokeFunction?.("portone-payment/cancel-pending", {
      body: { paymentId, reason: "결제창 미완료 자동 정리" },
    });
  } catch {
    // Paid or concurrently verified orders are intentionally not cancelled by this endpoint.
  }
}

function clearPaymentRedirectParams() {
  const url = new URL(window.location.href);
  ["paymentId", "code", "message", "pgCode", "pgMessage"].forEach((key) => url.searchParams.delete(key));
  window.history.replaceState({}, document.title, `${url.pathname}${url.search}${url.hash}`);
}

async function handlePaymentRedirectResult() {
  const params = new URLSearchParams(window.location.search);
  const paymentId = params.get("paymentId") || "";
  if (!paymentId) return false;
  const errorCode = params.get("code") || "";
  const message = params.get("message") || params.get("pgMessage") || "";
  clearPaymentRedirectParams();
  if (errorCode) {
    await reconcileRejectedServerPayment(paymentId);
    await syncMemberTicketsFromServer();
    state.pendingPaymentCheckStatus = { tone: "alert", text: message || "결제가 완료되지 않았습니다." };
    state.ticketHistory.unshift({ text: message || `결제 미완료 · ${errorCode}`, tone: "alert" });
    renderAll();
    setView("shopView");
    return true;
  }
  try {
    const verification = await verifyServerPayment(paymentId);
    state.pendingPaymentCheckStatus = verification?.ok
      ? { tone: "done", text: "결제 검증이 끝났습니다. 회원권 상태를 확인합니다." }
      : { tone: "wait", text: "결제 접수 후 서버 검증을 기다리는 중입니다." };
    state.ticketHistory.unshift({ text: "결제창 복귀 · 서버 검증 완료", tone: verification?.ok ? "done" : "wait" });
    const flow = purchaseFlowState();
    flow.open = true;
    flow.step = 4;
    flow.completionStatus = verification?.ok ? "결제가 확인되었습니다" : "결제가 접수되었습니다";
  } catch (error) {
    state.pendingPaymentCheckStatus = { tone: "alert", text: `결제 검증 확인 필요 · ${paymentServerErrorMessage(error)}` };
    state.ticketHistory.unshift({ text: "결제창 복귀 · 관리자 검증 확인 필요", tone: "alert" });
  }
  await syncMemberTicketsFromServer();
  renderAll();
  setView("shopView");
  return true;
}

async function checkPendingTicketPayment(ticketId = "") {
  const ticket = state.liveTickets.find((item) => item.id === ticketId) || currentLiveTicket();
  const paymentId = ticket?.providerPaymentId || "";
  if (!ticket || !paymentId) {
    state.ticketSyncStatus = { tone: "alert", text: "결제 기록 연결 확인 필요 · 새 결제 전 관리자 화면 확인" };
    state.pendingPaymentCheckStatus = { tone: "alert", text: "결제 기록을 찾지 못했습니다. 새 결제 전 관리자 화면을 먼저 확인해주세요." };
    state.ticketHistory.unshift({ text: "대기 회원권의 결제 기록을 아직 찾지 못했습니다.", tone: "alert" });
    renderAll();
    setView("shopView");
    return;
  }

  state.ticketSyncStatus = { tone: "wait", text: "결제 상태 서버 확인 중" };
  state.pendingPaymentCheckStatus = { tone: "wait", text: "결제 상태를 확인하는 중입니다." };
  renderProducts();
  try {
    const verification = await verifyServerPayment(paymentId);
    if (verification?.ok) {
      state.pendingPaymentCheckStatus = { tone: "done", text: "서버 검증이 완료되었습니다. 회원권 상태를 새로 확인합니다." };
      state.ticketHistory.unshift({ text: `${ticket.title} 결제 검증 완료 · 회원권 활성화 확인`, tone: "done" });
    } else if (verification?.code === "payment_not_paid") {
      state.pendingPaymentCheckStatus = { tone: "wait", text: "아직 결제 완료 전입니다. 결제창에서 결제를 마친 뒤 다시 눌러주세요." };
      state.ticketHistory.unshift({ text: `${ticket.title} 아직 결제 완료 전 · 결제 완료 후 다시 확인`, tone: "wait" });
      state.ticketSyncStatus = { tone: "wait", text: "아직 결제 완료 전 · 결제창 완료 후 다시 확인" };
    } else {
      state.pendingPaymentCheckStatus = { tone: "alert", text: `결제 확인이 필요합니다. ${verification?.code || "서버 응답을 확인해주세요."}` };
      state.ticketHistory.unshift({ text: `${ticket.title} 결제 확인 필요 · ${verification?.code || "서버 응답 확인"}`, tone: "alert" });
      state.ticketSyncStatus = { tone: "alert", text: "결제 확인 필요 · 관리자 확인" };
    }
  } catch (error) {
    const code = paymentServerErrorMessage(error);
    const isNotPaid = code === "payment_not_paid";
    state.ticketHistory.unshift({
      text: isNotPaid
        ? `${ticket.title} 아직 결제 완료 전 · 결제 후 다시 확인`
        : `${ticket.title} 결제 검증 실패 · ${code}`,
      tone: isNotPaid ? "wait" : "alert",
    });
    state.pendingPaymentCheckStatus = {
      tone: isNotPaid ? "wait" : "alert",
      text: isNotPaid ? "아직 결제 완료 전입니다. 결제창에서 결제를 마친 뒤 다시 확인해주세요." : `결제 검증 실패: ${code}`,
    };
    state.ticketSyncStatus = {
      tone: isNotPaid ? "wait" : "alert",
      text: isNotPaid ? "아직 결제 완료 전 · 결제 후 다시 확인" : `결제 검증 실패 · ${code}`,
    };
  }
  await syncMemberTicketsFromServer();
  renderAll();
  setView("shopView");
}

async function resumePendingTicketPayment(ticketId = "") {
  const ticket = state.liveTickets.find((item) => item.id === ticketId) || currentLiveTicket();
  const paymentId = ticket?.providerPaymentId || "";
  const amount = Number(ticket?.paymentAmount || 0);
  const methodId = String(ticket?.paymentMethod || "").toLowerCase();
  if (ticket && (!isPaymentMethodAllowed(methodId) || !isPaymentGatewayReady(methodId))) {
    state.pendingPaymentCheckStatus = {
      tone: "alert",
      text: "기존 결제 대기건은 재개할 수 없습니다. 토스페이로 새 결제를 시작해 주세요.",
    };
    state.ticketHistory.unshift({ text: `${ticket.title || "회원권"} 기존 결제 대기 재개 차단 · 토스페이 신규 결제 필요`, tone: "alert" });
    renderAll();
    setView("shopView");
    return;
  }
  if (!ticket || !paymentId || !amount || !isPaymentGatewayReady(methodId)) {
    state.pendingPaymentCheckStatus = { tone: "alert", text: "기존 결제창을 열 결제 기록이나 결제 설정을 확인해주세요." };
    renderAll();
    setView("shopView");
    return;
  }

  try {
    const PortOne = await loadPortOneSdk();
    const response = await PortOne.requestPayment(portOnePaymentRequest({
      paymentId,
      productId: ticket.productId,
      orderName: ticket.title,
      totalAmount: amount,
      methodId,
    }));

    if (response?.code) {
      await reconcileRejectedServerPayment(response?.paymentId || paymentId);
      await syncMemberTicketsFromServer();
      const providerError = { payload: { code: response.code, message: response.message }, message: response.message };
      const detail = paymentServerErrorMessage(providerError);
      reportPaymentProviderError(providerError, "payment_resume_response");
      state.pendingPaymentCheckStatus = { tone: "alert", text: detail };
      state.ticketHistory.unshift({ text: `${ticket.title} 결제창 종료 · 결제 미완료`, tone: "alert" });
    } else {
      state.pendingPaymentCheckStatus = { tone: "wait", text: "결제창 완료 접수 · 서버 검증을 확인합니다." };
      await checkPendingTicketPayment(ticketId);
      return;
    }
  } catch (error) {
    const detail = paymentServerErrorMessage(error);
    reportPaymentProviderError(error, "payment_resume_open");
    state.pendingPaymentCheckStatus = { tone: "alert", text: `결제창을 열지 못했습니다. ${detail}` };
    state.ticketHistory.unshift({ text: `${ticket.title} 결제창 열기 실패`, tone: "alert" });
  }

  await syncMemberTicketsFromServer();
  renderAll();
  setView("shopView");
}

async function cancelPendingTicketPayment(ticketId = "") {
  const ticket = state.liveTickets.find((item) => item.id === ticketId) || null;
  const paymentId = ticket?.providerPaymentId || "";
  if (!ticket || !paymentId) {
    state.pendingPaymentCheckStatus = { tone: "alert", text: "취소할 결제 대기 기록을 찾지 못했습니다." };
    renderAll();
    setView("shopView");
    return;
  }
  if (pendingPaymentCancelInFlight.has(paymentId)) return;
  if (!window.confirm(`${ticket.title || "회원권"} 결제 대기를 취소할까요?\n실제 결제가 완료된 회원권은 취소되지 않습니다.`)) return;

  const client = window.TennisNoteDataClient;
  if (!client?.invokeFunction || !client.getSession?.()?.access_token) {
    state.pendingPaymentCheckStatus = { tone: "alert", text: "로그인 상태를 확인한 뒤 다시 시도해 주세요." };
    renderAll();
    return;
  }

  pendingPaymentCancelInFlight.add(paymentId);
  state.pendingPaymentCheckStatus = { tone: "wait", text: "결제 대기건을 취소하는 중입니다." };
  renderAll();
  try {
    const result = await client.invokeFunction("portone-payment/cancel-pending", {
      body: { paymentId, reason: "회원 결제 대기 취소" },
    });
    if (!result?.ok) throw Object.assign(new Error(result?.code || "pending_payment_cancel_failed"), { payload: result });
    state.pendingPaymentCheckStatus = { tone: "done", text: "결제 대기건을 취소했습니다." };
    state.ticketHistory.unshift({ text: `${ticket.title} 결제 대기 취소`, tone: "done" });
  } catch (error) {
    const detail = paymentServerErrorMessage(error);
    state.pendingPaymentCheckStatus = { tone: "alert", text: detail };
    state.ticketHistory.unshift({ text: `${ticket.title} 결제 대기 취소 실패 · ${detail}`, tone: "alert" });
  } finally {
    pendingPaymentCancelInFlight.delete(paymentId);
  }

  await Promise.allSettled([syncMemberTicketsFromServer(), syncMemberPendingPurchaseSchedulesFromServer(), syncMemberPendingPaymentsFromServer(), syncMemberDiscountCouponsFromServer()]);
  renderAll();
  setView("shopView");
}

async function cancelPendingPurchasePayment(paymentId = "", productTitle = "회원권") {
  if (!paymentId || pendingPaymentCancelInFlight.has(paymentId)) return;
  if (!window.confirm(`${productTitle} 결제 대기를 취소할까요?\n실제 결제가 완료된 건은 취소되지 않으며, 보관 중인 시간은 다시 예약 가능 상태로 돌아갑니다.`)) return;
  const client = window.TennisNoteDataClient;
  if (!client?.invokeFunction || !client.getSession?.()?.access_token) {
    showToast("로그인 상태를 확인한 뒤 다시 시도해 주세요.");
    return;
  }
  pendingPaymentCancelInFlight.add(paymentId);
  renderProducts();
  try {
    const result = await client.invokeFunction("portone-payment/cancel-pending", {
      body: { paymentId, reason: "회원 결제 대기 취소" },
    });
    if (!result?.ok) throw Object.assign(new Error(result?.code || "pending_payment_cancel_failed"), { payload: result });
    state.pendingPaymentCheckStatus = { tone: "done", text: "결제 대기와 선택 시간 보관을 취소했습니다. 같은 상품은 다시 결제할 수 있습니다." };
    state.paymentRequests = (state.paymentRequests || []).filter((request) => String(request.paymentId || "") !== String(paymentId));
    const shared = loadSharedData();
    shared.paymentRequests = (shared.paymentRequests || []).filter((request) => String(request.paymentId || "") !== String(paymentId));
    saveSharedData(shared);
    await Promise.allSettled([
      syncMemberPendingPurchaseSchedulesFromServer(),
      syncMemberPendingPaymentsFromServer(),
      syncMemberDiscountCouponsFromServer(),
      refreshPurchaseScheduleAvailability(),
    ]);
    renderAll();
    showToast("결제 대기를 취소했습니다.");
  } catch (error) {
    state.pendingPaymentCheckStatus = { tone: "alert", text: paymentServerErrorMessage(error) };
    renderAll();
  } finally {
    pendingPaymentCancelInFlight.delete(paymentId);
  }
}

function closePaymentConfirmationModal() {
  closeAppSheet("paymentConfirmationModal");
  preparedPaymentContext = null;
}

function openPaymentConfirmationModal({ product, paymentId, preparedPayment, methodId, sdk }) {
  const enforcedMethodId = paymentMethodIdForRequest(methodId);
  preparedPaymentContext = { product, paymentId, preparedPayment, methodId: enforcedMethodId, sdk };
  const modal = $("#paymentConfirmationModal");
  if (!modal) return;
  const amount = purchasePaymentAmount(product, enforcedMethodId);
  const method = paymentMethodDefinition(enforcedMethodId);
  $("#paymentConfirmationProduct").textContent = product.title;
  $("#paymentConfirmationAmount").textContent = `${amount.toLocaleString("ko-KR")}원`;
  $("#paymentConfirmationMethod").textContent = method.label;
  $("#paymentConfirmationMessage").textContent = "결제창에서 결제 정보를 확인한 뒤 최종 결제를 완료합니다.";
  const button = $("#openPreparedPaymentButton");
  const bankButton = $("#switchPaymentToBankTransferButton");
  if (bankButton) bankButton.hidden = true;
  if (button) {
    button.disabled = false;
    button.textContent = `${amount.toLocaleString("ko-KR")}원 결제창 열기`;
  }
  openAppSheet("paymentConfirmationModal", { initialFocus: "#openPreparedPaymentButton" });
}

async function completePreparedPayment() {
  const context = preparedPaymentContext;
  if (!context) return;
  const { product, sdk } = context;
  const requestedPaymentId = context.paymentId;
  const methodId = paymentMethodIdForRequest(context.methodId);
  let preparedPayment = context.preparedPayment || null;
  const method = paymentMethodDefinition(methodId);
  const paymentAmount = purchasePaymentAmount(product, methodId);
  const button = $("#openPreparedPaymentButton");
  const message = $("#paymentConfirmationMessage");
  if (button) button.disabled = true;
  if (message) message.textContent = "결제 요청을 준비하는 중입니다.";

  try {
    if (!preparedPayment) {
      preparedPayment = await prepareServerPayment(product, requestedPaymentId, methodId);
      context.preparedPayment = preparedPayment;
    }
    const effectivePaymentId = String(preparedPayment?.paymentId || requestedPaymentId);
    context.paymentId = effectivePaymentId;
    if (message) message.textContent = "결제창을 여는 중입니다.";
    const response = await sdk.requestPayment(portOnePaymentRequest({
      paymentId: effectivePaymentId,
      productId: product.id,
      orderName: product.title,
      totalAmount: paymentAmount,
      methodId,
    }));

    if (response?.code) {
      await reconcileRejectedServerPayment(response?.paymentId || effectivePaymentId);
      await syncMemberTicketsFromServer();
      const providerError = { payload: { code: response.code, message: response.message }, message: response.message };
      const detail = paymentServerErrorMessage(providerError);
      const diagnosticCode = reportPaymentProviderError(providerError, "payment_window_response");
      createPaymentRecord(product, {
        paymentId: effectivePaymentId,
        serverPaymentId: preparedPayment?.localPaymentId || "",
        method: `${method.label} 결제 실패`,
        status: detail,
      });
      await syncMemberPendingPaymentsFromServer();
      state.ticketHistory.unshift({ text: `${product.title} 결제 실패 · 다시 시도 필요`, tone: "alert" });
      const flow = purchaseFlowState();
      flow.paymentErrorCode = diagnosticCode;
      flow.paymentErrorMessage = detail;
      state.pendingPaymentCheckStatus = { tone: "alert", text: detail };
      if (message) message.textContent = `${detail} 선택한 상품·시간·쿠폰은 유지됩니다.`;
      const bankButton = $("#switchPaymentToBankTransferButton");
      if (bankButton) bankButton.hidden = !isPaymentGatewayReady("bank_transfer");
      if (button) {
        button.disabled = false;
        button.textContent = "다시 시도";
      }
      saveSnapshot();
      return;
    } else {
      const paidPaymentId = response?.paymentId || effectivePaymentId;
      let verifiedStatus = "결제 완료 · 서버 검증 후 회원권 충전 대기";
      try {
        const verification = await verifyServerPayment(paidPaymentId);
        if (verification?.ok) {
          verifiedStatus = verification.status === "verified"
            ? "서버 검증 완료 · 이용권 충전 확인 필요"
            : "서버 검증 확인 · 관리자 확인 필요";
        }
      } catch (error) {
        verifiedStatus = `결제 완료 · 서버 검증 대기 · ${paymentServerErrorMessage(error)}`;
      }
      createPaymentRecord(product, {
        paymentId: paidPaymentId,
        serverPaymentId: preparedPayment?.localPaymentId || "",
        method: method.label,
        status: verifiedStatus,
      });
      state.ticketHistory.unshift({ text: `${product.title} 결제 완료 접수 · 검증 후 회원권 충전`, tone: "wait" });
      const flow = purchaseFlowState();
      flow.open = true;
      flow.step = 4;
      flow.completionStatus = "결제가 접수되었습니다";
    }
  } catch (error) {
    if (preparedPayment?.localPaymentId) {
      await reconcileRejectedServerPayment(context.paymentId || requestedPaymentId).catch(() => undefined);
      await syncMemberDiscountCouponsFromServer().catch(() => false);
    }
    const serverCode = paymentServerErrorCode(error);
    if (["membership_enrollment_required", "group_enrollment_required", "group_partner_required"].includes(serverCode)) {
      closePaymentConfirmationModal();
      await syncMemberEnrollmentFromServer();
      openMemberEnrollmentModal(product.id, "2대1 동반 회원 정보를 포함해 수강 가입서를 확인해 주세요.");
      return;
    }
    if (serverCode === "login_required") {
      closePaymentConfirmationModal();
      markTicketSyncLoginNeeded();
      state.pendingPaymentCheckStatus = { tone: "alert", text: "서버 로그인 후 결제할 수 있습니다. 간편 로그인으로 다시 접속해 주세요." };
      state.ticketHistory.unshift({ text: `${product.title} 결제 전 서버 로그인 필요`, tone: "alert" });
      renderAll();
      setView("shopView");
      return;
    }
    await applyPaymentPreparationFailure(error);
    const detail = paymentServerErrorMessage(error);
    const diagnosticCode = reportPaymentProviderError(error, "payment_window_open");
    createPaymentRecord(product, {
      paymentId: context.paymentId || requestedPaymentId,
      serverPaymentId: preparedPayment?.localPaymentId || "",
      method: "결제창 오류",
      status: `결제창을 열지 못했습니다. ${detail}`,
    });
    await syncMemberPendingPaymentsFromServer();
    state.pendingPaymentCheckStatus = { tone: "alert", text: `결제창을 열지 못했습니다. ${detail}` };
    state.ticketHistory.unshift({ text: `${product.title} 결제창 오류 · ${detail}`, tone: "alert" });
    purchaseFlowState().paymentErrorCode = diagnosticCode;
    purchaseFlowState().paymentErrorMessage = detail;
    const bankButton = $("#switchPaymentToBankTransferButton");
    if (bankButton) bankButton.hidden = !isPaymentGatewayReady("bank_transfer");
    context.preparedPayment = null;
    context.paymentId = createProviderPaymentId(product.id);
    if (message) message.textContent = `${detail} 선택 내용은 유지됩니다. 다시 시도해 주세요.`;
    if (button) {
      button.disabled = false;
      button.textContent = "다시 시도";
    }
    return;
  }

  closePaymentConfirmationModal();
  await Promise.allSettled([syncMemberTicketsFromServer(), syncMemberPendingPurchaseSchedulesFromServer(), syncMemberPendingPaymentsFromServer(), syncMemberDiscountCouponsFromServer()]);
  renderAll();
  setView("shopView");
}

async function startProductPayment(productId, options = {}) {
  const product = membershipProducts().find((item) => item.id === productId);
  if (!product) return;
  const methodId = normalizeSelectedPaymentMethod();
  const paymentAmount = purchasePaymentAmount(product, methodId);
  if (!paymentAmount || product.status === "consult") {
    requestProduct(productId);
    const flow = purchaseFlowState();
    flow.productId = product.id;
    flow.open = true;
    flow.step = 4;
    flow.completionStatus = "상담 요청이 접수되었습니다";
    saveSnapshot();
    renderProducts();
    return;
  }

  const method = paymentMethodDefinition(methodId);
  if (!options.skipEnrollmentGate && state.member && !memberEnrollmentAllowsProduct(product)) {
    openMemberEnrollmentModal(productId);
    return;
  }
  if (!hasLiveMemberSession()) {
    markTicketSyncLoginNeeded();
    state.pendingPaymentCheckStatus = { tone: "alert", text: "서버 로그인 후 결제할 수 있습니다. 간편 로그인으로 다시 접속해주세요." };
    state.ticketHistory.unshift({ text: `${product.title} 결제 전 서버 로그인 필요`, tone: "alert" });
    renderAll();
    setView("shopView");
    return;
  }
  const pricingQuote = membershipPricingQuote(product);
  const paymentId = pricingQuote?.eligible && pricingQuote?.reservedPaymentId
    ? String(pricingQuote.reservedPaymentId)
    : createProviderPaymentId(product.id);
  if (!isPaymentGatewayReady(methodId)) {
    createPaymentRecord(product, {
      paymentId,
      method: `${method.label} 설정 필요`,
      status: `${product.flow} · 결제 채널 연결 후 결제 가능`,
    });
    state.ticketHistory.unshift({ text: `${product.title} 결제 준비 · ${method.label} 연결 필요`, tone: "alert" });
    renderAll();
    setView("shopView");
    return;
  }
  if (methodId === "naverpay" && paymentAmount < 100) {
    state.pendingPaymentCheckStatus = { tone: "alert", text: "네이버페이는 100원 이상부터 결제할 수 있습니다." };
    renderAll();
    setView("shopView");
    return;
  }

  if (methodId === "bank_transfer") {
    clearPurchasePaymentError();
    try {
      const prepared = await prepareServerPayment(product, paymentId, methodId);
      const effectivePaymentId = String(prepared?.paymentId || paymentId);
      createPaymentRecord(product, {
        paymentId: effectivePaymentId,
        serverPaymentId: prepared?.localPaymentId || "",
        methodId,
        method: method.label,
        status: "입금 확인 대기",
        bankTransferAccount: prepared?.bankTransferAccount || null,
      });
      state.pendingPaymentCheckStatus = {
        tone: "wait",
        text: prepared?.reusedPurchaseIntent
          ? "진행 중인 계좌이체 요청을 다시 열었습니다. 같은 요청은 한 건으로 관리됩니다."
          : "계좌이체 신청이 접수되었습니다. 입금 확인 후 회원권이 발급됩니다.",
      };
      state.ticketHistory.unshift({ text: `${product.title} 계좌이체 신청 · 입금 확인 대기`, tone: "wait" });
      completeMembershipPurchaseFlow("계좌이체 신청이 접수되었습니다");
      await Promise.allSettled([syncMemberPendingPurchaseSchedulesFromServer(), syncMemberPendingPaymentsFromServer(), syncMemberDiscountCouponsFromServer()]);
      saveSnapshot();
      renderAll();
      setView("shopView");
      openBankTransferInstructions(prepared, product, paymentAmount);
    } catch (error) {
      const flow = purchaseFlowState();
      const serverCode = String(error?.payload?.code || error?.message || "bank_transfer_request_failed");
      await applyPaymentPreparationFailure(error);
      const detail = paymentServerErrorMessage(error);
      flow.paymentErrorCode = serverCode;
      if (serverCode === "bank_transfer_account_not_ready") {
        await syncMemberPaymentOptionsFromServer(product.branchId).catch(() => false);
        state.selectedPaymentMethod = "tosspay";
        normalizeSelectedPaymentMethod();
        flow.paymentErrorMessage = "현재 계좌이체를 사용할 수 없어 토스페이로 변경했습니다. 선택한 상품·시간·쿠폰은 유지됩니다.";
      } else if (serverCode === "bank_transfer_account_lookup_failed") {
        flow.paymentErrorMessage = "입금 계좌를 확인하지 못했습니다. 선택 내용은 유지했으며 다시 확인할 수 있습니다.";
      } else {
        flow.paymentErrorMessage = `계좌이체 신청에 실패했습니다. ${detail}`;
      }
      state.pendingPaymentCheckStatus = { tone: "alert", text: flow.paymentErrorMessage };
      state.ticketHistory.unshift({ text: `${product.title} 계좌이체 신청 실패 · ${detail}`, tone: "alert" });
      saveSnapshot();
      renderAll();
      setView("shopView");
    }
    return;
  }

  try {
    const sdk = await loadPortOneSdk();
    openPaymentConfirmationModal({ product, paymentId, preparedPayment: null, methodId, sdk });
  } catch (error) {
    const detail = paymentServerErrorMessage(error);
    reportPaymentProviderError(error, "payment_sdk_load");
    state.pendingPaymentCheckStatus = { tone: "alert", text: `결제창 준비에 실패했습니다. ${detail}` };
    state.ticketHistory.unshift({ text: `${product.title} 결제창 준비 실패 · ${detail}`, tone: "alert" });
    renderAll();
    setView("shopView");
  }
}

const journalCalendarWeekdays = ["월", "화", "수", "목", "금", "토", "일"];

function normalizeJournalCalendarViewMode(mode = "") {
  return String(mode || "").toLowerCase() === "week" ? "week" : "month";
}

function journalWeekDateValues(dateValue = "") {
  const normalizedDate = normalizeJournalNavigationDate(dateValue) || localDateKey();
  const anchor = new Date(`${normalizedDate}T12:00:00`);
  const mondayOffset = (anchor.getDay() + 6) % 7;
  anchor.setDate(anchor.getDate() - mondayOffset);
  return Array.from({ length: 7 }, (_, index) => {
    const value = new Date(anchor);
    value.setDate(anchor.getDate() + index);
    return localDateKey(value);
  });
}

function journalWeekRangeLabel(dateValues = []) {
  const first = normalizeJournalNavigationDate(dateValues[0]);
  const last = normalizeJournalNavigationDate(dateValues[dateValues.length - 1]);
  if (!first || !last) return "";
  const [firstYear, firstMonth, firstDay] = first.split("-").map(Number);
  const [lastYear, lastMonth, lastDay] = last.split("-").map(Number);
  if (firstYear === lastYear && firstMonth === lastMonth) return `${firstYear}년 ${firstMonth}월 ${firstDay}일~${lastDay}일`;
  if (firstYear === lastYear) return `${firstYear}년 ${firstMonth}월 ${firstDay}일~${lastMonth}월 ${lastDay}일`;
  return `${firstYear}년 ${firstMonth}월 ${firstDay}일~${lastYear}년 ${lastMonth}월 ${lastDay}일`;
}

function journalCalendarEntryLabel(dayEntries = [], hasLesson = false) {
  if (dayEntries.length > 1) return `${dayEntries.length}건`;
  return dayEntries[0]?.kind || (hasLesson ? "수업" : "");
}

function setJournalCalendarViewMode(mode = "month") {
  const normalizedMode = normalizeJournalCalendarViewMode(mode);
  const changed = normalizeJournalCalendarViewMode(state.journalCalendarViewMode) !== normalizedMode;
  state.journalCalendarViewMode = normalizedMode;
  renderJournalCalendar();
  return changed;
}

function renderJournalCalendar() {
  const target = $("#journalCalendar");
  if (!target) return;
  const todayValue = localDateKey();
  const selectedDate = normalizeJournalNavigationDate(state.selectedJournalDate) || todayValue;
  const monthValue = state.activeJournalMonth || selectedDate.slice(0, 7);
  const viewMode = normalizeJournalCalendarViewMode(state.journalCalendarViewMode);
  state.journalCalendarViewMode = viewMode;
  const [yearText, monthText] = monthValue.split("-");
  const year = Number(yearText);
  const monthIndex = Number(monthText) - 1;
  const dayCount = new Date(year, monthIndex + 1, 0).getDate();
  const firstWeekday = (new Date(year, monthIndex, 1).getDay() + 6) % 7;
  const dateValues = viewMode === "week"
    ? journalWeekDateValues(selectedDate)
    : Array.from({ length: dayCount }, (_, index) => `${monthValue}-${String(index + 1).padStart(2, "0")}`);
  const visibleDates = new Set(dateValues);
  const query = (state.journalSearchQuery || "").trim();
  const entries = journalEntries();
  const lessonDates = new Set(entries.filter((entry) => entry.kind === "레슨" && visibleDates.has(entry.dateValue)).map((entry) => entry.dateValue));
  const entriesByDate = entries.reduce((map, entry) => {
    if (!visibleDates.has(entry.dateValue) || !journalMatchesSearch(entry, query)) return map;
    if (!map.has(entry.dateValue)) map.set(entry.dateValue, []);
    map.get(entry.dateValue).push(entry);
    return map;
  }, new Map());
  const weekdays = journalCalendarWeekdays.map((day) => `<b>${day}</b>`).join("");
  const emptyMarkup = viewMode === "month"
    ? Array.from({ length: firstWeekday }, () => `<span class="calendar-empty"></span>`).join("")
    : "";
  const daysMarkup = dateValues.map((dateValue) => {
    const [, dateMonth, dateDay] = dateValue.split("-").map(Number);
    const dayEntries = entriesByDate.get(dateValue) || [];
    const hasRecord = dayEntries.length > 0;
    const hasLesson = lessonDates.has(dateValue);
    const label = journalCalendarEntryLabel(dayEntries, hasLesson);
    const accessibleLabel = label || "기록 없음";
    const dayLabel = viewMode === "week" ? `${dateMonth}/${dateDay}` : String(dateDay);
    return `
      <button class="journal-day ${hasRecord ? "has-record" : ""} ${hasLesson ? "has-lesson" : ""} ${selectedDate === dateValue ? "is-selected" : ""} ${query && hasRecord ? "matches-search" : ""}" type="button" data-select-journal-date="${dateValue}" aria-label="${dateValue} ${accessibleLabel}">
        <strong>${dayLabel}</strong>
        ${label ? `<span>${label}</span>` : ""}
      </button>`;
  }).join("");
  target.classList.toggle("is-week-view", viewMode === "week");
  target.innerHTML = `<div class="calendar-weekdays">${weekdays}</div><div class="calendar-days ${viewMode === "week" ? "is-week-view" : ""}">${emptyMarkup}${daysMarkup}</div>`;
  const weekLabel = journalWeekRangeLabel(dateValues);
  const visiblePeriodLabel = viewMode === "week" ? weekLabel : `${year}년 ${monthIndex + 1}월`;
  const monthLabel = $("#journalMonthLabel");
  if (monthLabel) monthLabel.textContent = visiblePeriodLabel;
  const controlLabel = $("#journalCalendarControlLabel");
  if (controlLabel) controlLabel.textContent = visiblePeriodLabel;
  const monthPickerButton = $("#journalMonthPickerButton");
  if (monthPickerButton) monthPickerButton.setAttribute("aria-label", `${visiblePeriodLabel}, 연·월 선택`);
  const previousButton = $("#journalPrevMonth");
  const nextButton = $("#journalNextMonth");
  const periodUnit = viewMode === "week" ? "주" : "달";
  if (previousButton) {
    previousButton.setAttribute("aria-label", `이전 ${periodUnit}`);
    previousButton.title = `이전 ${periodUnit}`;
  }
  if (nextButton) {
    nextButton.setAttribute("aria-label", `다음 ${periodUnit}`);
    nextButton.title = `다음 ${periodUnit}`;
  }
  $$('[data-journal-calendar-view]').forEach((button) => {
    const active = button.dataset.journalCalendarView === viewMode;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", String(active));
  });
  const jumpInput = $("#journalJumpDate");
  if (jumpInput && jumpInput.value !== selectedDate) jumpInput.value = selectedDate;
  const searchInput = $("#journalSearch");
  if (searchInput && searchInput.value !== query) searchInput.value = query;
  renderSelectedJournalDayPanel();
}

const journalActivityStatuses = [
  { key: "scheduled", label: () => memberStatusLabel("lesson", "scheduled", "예정") },
  { key: "completed", label: () => memberStatusLabel("lesson", "completed", "완료") },
  { key: "absent", label: () => memberStatusLabel("lesson", "absent", "불참") },
  { key: "no_show", label: () => memberStatusLabel("lesson", "no_show", "노쇼") },
  { key: "makeup_booked", label: () => memberStatusLabel("lesson", "makeup_booked", "보강 예약") },
];

function journalActivityLessonStatus(lesson) {
  const source = String(lesson.lessonSource || lesson.lesson_source || "").toLowerCase();
  const status = String(lesson.serverStatus || lesson.status || "scheduled").toLowerCase();
  if (source === "makeup" || String(lesson.type || "").includes("보강")) return "makeup_booked";
  if (status === "no_show") return "no_show";
  if (["absence", "absent"].includes(status)) return "absent";
  if (["completed", "confirmed"].includes(status)) return "completed";
  if (["scheduled", "pending_change", "requested"].includes(status)) return "scheduled";
  return "";
}

function journalActivityItems() {
  const monthValue = state.activeJournalMonth || (state.selectedJournalDate || localDateKey()).slice(0, 7);
  const sourceLessons = state.liveLessonsLoaded ? state.liveLessons : memberScheduleLessons();
  const seenLessons = new Set();
  const lessonItems = sourceLessons
    .filter((lesson) => isOwnMemberScheduleLesson(lesson))
    .map((lesson) => {
      const id = String(lesson.serverLessonId || lesson.id || "");
      const dateValue = lesson.lessonDate || memberScheduleDateForDay(lesson.day);
      const status = journalActivityLessonStatus(lesson);
      return { id, dateValue, status };
    })
    .filter((item) => {
      if (!item.id || seenLessons.has(item.id) || !item.status || !item.dateValue?.startsWith(monthValue)) return false;
      seenLessons.add(item.id);
      return true;
    });

  const absenceItems = (state.liveMakeupEntitlements || [])
    .filter((entitlement) => (
      entitlement.lessonDate?.startsWith(monthValue)
      && !seenLessons.has(String(entitlement.sourceLessonId || ""))
    ))
    .map((entitlement) => ({
      id: `absence-${entitlement.id}`,
      dateValue: entitlement.lessonDate,
      status: "absent",
    }));

  return [...lessonItems, ...absenceItems];
}

function renderJournalActivitySummary() {
  const target = $("#journalActivitySummary");
  if (!target) return;
  const items = journalActivityItems();
  target.innerHTML = journalActivityStatuses.map((definition) => {
    const matches = items.filter((item) => item.status === definition.key);
    return `
      <button class="journal-activity-chip" type="button" data-journal-activity-status="${definition.key}" ${matches.length ? "" : "disabled"}>
        <span>${definition.label()}</span>
        <strong>${matches.length}</strong>
      </button>`;
  }).join("");
}

function focusJournalActivity(status) {
  const today = localDateKey();
  const matches = journalActivityItems()
    .filter((item) => item.status === status)
    .sort((left, right) => {
      const leftFuture = left.dateValue >= today ? 0 : 1;
      const rightFuture = right.dateValue >= today ? 0 : 1;
      return leftFuture - rightFuture || left.dateValue.localeCompare(right.dateValue);
    });
  if (!matches.length) return;
  const calendarDisclosure = $("#journalCalendarDisclosure");
  if (calendarDisclosure) {
    calendarDisclosure.open = true;
    calendarDisclosure.dataset.userToggled = "true";
  }
  selectJournalDate(matches[0].dateValue);
  $("#journalSelectedDayPanel")?.scrollIntoView({ behavior: "smooth", block: "start" });
}

function journalEntries() {
  const lessonEntries = state.lessonLogs.map((log) => {
    const dateValue = log.journalDate || new Date(log.submittedAt || Date.now()).toISOString().slice(0, 10);
    return {
      id: log.id,
      serverLessonId: log.serverLessonId || "",
      lessonId: log.lessonId || "",
      kind: "레슨",
      day: new Date(`${dateValue}T00:00:00`).getDate(),
      dateLabel: dateValue,
      dateValue,
      title: lessonReviewTitle(log),
      subtitle: log.lessonLabel,
      body: log.selfMemo,
      note: log.coachComment || "코치 피드백 대기",
      next: log.memberVisibleSummary || selectedNextText(log),
      outcome: log.participantOutcome || "",
      deductedSessions: Number(log.deductedSessions) || (log.ticketDeducted ? 1 : 0),
      sessionSnapshot: log.sessionSnapshot || null,
      sessionRoundLabel: log.sessionRoundLabel || memberTicketSessionSnapshot(log).label,
      curriculumStep: curriculumById(log.nextCurriculumId || log.curriculum?.id, log.curriculum),
      mediaNames: log.mediaNames || [],
      mediaItems: normalizeMediaItems(log),
    };
  });
  const practiceEntries = state.practiceLogs.map((log) => {
    const dateValue = log.journalDate || new Date(log.submittedAt || Date.now()).toISOString().slice(0, 10);
    return {
      id: log.id,
      kind: "개인운동",
      day: new Date(`${dateValue}T00:00:00`).getDate(),
      dateLabel: dateValue,
      dateValue,
      title: `${log.type} 기록`,
      subtitle: log.date,
      body: log.memo,
      note: log.coachFeedback || log.feedbackStatus || "개인 기록",
      next: log.next,
      mediaNames: log.mediaNames || [],
      mediaItems: normalizeMediaItems(log),
    };
  });
  return [...lessonEntries, ...practiceEntries];
}

function journalMatchesSearch(entry, rawQuery) {
  const query = (rawQuery || "").trim().toLowerCase();
  if (!query) return true;
  return [entry.kind, entry.dateLabel, entry.title, entry.subtitle, entry.body, entry.note, entry.next, ...(entry.mediaNames || [])]
    .some((value) => `${value || ""}`.toLowerCase().includes(query));
}

function selectedJournalEntries() {
  const selectedDate = state.selectedJournalDate || localDateKey();
  const query = state.journalSearchQuery || "";
  return journalEntries().filter((entry) => entry.dateValue === selectedDate && journalMatchesSearch(entry, query));
}

function renderSelectedJournalCard(entry) {
  const statusText = entry.note && entry.note !== "개인 기록" ? entry.note : entry.kind === "레슨" ? "수업 기록" : "개인 기록";
  return `
    <article class="journal-selected-card ${entry.kind === "레슨" ? "lesson" : "practice"}">
      <div class="journal-selected-card-head">
        <span>${entry.kind}</span>
        <strong>${escapeHtml(entry.title)}</strong>
        <small>${escapeHtml(entry.subtitle || entry.dateLabel)}</small>
      </div>
      <div class="journal-selected-card-action">
        <span>${escapeHtml(statusText)}${entry.mediaNames?.length ? ` · 첨부 ${entry.mediaNames.length}개` : ""}</span>
        <button class="small-button" type="button" data-open-journal-detail="${escapeHtml(entry.id)}">내용 보기</button>
      </div>
    </article>`;
}

function renderSelectedJournalDayPanel() {
  const target = $("#journalSelectedDayPanel");
  if (!target) return;
  renderPersonalJournalReadStatus();
  const selectedDate = state.selectedJournalDate || localDateKey();
  const dateLabel = new Date(`${selectedDate}T00:00:00`).toLocaleDateString("ko-KR", { month: "long", day: "numeric", weekday: "short" });
  const query = (state.journalSearchQuery || "").trim();
  const entries = selectedJournalEntries();
  const readError = personalJournalListErrorMarkup();
  target.innerHTML = `
    <div class="journal-selected-heading">
      <div>
        <strong>${dateLabel}</strong>
        <span>${query ? `"${query}" 검색 결과` : "선택한 날짜 기록"}</span>
      </div>
      <button class="small-button" type="button" data-journal-write-date="${selectedDate}">이 날짜에 기록</button>
    </div>
    <div class="journal-selected-list">
      ${entries.length ? entries.map(renderSelectedJournalCard).join("") : readError ? "" : memberEmptyState({
        title: "이 날짜의 운동 기록이 없습니다",
        reason: "레슨 또는 개인운동 내용을 사진·영상과 함께 남길 수 있습니다.",
        compact: true,
      })}
    </div>`;
}

function selectJournalDate(dateValue) {
  applyJournalNavigationDate(dateValue);
}

function returnJournalToToday() {
  const todayValue = localDateKey();
  const changed = applyJournalNavigationDate(todayValue);
  if (!changed) renderJournalCalendar();
  return changed;
}

function applyJournalMonthNavigation(monthValue, options = {}) {
  const normalizedMonth = normalizeJournalMonthValue(monthValue);
  if (!normalizedMonth) return false;
  const selectedDate = normalizeJournalNavigationDate(state.selectedJournalDate) || localDateKey();
  const nextDate = selectedDate.startsWith(normalizedMonth) ? selectedDate : `${normalizedMonth}-01`;
  const changed = state.activeJournalMonth !== normalizedMonth || state.selectedJournalDate !== nextDate;
  state.activeJournalMonth = normalizedMonth;
  state.selectedJournalDate = nextDate;
  if (options.render !== false) renderJournalCalendar();
  if (changed && options.persist !== false) saveSnapshot();
  return changed;
}

function setJournalMonthPickerStatus(message = "", tone = "") {
  const status = $("#journalMonthPickerStatus");
  if (!status) return;
  status.textContent = String(message || "");
  if (tone) status.dataset.tone = tone;
  else delete status.dataset.tone;
}

function prepareJournalMonthPicker(monthValue = "") {
  const normalizedMonth = normalizeJournalMonthValue(monthValue)
    || normalizeJournalMonthValue(state.activeJournalMonth)
    || localDateKey().slice(0, 7);
  const [yearValue, monthNumber] = normalizedMonth.split("-");
  const yearSelect = $("#journalMonthPickerYear");
  const monthSelect = $("#journalMonthPickerMonth");
  if (!yearSelect || !monthSelect) return normalizedMonth;
  if (!yearSelect.options.length) {
    yearSelect.innerHTML = Array.from(
      { length: journalMonthPickerMaxYear - journalMonthPickerMinYear + 1 },
      (_, index) => {
        const year = journalMonthPickerMinYear + index;
        return `<option value="${year}">${year}년</option>`;
      },
    ).join("");
  }
  if (!monthSelect.options.length) {
    monthSelect.innerHTML = Array.from({ length: 12 }, (_, index) => {
      const month = String(index + 1).padStart(2, "0");
      return `<option value="${month}">${index + 1}월</option>`;
    }).join("");
  }
  yearSelect.value = yearValue;
  monthSelect.value = monthNumber;
  setJournalMonthPickerStatus();
  return normalizedMonth;
}

function openJournalMonthPicker() {
  const sheet = $("#journalMonthPickerSheet");
  if (!sheet || (!sheet.hidden && activeAppSheetId === sheet.id)) return false;
  prepareJournalMonthPicker();
  $("#journalMonthPickerButton")?.setAttribute("aria-expanded", "true");
  openAppSheet(sheet.id, { initialFocus: "#journalMonthPickerYear" });
  return true;
}

function closeJournalMonthPicker(fromHistory = false) {
  $("#journalMonthPickerButton")?.setAttribute("aria-expanded", "false");
  return closeAppSheet("journalMonthPickerSheet", fromHistory);
}

function applyJournalMonthPicker() {
  const yearValue = $("#journalMonthPickerYear")?.value || "";
  const monthValue = $("#journalMonthPickerMonth")?.value || "";
  const normalizedMonth = normalizeJournalMonthValue(`${yearValue}-${monthValue}`);
  if (!normalizedMonth) {
    setJournalMonthPickerStatus("선택한 연·월을 다시 확인해 주세요.", "error");
    $("#journalMonthPickerYear")?.focus({ preventScroll: true });
    return false;
  }
  const changed = applyJournalMonthNavigation(normalizedMonth);
  closeJournalMonthPicker();
  return changed;
}

function changeJournalMonth(delta) {
  const selectedDate = state.selectedJournalDate || localDateKey();
  const monthValue = state.activeJournalMonth || selectedDate.slice(0, 7);
  const [yearText, monthText] = monthValue.split("-");
  const nextMonth = new Date(Number(yearText), Number(monthText) - 1 + delta, 1);
  const nextMonthValue = `${nextMonth.getFullYear()}-${String(nextMonth.getMonth() + 1).padStart(2, "0")}`;
  applyJournalMonthNavigation(nextMonthValue);
}

function changeJournalWeek(delta) {
  const selectedDate = normalizeJournalNavigationDate(state.selectedJournalDate) || localDateKey();
  const nextDate = new Date(`${selectedDate}T12:00:00`);
  nextDate.setDate(nextDate.getDate() + (Number(delta) || 0) * 7);
  applyJournalNavigationDate(localDateKey(nextDate));
}

function changeJournalCalendarPeriod(delta) {
  if (normalizeJournalCalendarViewMode(state.journalCalendarViewMode) === "week") {
    changeJournalWeek(delta);
    return;
  }
  changeJournalMonth(delta);
}

let activeAppSheetId = "";
let activeAppModalId = "";
let appModalReturnFocus = null;
let appSheetScrollLock = null;

function lockAppSheetBackground() {
  if (appSheetScrollLock) return;
  const scrollY = Math.max(0, window.scrollY || window.pageYOffset || 0);
  appSheetScrollLock = {
    scrollY,
    bodyPosition: document.body.style.position,
    bodyTop: document.body.style.top,
    bodyLeft: document.body.style.left,
    bodyRight: document.body.style.right,
    bodyWidth: document.body.style.width,
    htmlOverscrollBehavior: document.documentElement.style.overscrollBehavior,
  };
  document.body.style.position = "fixed";
  document.body.style.top = `-${scrollY}px`;
  document.body.style.left = "0";
  document.body.style.right = "0";
  document.body.style.width = "100%";
  document.documentElement.style.overscrollBehavior = "none";
}

function unlockAppSheetBackground() {
  if (!appSheetScrollLock) return;
  const saved = appSheetScrollLock;
  appSheetScrollLock = null;
  document.body.style.position = saved.bodyPosition;
  document.body.style.top = saved.bodyTop;
  document.body.style.left = saved.bodyLeft;
  document.body.style.right = saved.bodyRight;
  document.body.style.width = saved.bodyWidth;
  document.documentElement.style.overscrollBehavior = saved.htmlOverscrollBehavior;
  window.scrollTo({ top: saved.scrollY, left: 0, behavior: "auto" });
}

function refreshAppSheetState() {
  const sheetOpen = Boolean(activeAppSheetId);
  document.body.classList.toggle("sheet-open", sheetOpen);
  if (sheetOpen) lockAppSheetBackground();
  else unlockAppSheetBackground();
}

function openAppSheet(sheetId, options = {}) {
  const target = $(`#${sheetId}`);
  if (!target) return;
  if (activeAppSheetId && activeAppSheetId !== sheetId) {
    closeAppSheet(activeAppSheetId, true, { restoreFocus: false, immediate: true });
  }
  activeAppSheetId = sheetId;
  if (window.TennisNoteBottomSheet?.open?.(target, options)) return;
  target.hidden = false;
  refreshAppSheetState();
  if (options.history !== false) {
    const historyState = typeof history.state === "object" && history.state ? history.state : {};
    if (historyState.tennisNoteSheet !== sheetId) {
      history.pushState({ ...historyState, tennisNoteSheet: sheetId }, "", window.location.href);
    }
  }
}

function closeAppSheet(sheetId, fromHistory = false, options = {}) {
  const target = $(`#${sheetId}`);
  if (!target) return false;
  if (activeAppSheetId === sheetId) activeAppSheetId = "";
  if (window.TennisNoteBottomSheet?.close?.(target, { ...options, fromHistory })) return true;
  target.hidden = true;
  refreshAppSheetState();
  if (!fromHistory && history.state?.tennisNoteSheet === sheetId) history.back();
  return true;
}

function closeVisibleAppSheet(fromHistory = false, options = {}) {
  const trackedSheet = activeAppSheetId ? $(`#${activeAppSheetId}`) : null;
  const visibleSheet = trackedSheet && !trackedSheet.hidden
    ? trackedSheet
    : document.querySelector(".app-bottom-sheet:not([hidden])");
  if (!visibleSheet?.id) return false;
  closeAppSheet(visibleSheet.id, fromHistory, options);
  return true;
}

function focusableElements(container) {
  if (!container) return [];
  return [...container.querySelectorAll(
    'button:not([disabled]), a[href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
  )].filter((element) => !element.hidden && element.getClientRects().length > 0);
}

function refreshAppModalState() {
  const modalOpen = Boolean(activeAppModalId);
  document.body.classList.toggle("modal-open", modalOpen);
  const tabbar = $(".tabbar");
  if (tabbar) {
    if (modalOpen) tabbar.setAttribute("aria-hidden", "true");
    else tabbar.removeAttribute("aria-hidden");
  }
}

function openAppModal(modalId, focusSelector = "") {
  const target = $(`#${modalId}`);
  if (!target) return;
  if (activeAppModalId && activeAppModalId !== modalId) closeAppModal(activeAppModalId, true);
  appModalReturnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  target.hidden = false;
  activeAppModalId = modalId;
  refreshAppModalState();
  stabilizeMemberVisualViewport();
  const historyState = typeof history.state === "object" && history.state ? history.state : {};
  if (historyState.tennisNoteModal !== modalId) {
    history.pushState({ ...historyState, tennisNoteModal: modalId }, "", window.location.href);
  }
  window.setTimeout(() => {
    const preferred = focusSelector ? target.querySelector(focusSelector) : null;
    const focusTarget = preferred && !preferred.disabled ? preferred : focusableElements(target)[0];
    focusTarget?.focus({ preventScroll: true });
  }, 40);
}

function closeAppModal(modalId, fromHistory = false) {
  const target = $(`#${modalId}`);
  if (!target) return;
  target.hidden = true;
  if (activeAppModalId === modalId) activeAppModalId = "";
  refreshAppModalState();
  stabilizeMemberVisualViewport();
  if (!fromHistory && history.state?.tennisNoteModal === modalId) {
    history.back();
    return;
  }
  appModalReturnFocus?.focus?.({ preventScroll: true });
  appModalReturnFocus = null;
}

function closeVisibleAppModal(fromHistory = false) {
  const trackedModal = activeAppModalId ? $(`#${activeAppModalId}`) : null;
  const visibleModal = trackedModal && !trackedModal.hidden
    ? trackedModal
    : document.querySelector(".change-request-modal:not([hidden]), .modal:not([hidden])");
  if (!visibleModal?.id) return false;
  closeAppModal(visibleModal.id, fromHistory);
  return true;
}

