function normalizeIdentityText(value = "") {
  return String(value || "").trim().replace(/\s+/gu, " ");
}

function normalizeIdentityPhone(value = "") {
  return String(value || "").replace(/\D/gu, "");
}

function formatIdentityPhone(value = "") {
  const digits = normalizeIdentityPhone(value).slice(0, 11);
  if (digits.length === 11) return `${digits.slice(0, 3)}-${digits.slice(3, 7)}-${digits.slice(7)}`;
  if (digits.length === 10) return `${digits.slice(0, 3)}-${digits.slice(3, 6)}-${digits.slice(6)}`;
  return digits;
}

function identityPhoneE164(value = "") {
  const digits = normalizeIdentityPhone(value);
  if (digits.startsWith("82") && digits.length >= 11) return `+${digits}`;
  if (digits.startsWith("0") && digits.length >= 10) return `+82${digits.slice(1)}`;
  return "";
}

function verifiedPhoneFromAuthUser(user = {}, strict = false) {
  const directPhone = normalizeIdentityPhone(user?.phone || "");
  const canonicalDirect = directPhone.startsWith("82") ? `0${directPhone.slice(2)}` : directPhone;
  const confirmedAt = Date.parse(user?.phone_confirmed_at || "");
  if (directPhone && user?.phone_confirmed_at && (!strict || (/^01[0-9]{8,9}$/u.test(canonicalDirect)
    && Number.isFinite(confirmedAt) && confirmedAt <= Date.now()))) return canonicalDirect;
  if (strict) {
    const phones = [...new Set((Array.isArray(user.identities) ? user.identities : [])
      .filter((identity) => ["custom:naver", "custom:kakao"].includes(identity.provider))
      .map((identity) => identity.identity_data || {})
      .filter((data) => [data.phone_number_verified, data.phone_verified, data.mobile_verified, data.verified_phone]
        .some((value) => value === true || value === "true" || value === "1"))
      .map((data) => normalizeIdentityPhone(data.phone_number || data.phone || data.mobile || ""))
      .map((phone) => phone.startsWith("82") ? `0${phone.slice(2)}` : phone)
      .filter((phone) => /^01[0-9]{8,9}$/u.test(phone)))];
    return phones.length === 1 ? phones[0] : "";
  }
  const metadata = user?.user_metadata || {};
  const metadataVerified = [
    metadata.phone_number_verified,
    metadata.phone_verified,
    metadata.mobile_verified,
    metadata.verified_phone,
  ].some((value) => value === true || value === "true");
  if (!metadataVerified) return "";
  const metadataPhone = normalizeIdentityPhone(metadata.phone_number || metadata.phone || metadata.mobile || "");
  return metadataPhone.startsWith("82") ? `0${metadataPhone.slice(2)}` : metadataPhone;
}

function authUserHasProvider(user = {}, provider = "") {
  const expected = String(provider || "").trim().toLowerCase();
  if (!expected) return false;
  const appMetadata = user?.app_metadata || {};
  const providers = [appMetadata.provider, ...(Array.isArray(appMetadata.providers) ? appMetadata.providers : [])]
    .concat(Array.isArray(user?.identities) ? user.identities.map((identity) => identity?.provider) : [])
    .map((value) => String(value || "").trim().toLowerCase())
    .filter(Boolean);
  return providers.includes(expected);
}

function phoneVerificationControls(surface = "signup") {
  const prefix = surface === "profile" ? "profilePhone" : "identityPhone";
  return { input: $(surface === "profile" ? "#profilePhoneInput" : "#identityPhone"),
    send: $(`#${prefix}SendButton`), verify: $(`#${prefix}VerifyButton`), code: $(`#${prefix}Code`),
    row: $(`#${prefix}CodeRow`), status: $(`#${prefix}Status`), block: $(`#${prefix}Verification`) };
}

function phoneVerificationState(surface = "signup") {
  return surface === "profile" ? profilePhoneVerification : identityPhoneVerification;
}

function phoneVerificationOwner() {
  const client = window.TennisNoteDataClient;
  return { client, authId: String(client?.getSession?.()?.user?.id || state.member?.authUserId || ""),
    profileId: String(state.liveProfileId || state.member?.profileId || state.member?.id || "") };
}

function phoneVerificationOwnerCurrent(owner) {
  const current = phoneVerificationOwner();
  return Boolean(owner && hasLiveMemberSession() && owner.client === current.client
    && owner.authId === current.authId && owner.profileId === current.profileId);
}

function phoneVerificationRequestCurrent(owner, phone, surface) {
  return phoneVerificationOwnerCurrent(owner)
    && normalizeIdentityPhone(phoneVerificationControls(surface).input?.value || "") === phone;
}

function setIdentityPhoneStatus(message, tone = "", surface = "signup") {
  const target = phoneVerificationControls(surface).status;
  if (!target) return;
  target.textContent = message;
  target.classList.toggle("is-verified", tone === "verified");
  target.classList.toggle("is-error", tone === "error");
}

function normalizedIdentityErrorCode(error) {
  const values = [
    error?.code,
    error?.error_code,
    error?.message,
    error?.payload?.code,
    error?.payload?.error_code,
    error?.payload?.message,
    error?.payload?.error_description,
    typeof error === "string" ? error : "",
  ];
  return values
    .map((value) => String(value || "").trim().toLowerCase())
    .filter(Boolean)
    .join(" ")
    .replace(/[\s-]+/gu, "_");
}

function transientAuthCapabilityError(error) {
  const code = normalizedIdentityErrorCode(error);
  return ["failed_to_fetch", "networkerror", "load_failed", "temporarily_unavailable", "request_timeout"]
    .some((marker) => code.includes(marker));
}

function customOAuthProviderCapability(provider = "") {
  const client = globalThis.window?.TennisNoteDataClient || globalThis.TennisNoteDataClient;
  const fallbackSlug = {
    kakao: "custom:kakao",
    naver: "custom:naver",
  }[String(provider || "").toLowerCase()] || "";
  const slug = String(client?.providerSlug?.(provider) || fallbackSlug).toLowerCase();
  return slug.startsWith("custom:") ? slug : "";
}

function authProviderCapability(settings = {}, provider = "") {
  const external = settings?.external;
  const customSlug = customOAuthProviderCapability(provider);
  if (!external || typeof external !== "object") return customSlug ? true : null;
  const aliases = {
    phone: ["phone"],
    email: ["email"],
    apple: ["apple"],
    kakao: ["custom:kakao", "kakao"],
    naver: ["custom:naver", "naver"],
    google: ["google"],
  }[provider] || [provider];
  const configured = aliases.filter((key) => Object.prototype.hasOwnProperty.call(external, key));
  if (configured.some((key) => external[key] === true)) return true;
  if (customSlug && !Object.prototype.hasOwnProperty.call(external, customSlug)) return true;
  if (configured.length) return false;
  return customSlug ? true : null;
}

function resolvedAuthCapabilities(settings = {}) {
  return {
    phone: authProviderCapability(settings, "phone"),
    email: authProviderCapability(settings, "email"),
    apple: authProviderCapability(settings, "apple"),
    kakao: authProviderCapability(settings, "kakao"),
    naver: authProviderCapability(settings, "naver"),
    google: authProviderCapability(settings, "google") === true,
  };
}

function phoneAuthUnavailableMessage() {
  return "문자 인증을 준비 중입니다. 네이버 번호 다시 받기 또는 관리자 연결을 이용해 주세요.";
}

// Signup keeps verified phone as a required identity input. Provider
// capability still controls whether an OTP request can leave the app.
const signupSmsEnabled = true;
let signupProfileOperation = { fingerprint: "", key: "" };
let signupProfileSubmitting = false;

function syncIdentityPhoneCapabilityControl() {
  syncPhoneVerificationControl("signup");
  syncPhoneVerificationControl("profile");
}

function syncPhoneVerificationControl(surface) {
  const controls = phoneVerificationControls(surface);
  if (!signupSmsEnabled) {
    controls.block?.setAttribute("hidden", "");
    if (controls.send) controls.send.disabled = true;
    if (controls.verify) controls.verify.disabled = true;
    if (surface === "signup" && $("#identityNaverPhoneButton")) $("#identityNaverPhoneButton").disabled = true;
    return;
  }
  controls.block?.removeAttribute("hidden");
  const button = controls.send;
  const verification = phoneVerificationState(surface);
  if (!button) return;
  const exactVerified = verification.status === "verified" && phoneVerificationOwnerCurrent(verification.owner)
    && verification.phone === normalizeIdentityPhone(controls.input?.value || "");
  button.textContent = verification.status === "pending" ? "인증번호 다시 받기" : "인증번호 받기";
  button.disabled = exactVerified || identityPhoneRequestInFlight || identityPhoneConfirmInFlight;
  if (controls.verify) controls.verify.disabled = identityPhoneConfirmInFlight || identityPhoneRequestInFlight;
  if (exactVerified) return;
  if (identityAuthCapabilities.status === "checking") {
    button.disabled = true;
    setIdentityPhoneStatus("문자 인증 가능 여부를 확인하고 있습니다.", "", surface);
    return;
  }
  if (identityAuthCapabilities.providers.phone === false || identityAuthCapabilities.status === "unavailable") {
    button.disabled = true;
    controls.row?.setAttribute("hidden", "");
    setIdentityPhoneStatus(phoneAuthUnavailableMessage(), "error", surface);
    return;
  }
  button.disabled = identityPhoneRequestInFlight || identityPhoneConfirmInFlight;
  if (identityAuthCapabilities.status === "ready" && identityAuthCapabilities.providers.phone === true) {
    const currentStatus = controls.status?.textContent || "";
    if (currentStatus.includes("가능 여부") || currentStatus.includes("설정을 확인하지 못했습니다") || currentStatus.includes("문자 인증을 준비 중")) {
      const naverRepromptAvailable = !$("#identityNaverPhoneButton")?.hidden;
      setIdentityPhoneStatus(surface === "profile" ? "새 번호를 인증한 후 본인 프로필에 저장하세요." : naverRepromptAvailable
        ? "네이버 번호를 다시 받거나 문자 인증 후 기존 회원 DB와 연결합니다."
        : "휴대전화 인증 후 기존 회원 DB와 안전하게 연결합니다.", "", surface);
    }
  }
  if (identityAuthCapabilities.status === "unknown" && identityAuthCapabilities.errorCode) {
    setIdentityPhoneStatus("문자 인증 설정을 확인하지 못했습니다. 입력은 유지되며 다시 시도할 수 있습니다.", "error", surface);
  }
}

function syncAuthProviderCapabilityControls() {
  const providerSelectors = {
    naver: '[data-login-provider="네이버"]',
    kakao: '[data-login-provider="카카오"]',
    apple: '[data-login-provider="Apple"]',
    google: '[data-login-provider="Google"]',
  };
  Object.entries(providerSelectors).forEach(([provider, selector]) => {
    $$(selector).forEach((button) => {
      const available = identityAuthCapabilities.providers[provider];
      if (provider === "apple") {
        button.hidden = false;
        button.disabled = available !== true || Boolean(oauthLoginInFlightProvider);
        button.toggleAttribute("aria-disabled", available !== true);
        if (available === true) button.removeAttribute("aria-describedby");
        else button.setAttribute("aria-describedby", "appleLoginAvailabilityNote");
        return;
      }
      if (available === false) {
        button.hidden = true;
        button.disabled = true;
        button.setAttribute("aria-disabled", "true");
        return;
      }
      if (available === true) {
        button.hidden = false;
        button.removeAttribute("aria-disabled");
        if (!oauthLoginInFlightProvider) button.disabled = false;
      }
    });
  });
  const appleNote = $("#appleLoginAvailabilityNote");
  if (appleNote) {
    const appleCapability = identityAuthCapabilities.providers.apple;
    appleNote.hidden = appleCapability === true;
    appleNote.textContent = appleCapability === false
      ? "Apple 로그인은 개발 환경에서 사용할 수 없습니다. 네이버·카카오 로그인을 이용해 주세요."
      : "Apple 로그인 가능 여부를 확인하지 못했습니다. 네이버·카카오 로그인을 이용해 주세요.";
  }
  const emailPanel = $("#memberEmailAuthPanel");
  if (emailPanel) {
    const emailUiAvailable = emailPasswordSignInUiEnabled();
    emailPanel.hidden = !emailUiAvailable;
    emailPanel.inert = !emailUiAvailable;
    emailPanel.setAttribute("aria-hidden", String(!emailUiAvailable));
    if (emailUiAvailable) setEmailAuthMode("login", { focus: false, clearStatus: false });
  }
  syncIdentityPhoneCapabilityControl();
}

async function refreshAuthProviderCapabilities({ force = false } = {}) {
  const age = Date.now() - Number(identityAuthCapabilities.checkedAt || 0);
  if (!force && identityAuthCapabilities.status === "ready" && age < 60_000) return identityAuthCapabilities;
  if (identityAuthCapabilityPromise) return identityAuthCapabilityPromise;
  const client = window.TennisNoteDataClient;
  if (!client?.readiness?.().ready || !client?.getAuthSettings) {
    identityAuthCapabilities = {
      ...identityAuthCapabilities,
      status: "unavailable",
      providers: {
        ...identityAuthCapabilities.providers,
        phone: false,
        apple: null,
        kakao: authProviderCapability({}, "kakao"),
        naver: authProviderCapability({}, "naver"),
      },
      errorCode: "auth_settings_unavailable",
      checkedAt: Date.now(),
    };
    syncAuthProviderCapabilityControls();
    return identityAuthCapabilities;
  }
  identityAuthCapabilities = { ...identityAuthCapabilities, status: "checking", errorCode: "" };
  syncAuthProviderCapabilityControls();
  identityAuthCapabilityPromise = (async () => {
    try {
      const settings = await client.getAuthSettings();
      identityAuthCapabilities = {
        status: "ready",
        providers: resolvedAuthCapabilities(settings),
        errorCode: "",
        checkedAt: Date.now(),
      };
    } catch (error) {
      const transient = transientAuthCapabilityError(error);
      identityAuthCapabilities = {
        ...identityAuthCapabilities,
        status: transient ? "unknown" : "unavailable",
        providers: {
          ...identityAuthCapabilities.providers,
          phone: transient ? null : false,
          apple: null,
          kakao: authProviderCapability({}, "kakao"),
          naver: authProviderCapability({}, "naver"),
        },
        errorCode: normalizedIdentityErrorCode(error) || "auth_settings_unavailable",
        checkedAt: Date.now(),
      };
    } finally {
      identityAuthCapabilityPromise = null;
      syncAuthProviderCapabilityControls();
    }
    return identityAuthCapabilities;
  })();
  return identityAuthCapabilityPromise;
}

function resetIdentityPhoneVerification(message = "휴대전화 인증이 필요합니다.", surface = "signup") {
  const verification = { phone: "", status: "unverified", source: "" };
  if (surface === "profile") profilePhoneVerification = verification;
  else identityPhoneVerification = verification;
  const controls = phoneVerificationControls(surface);
  if (controls.code) controls.code.value = "";
  if (controls.row) controls.row.hidden = true;
  if (controls.send) controls.send.disabled = false;
  setIdentityPhoneStatus(message, "", surface);
  syncIdentityPhoneCapabilityControl();
}

function markIdentityPhoneVerified(phone, source = "sms", surface = "signup") {
  const normalizedPhone = normalizeIdentityPhone(phone);
  if (surface === "profile" && normalizeIdentityPhone(phoneVerificationControls(surface).input?.value || "") !== normalizedPhone) {
    resetIdentityPhoneVerification("입력 번호가 바뀌었습니다. 현재 번호를 인증한 후 저장하세요.", surface);
    return false;
  }
  const verification = { phone: normalizedPhone, status: "verified", source, owner: phoneVerificationOwner() };
  if (surface === "profile") profilePhoneVerification = verification;
  else identityPhoneVerification = verification;
  const controls = phoneVerificationControls(surface);
  if (controls.input && surface === "signup") controls.input.value = formatIdentityPhone(normalizedPhone);
  if (controls.row) controls.row.hidden = true;
  if (controls.send) controls.send.disabled = true;
  setIdentityPhoneStatus(
    surface === "profile" ? "휴대전화 인증이 완료되었습니다. 저장하면 본인 프로필에 반영됩니다." : source === "provider"
      ? "로그인 제공자가 확인한 번호입니다. 기존 회원 DB 연결에 사용합니다."
      : "휴대전화 인증이 완료되었습니다. 기존 회원 DB 연결에 사용합니다.",
    "verified", surface,
  );
}

function suggestedNicknameFromUser(user = {}) {
  const metadata = user?.user_metadata || {};
  return normalizeIdentityText(
    metadata.nickname
      || metadata.name
      || metadata.full_name
      || metadata.preferred_username
      || "",
  ).slice(0, 20);
