function identityErrorMessage(error) {
  if (String(error?.code || error?.message || "").includes("signup_link_readback_unconfirmed")) {
    return "가입 정보는 저장됐지만 회원권 조회를 확인하지 못했습니다. 입력을 유지한 채 다시 확인해 주세요.";
  }
  const code = normalizedIdentityErrorCode(error);
  if (code.includes("failed_to_fetch") || code.includes("networkerror") || code.includes("load_failed") || code.includes("temporarily_unavailable")) {
    return "인터넷 연결이 불안정합니다. 입력 내용은 유지되니 잠시 후 다시 저장해 주세요.";
  }
  if (code.includes("nickname_already_taken")) return "이미 사용 중인 닉네임입니다. 다른 닉네임을 입력해 주세요.";
  if (code.includes("nickname_invalid") || code.includes("nickname_length_invalid")) return "닉네임은 공백을 제외하고 2~20자로 입력해 주세요.";
  if (code.includes("real_name_invalid")) return "실명을 확인해 주세요.";
  if (code.includes("phone_invalid")) return "휴대전화 번호를 010부터 정확히 입력해 주세요.";
  if (code.includes("phone_verification_required")) return "휴대전화 인증을 먼저 완료해 주세요.";
  if (code.includes("profile_phone_stale") || code.includes("phone_operation_superseded")) return "저장된 번호가 변경되었습니다. 내 정보를 다시 열어 확인해 주세요.";
  if (code.includes("profile_phone_identity_mismatch") || code.includes("profile_phone_context_changed")) return "로그인 정보가 변경되었습니다. 본인 계정으로 다시 확인해 주세요.";
  if (code.includes("profile_phone_readback_unconfirmed")) return "번호 저장 결과를 확인하지 못했습니다. 입력을 유지한 채 다시 확인해 주세요.";
  if (code.includes("over_email_send_rate_limit") || code.includes("rate_limit") || code.includes("too many")) return "인증번호 요청이 많습니다. 잠시 후 다시 시도해 주세요.";
  if (code.includes("phone_provider") || code.includes("sms_provider") || code.includes("sms_send")) return phoneAuthUnavailableMessage();
  if (code.includes("otp_expired") || code.includes("token has expired")) return "인증번호가 만료되었거나 올바르지 않습니다. 새 번호를 받아 다시 입력해 주세요.";
  if (code.includes("phone_otp_invalid") || code.includes("phone_otp_verification_failed")) return "인증번호 6자리를 확인해 주세요.";
  if (code.includes("phone_exists")) return "이미 다른 계정에 연결된 휴대전화입니다. 기존 계정으로 로그인하거나 다른 번호를 사용해 주세요.";
  if (code.includes("phone_change_conflict") || code.includes("phone already")) return "이미 다른 로그인 계정에서 확인된 번호입니다. 관리자에게 계정 연결을 요청해 주세요.";
  if (code.includes("birth_year_invalid")) return "출생연도를 확인해 주세요.";
  if (code.includes("gender_invalid")) return "성별을 선택해 주세요.";
  if (code.includes("terms_consent")) return "서비스 이용약관 동의가 필요합니다.";
  if (code.includes("privacy_consent")) return "개인정보 처리방침 동의가 필요합니다.";
  if (code.includes("login_required")) return "로그인 상태를 다시 확인해 주세요.";
  return "정보를 저장하지 못했습니다. 잠시 후 다시 시도해 주세요.";
}

async function checkNicknameAvailability(inputId, statusId) {
  const nickname = normalizeIdentityText($(`#${inputId}`)?.value || "");
  if (nickname.length < 2 || nickname.length > 20) {
    setNicknameStatus(statusId, "닉네임은 2~20자로 입력해 주세요.", "unavailable");
    return false;
  }
  const client = window.TennisNoteDataClient;
  if (!hasLiveMemberSession() || !client?.rpc) {
    setNicknameStatus(statusId, "실사용 로그인 후 중복을 확인할 수 있습니다.", "unavailable");
    return false;
  }
  setNicknameStatus(statusId, "중복 여부를 확인하고 있습니다.");
  try {
    const rawResult = await client.rpc("tn_check_nickname_available", { target_nickname: nickname });
    const result = Array.isArray(rawResult) ? rawResult[0] : rawResult;
    if (result?.available) {
      setNicknameStatus(statusId, "사용할 수 있는 닉네임입니다.", "available");
      return true;
    }
    setNicknameStatus(statusId, identityErrorMessage(result?.reason || "nickname_already_taken"), "unavailable");
    return false;
  } catch (error) {
    setNicknameStatus(statusId, identityErrorMessage(error), "unavailable");
    return false;
  }
}

function applySavedIdentity(profile = {}, { preserveCompletion = false } = {}) {
  state.profile.name = normalizeIdentityText(profile.name || state.profile.name);
  state.profile.nickname = normalizeIdentityText(profile.nickname || state.profile.nickname);
  state.profile.phone = normalizeIdentityPhone(Object.prototype.hasOwnProperty.call(profile, "phone") ? profile.phone || "" : state.profile.phone);
  state.profile.birthYear = profile.birth_year || state.profile.birthYear || "";
  state.profile.neighborhood = normalizeIdentityText(profile.neighborhood || state.profile.neighborhood || "");
  state.profile.gender = profile.gender || state.profile.gender || "";
  state.profile.profileCompletedAt = preserveCompletion ? profile.profile_completed_at || "" : profile.profile_completed_at || state.profile.profileCompletedAt || new Date().toISOString();
  state.profile.privacyConsentVersion = preserveCompletion ? profile.privacy_consent_version || "" : profile.privacy_consent_version || state.profile.privacyConsentVersion || identityPrivacyVersion;
  state.profile.privacyConsentedAt = preserveCompletion ? profile.privacy_consented_at || "" : profile.privacy_consented_at || state.profile.privacyConsentedAt || new Date().toISOString();
  if (profile.updated_at) state.profile.serverRevision = profile.updated_at;
  if (state.member) {
    state.member.name = state.profile.name;
    state.member.nickname = state.profile.nickname;
  }
}

function applyConsentPreferences(preferences = {}) {
  state.profile.termsConsentVersion = preferences.termsVersion || state.profile.termsConsentVersion || "";
  state.profile.termsConsentedAt = preferences.termsConsentedAt || state.profile.termsConsentedAt || "";
  state.profile.privacyConsentVersion = preferences.privacyVersion || state.profile.privacyConsentVersion || "";
  state.profile.privacyConsentedAt = preferences.privacyConsentedAt || state.profile.privacyConsentedAt || "";
  state.profile.marketingPushConsent = preferences.marketingPush === true;
  state.profile.marketingSmsConsent = preferences.marketingSms === true;
  state.profile.marketingEmailConsent = preferences.marketingEmail === true;
}

async function loadIdentityConsentPreferences() {
  const client = window.TennisNoteDataClient;
  if (!hasLiveMemberSession() || !client?.rpc) return {};
  const rawResult = await retryTransientNetwork(() => client.rpc("tn_my_consent_preferences"));
  const result = Array.isArray(rawResult) ? rawResult[0] : rawResult;
  applyConsentPreferences(result || {});
  return result || {};
}

async function persistConsentPreferences({ marketingPush, marketingSms, marketingEmail }) {
  const client = window.TennisNoteDataClient;
  if (!hasLiveMemberSession() || !client?.rpc) {
    applyConsentPreferences({
      termsVersion: identityTermsVersion,
      termsConsentedAt: new Date().toISOString(),
      privacyVersion: identityPrivacyVersion,
      privacyConsentedAt: new Date().toISOString(),
      marketingPush,
      marketingSms,
      marketingEmail,
    });
    return { ok: true, offlinePreview: true };
  }
  const rawResult = await retryTransientNetwork(() => client.rpc("tn_save_my_consent_preferences", {
    target_terms_version: identityTermsVersion,
    target_privacy_version: identityPrivacyVersion,
    target_terms_consent: true,
    target_privacy_consent: true,
    target_marketing_push: marketingPush === true,
    target_marketing_sms: marketingSms === true,
    target_marketing_email: marketingEmail === true,
  }));
  const result = Array.isArray(rawResult) ? rawResult[0] : rawResult;
  if (!result?.ok) throw new Error("consent_update_not_confirmed");
  applyConsentPreferences(result);
  return result;
}

async function refreshIdentityPhoneVerification(surface = "signup") {
  if (!signupSmsEnabled) return "";
  const client = window.TennisNoteDataClient;
  if (!hasLiveMemberSession() || !client?.getAuthUser) return "";
  const owner = phoneVerificationOwner();
  const inputPhone = normalizeIdentityPhone(phoneVerificationControls(surface).input?.value || "");
  const user = await client.getAuthUser();
  if (!phoneVerificationOwnerCurrent(owner) || (owner.authId && user?.id && user.id !== owner.authId)) return "";
  const verifiedPhone = verifiedPhoneFromAuthUser(user || {}, surface === "profile");
  if (verifiedPhone && ((!inputPhone && surface === "signup") || inputPhone === verifiedPhone)
    && normalizeIdentityPhone(phoneVerificationControls(surface).input?.value || "") === inputPhone) {
    markIdentityPhoneVerified(verifiedPhone, "provider", surface);
  }
  return verifiedPhone;
}

async function requestIdentityPhoneVerification(surface = "signup") {
  if (!signupSmsEnabled) return false;
  const controls = phoneVerificationControls(surface);
  const button = controls.send;
  if (!button || identityPhoneRequestInFlight || identityPhoneConfirmInFlight) return false;
  const phone = normalizeIdentityPhone(controls.input?.value || "");
  const e164Phone = identityPhoneE164(phone);
  if (!/^01[0-9]{8,9}$/u.test(phone) || !e164Phone) {
    setIdentityPhoneStatus("휴대전화 번호를 010부터 정확히 입력해 주세요.", "error", surface);
    controls.input?.focus();
    return false;
  }
  const client = window.TennisNoteDataClient;
  if (!hasLiveMemberSession() || !client?.requestPhoneChangeVerification) {
    setIdentityPhoneStatus("로그인 상태를 다시 확인해 주세요.", "error", surface);
    return false;
  }
  identityPhoneRequestInFlight = true;
  button.disabled = true;
  const owner = phoneVerificationOwner();
  try {
    const currentUser = await client.getAuthUser?.();
    if (!phoneVerificationRequestCurrent(owner, phone, surface)
      || (owner.authId && currentUser?.id && currentUser.id !== owner.authId)) return false;
    if (verifiedPhoneFromAuthUser(currentUser || {}, surface === "profile") === phone) {
      markIdentityPhoneVerified(phone, "provider", surface);
      return true;
    }
    const capabilities = await refreshAuthProviderCapabilities({ force: true });
    if (!phoneVerificationRequestCurrent(owner, phone, surface)) return false;
    if (capabilities.providers.phone === false || capabilities.status === "unavailable") {
      setIdentityPhoneStatus(phoneAuthUnavailableMessage(), "error", surface);
      return false;
    }
    if (capabilities.status !== "ready") {
      setIdentityPhoneStatus("문자 인증 설정을 확인하지 못했습니다. 입력은 유지되며 다시 시도할 수 있습니다.", "error", surface);
      return false;
    }
    setIdentityPhoneStatus("인증번호를 보내고 있습니다.", "", surface);
    await client.requestPhoneChangeVerification(e164Phone);
    if (!phoneVerificationRequestCurrent(owner, phone, surface)) return false;
    const verification = { phone, status: "pending", source: "sms", owner };
    if (surface === "profile") profilePhoneVerification = verification;
    else identityPhoneVerification = verification;
    if (controls.code) controls.code.value = "";
    if (controls.row) controls.row.hidden = false;
    setIdentityPhoneStatus("문자로 받은 인증번호 6자리를 입력해 주세요.", "", surface);
    window.setTimeout(() => { if (phoneVerificationRequestCurrent(owner, phone, surface)) controls.code?.focus(); }, 40);
    return true;
  } catch (error) {
    if (phoneVerificationRequestCurrent(owner, phone, surface)) {
      resetIdentityPhoneVerification(identityErrorMessage(error), surface);
      setIdentityPhoneStatus(identityErrorMessage(error), "error", surface);
    }
    return false;
  } finally {
    identityPhoneRequestInFlight = false;
    syncIdentityPhoneCapabilityControl();
  }
}

async function requestNaverPhoneConsent() {
  if (!signupSmsEnabled) return false;
  const button = $("#identityNaverPhoneButton");
