      birthYear: profile?.birth_year || "",
      neighborhood: profile?.neighborhood || "",
      gender: profile?.gender || "",
      coachApproved: coachRole?.status === "approved",
    };
    state.coachModeAllowed = state.member.coachApproved;
    rememberRecentLoginProvider(state.member.provider);
    if (shouldOpenCoachModeByDefault()) {
      memberCurriculumUI.clear();
      openCoachMode();
      return true;
    }
    await memberCurriculumUI.bindVerifiedProfile(current, session);
    if (curriculumAttempt !== curriculumSessionAttempt) return false;
    state.profile.name = profile?.name || "가입 확인 중";
    state.profile.nickname = profile?.nickname || "";
    state.profile.phone = profile?.phone || "";
    state.profile.birthYear = profile?.birth_year || "";
    state.profile.neighborhood = profile?.neighborhood || "";
    state.profile.gender = profile?.gender || "";
    state.profile.profileCompletedAt = profile?.profile_completed_at || "";
    state.profile.termsConsentVersion = "";
    state.profile.termsConsentedAt = "";
    state.profile.privacyConsentVersion = profile?.privacy_consent_version || "";
    state.profile.privacyConsentedAt = profile?.privacy_consented_at || "";
    state.profile.marketingPushConsent = false;
    state.profile.marketingSmsConsent = false;
    state.profile.marketingEmailConsent = false;
    state.profile.suggestedNickname = suggestedNicknameFromUser(user);
    if (profile?.profile_photo_url) state.profile.photoDataUrl = profile.profile_photo_url;
    state.profile.serverRevision = profile?.updated_at || "";
    if (profile?.dominant_hand) state.profile.hand = profile.dominant_hand;
    if (profile?.backhand_style) state.profile.backhand = profile.backhand_style;
    if (profile?.tennis_started_on) state.profile.startedAt = profile.tennis_started_on;
    if (profile?.self_ntrp) state.profile.selfNtrp = String(profile.self_ntrp);
    if (profile?.coach_ntrp) state.profile.coachNtrp = String(profile.coach_ntrp);
    if (profile?.tennis_goal) state.profile.goal = profile.tennis_goal;
    if (profile?.play_style_memo) state.profile.styleMemo = profile.play_style_memo;
    if (profile?.ntrp_survey && typeof profile.ntrp_survey === "object") state.profile.ntrpSurvey = profile.ntrp_survey;
    state.profile.ntrpCheckRequested = Boolean(profile?.ntrp_requested_at && !profile?.coach_ntrp);
    openAppFromSession(false);
    renderAll();
    try {
      await loadIdentityConsentPreferences();
    } catch (consentError) {
      console.warn("[TennisNote] consent preferences could not be loaded", consentError?.message || consentError);
    }
    syncIdentitySetupModal(user);
    saveSnapshot();
    setMemberSessionRestoring(false);

    memberPurchaseDataLoaded = false;
    const initialReadback = await Promise.allSettled([
      syncMemberTicketsFromServer(profile),
      syncMemberRefundRequests(),
      syncMemberPendingPurchaseSchedulesFromServer(),
      syncMemberPendingPaymentsFromServer(),
      syncMemberLessonsFromServer(profile),
      syncMemberAccountDeletionRequestFromServer(profile),
    ]);
    if (options.requireSignupReadback && [0, 4].some(index =>
      initialReadback[index].status !== "fulfilled" || initialReadback[index].value !== true
    )) throw new Error("signup_link_readback_unconfirmed");
    await syncLiveSchedulePolicy(currentLiveTicket()?.branchId || "");
    renderAll();
    saveSnapshot();
    await applyPendingOnboardingIntent();
    void Promise.allSettled([
      syncMemberChangeRequestsFromServer(profile),
      syncMemberJournalEntriesFromServer(profile),
      syncMemberGroupAccountFromServer(profile),
      syncMemberNotificationsFromServer(profile),
      syncNativePushRegistration(profile, false),
    ]).then(() => {
      renderAll();
      if (showNotice && !isApprovalPending()) showNoticeAfterLiveSync();
      scheduleNativePushPrimer();
      saveSnapshot();
    });
    return true;
  } catch (error) {
    const status = $("#memberEmailLoginStatus");
    memberCurriculumUI.clear();
    const code = error?.payload?.code || error?.message || "";
    if (status && code === "verified_phone_member_ambiguous") {
      status.textContent = "같은 휴대전화 정보의 회원 DB가 여러 개입니다. 관리자에게 계정 연결을 요청해 주세요.";
    } else if (status && code) {
      status.textContent = "회원정보 연결을 확인하지 못했습니다. 잠시 후 다시 시도해 주세요.";
    }
    return false;
  }
}

function beginOAuthLogin(provider) {
  if (oauthLoginInFlightProvider) return false;
  oauthLoginInFlightProvider = provider || "간편";
  $$('[data-login-provider]').forEach((button) => {
    button.dataset.oauthDisabledBefore = button.disabled ? "true" : "false";
    button.disabled = true;
    button.setAttribute("aria-busy", button.dataset.loginProvider === provider ? "true" : "false");
  });
  return true;
}

function finishOAuthLogin() {
  oauthLoginInFlightProvider = "";
  $$('[data-login-provider]').forEach((button) => {
    const disabledBefore = button.dataset.oauthDisabledBefore;
    if (disabledBefore) button.disabled = disabledBefore === "true";
    delete button.dataset.oauthDisabledBefore;
    button.removeAttribute("aria-busy");
  });
  syncAuthProviderCapabilityControls();
}

function oauthLoginErrorMessage(error, provider = "간편") {
  const code = String(error?.code || error?.message || "").toLowerCase();
  if (code.includes("flow_state_already_used")) {
    return `${provider} 로그인 요청이 겹쳤습니다. 버튼을 한 번만 눌러 다시 진행해 주세요.`;
  }
  if (code.includes("server_error") || code.includes("unexpected_failure") || code.includes("request_timeout")) {
    return `${provider} 로그인 서버 응답이 늦어졌습니다. 잠시 후 다시 시도해 주세요.`;
  }
  if (code.includes("native_oauth_browser_load_incomplete")) {
    return `${provider} 인증 화면을 불러오지 못했습니다. 네트워크를 확인한 뒤 한 번만 다시 시도해 주세요.`;
  }
  return `${provider} 로그인을 완료하지 못했습니다. 다시 시도해 주세요.`;
}

async function login(provider) {
  const client = window.TennisNoteDataClient;
  if (!beginOAuthLogin(provider)) {
    setEmailAuthStatus(`${oauthLoginInFlightProvider} 로그인을 진행하고 있습니다.`);
    return;
  }
  if (client?.readiness?.().ready) {
    try {
      setEmailAuthStatus(`${provider} 로그인 화면을 여는 중입니다.`);
      await client.signInWithOAuth(provider);
      return;
    } catch (error) {
      finishOAuthLogin();
      setEmailAuthStatus(oauthLoginErrorMessage(error, provider), "alert");
      return;
    }
  }
  finishOAuthLogin();
  setEmailAuthStatus("실사용 로그인 연결 설정을 확인해 주세요.", "alert");
}

async function syncAppleLoginAvailability() {
  await refreshAuthProviderCapabilities();
}

async function handleOAuthResult(event) {
  const provider = event?.detail?.provider || "간편";
  finishOAuthLogin();
  if (event?.detail?.ok) {
    event.preventDefault();
    if (event?.detail?.callbackType === "recovery") {
      if (!emailPasswordAuthUiEnabled()) {
        emailPasswordRecoveryPending = false;
        await window.TennisNoteDataClient?.signOut?.().catch(() => {});
        $("#appScreen").hidden = true;
        $("#loginScreen").hidden = false;
        setMemberSessionRestoring(false);
        setEmailAuthStatus(emailAuthUiUnavailableMessage, "alert");
        return;
      }
      emailPasswordRecoveryPending = true;
      $("#appScreen").hidden = true;
      $("#loginScreen").hidden = false;
      setMemberSessionRestoring(false);
      setEmailAuthMode("recovery", {
        message: "이메일 인증이 완료됐습니다. 새 비밀번호를 입력해주세요.",
        tone: "done",
      });
      return;
    }
    setEmailAuthStatus(`${provider} 로그인 정보를 확인하고 있습니다.`);
    setMemberSessionRestoring(true);
    try {
      const opened = await applySupabaseMemberSession(true);
      if (!opened) throw new Error("oauth_profile_bootstrap_failed");
      setEmailAuthStatus();
    } catch (error) {
      setEmailAuthStatus(`${provider} 로그인 후 회원정보를 열지 못했습니다. 다시 시도해주세요.`, "alert");
    } finally {
      setMemberSessionRestoring(false);
    }
    return;
  }
  setEmailAuthStatus(event?.detail?.cancelled
    ? `${provider} 로그인이 취소되었습니다.`
    : oauthLoginErrorMessage({ code: event?.detail?.errorCode }, provider), "alert");
}

function emailLoginErrorMessage(error) {
  const code = `${error?.code || error?.message || ""}`.toLowerCase();
  if (code.includes("invalid_credentials") || code.includes("invalid login")) return "이메일 또는 비밀번호를 확인해주세요.";
  if (code.includes("email_not_confirmed")) return "이메일 인증을 먼저 완료해주세요.";
  if (code.includes("credentials_required")) return "이메일과 비밀번호를 입력해주세요.";
  return "로그인을 완료하지 못했습니다. 고객지원으로 문의해주세요.";
}

function setEmailAuthStatus(message = "", tone = "") {
  const status = $("#memberEmailLoginStatus");
  if (!status) return;
  status.textContent = message;
  if (tone) status.dataset.tone = tone;
  else delete status.dataset.tone;
}

function setEmailAuthMode(mode = "login", options = {}) {
  if (!emailPasswordSignInUiEnabled()) {
    const panel = $("#memberEmailAuthPanel");
    if (panel) {
      panel.hidden = true;
      panel.inert = true;
      panel.setAttribute("aria-hidden", "true");
    }
    setEmailAuthStatus(emailAuthUiUnavailableMessage, "alert");
    return false;
  }
  if (mode !== "login") {
    setEmailAuthStatus("개발 검증에서는 기존 계정 로그인만 제공합니다. 가입·비밀번호 변경은 사용할 수 없습니다.", "alert");
    return false;
  }
  const nextMode = "login";
  emailAuthMode = nextMode;
  const panel = $("#memberEmailAuthPanel");
  const tabs = $("#memberEmailAuthTabs");
  const summary = $("#memberEmailAuthSummary");
  const forms = {
    login: $("#memberEmailLoginForm"),
    signup: $("#memberEmailSignupForm"),
    recovery: $("#memberPasswordRecoveryForm"),
  };
  if (panel) { panel.hidden = false; panel.inert = false; panel.setAttribute("aria-hidden", "false"); }
  if (tabs) { tabs.hidden = true; tabs.inert = true; }
  const reset = $("#memberPasswordResetButton");
  if (reset) { reset.hidden = true; reset.disabled = true; }
  if (summary) summary.textContent = "개발 검증용 기존 계정 로그인";
  Object.entries(forms).forEach(([key, form]) => {
    if (form) {
      form.hidden = key !== nextMode;
      form.inert = key !== nextMode;
      form.querySelectorAll("input,button").forEach((control) => { control.disabled = key !== nextMode || control.id === "memberPasswordResetButton"; });
    }
  });
  $$('[data-email-auth-mode]').forEach((button) => {
    const selected = button.dataset.emailAuthMode === nextMode;
    button.classList.toggle("is-active", selected);
    button.setAttribute("aria-selected", selected ? "true" : "false");
  });
  if (Object.prototype.hasOwnProperty.call(options, "message")) {
    setEmailAuthStatus(options.message, options.tone || "");
  } else if (options.clearStatus !== false) {
    setEmailAuthStatus();
  }
  if (options.focus === false) return;
  const focusTarget = forms[nextMode]?.querySelector("input:not([type=checkbox])");
  window.requestAnimationFrame(() => focusTarget?.focus());
}

function emailSignupErrorMessage(error) {
  const code = `${error?.code || error?.message || ""}`.toLowerCase();
  if (code.includes("already") || code.includes("registered") || code.includes("exists")) return "이미 가입된 이메일입니다. 로그인하거나 비밀번호 찾기를 이용해주세요.";
  if (code.includes("weak_password") || code.includes("at least") || code.includes("too short")) return "비밀번호는 8자 이상 입력해주세요.";
  if (code.includes("invalid") && code.includes("email")) return "사용할 수 있는 이메일 주소를 입력해주세요.";
  if (code.includes("rate") || code.includes("too many")) return "요청이 많습니다. 잠시 후 다시 시도해주세요.";
  if (code.includes("signup_disabled")) return "현재 이메일 회원가입을 준비 중입니다. 고객지원으로 문의해주세요.";
  return "회원가입을 완료하지 못했습니다. 잠시 후 다시 시도해주세요.";
}

function emailSignupResponseKind(result) {
  if (result?.access_token) return "authenticated";
  const identities = result?.user?.identities;
  if (Array.isArray(identities) && identities.length > 0) return "confirmation_sent";
  return "indeterminate";
}

function passwordUpdateErrorMessage(error) {
  const code = `${error?.code || error?.message || ""}`.toLowerCase();
  if (code.includes("same_password")) return "기존 비밀번호와 다른 비밀번호를 입력해주세요.";
  if (code.includes("session") || code.includes("token") || code.includes("jwt")) return "인증 링크가 만료됐습니다. 비밀번호 찾기를 다시 진행해주세요.";
  if (code.includes("weak_password") || code.includes("at least") || code.includes("too short")) return "비밀번호는 8자 이상 입력해주세요.";
  return "비밀번호를 변경하지 못했습니다. 비밀번호 찾기를 다시 진행해주세요.";
}

