function minutesFromTime(time) {
  const [hour, minute] = time.split(":").map(Number);
  return hour * 60 + minute;
}

function lessonDuration(lesson) {
  if (Number(lesson?.durationMinutes) > 0) return Number(lesson.durationMinutes);
  const text = `${lesson.type || ""} ${lesson.ticket || ""}`;
  const matched = text.match(/(\d+)\s*분/);
  return matched ? Number(matched[1]) : 20;
}

function todayLessonPriority(lesson = {}, now = new Date()) {
  const start = minutesFromTime(String(lesson.time || ""));
  const current = now.getHours() * 60 + now.getMinutes();
  if (!Number.isFinite(start)) return { group: 3, distance: Number.MAX_SAFE_INTEGER, start: Number.MAX_SAFE_INTEGER };
  const end = start + Math.max(1, Number(lesson.durationMinutes) || lessonDuration(lesson));
  if (start <= current && current < end) return { group: 0, distance: 0, start };
  if (start > current) return { group: 1, distance: start - current, start };
  return { group: 2, distance: current - end, start: -start };
}

function compareTodayLessonsByNearest(left, right, now = new Date()) {
  const leftPriority = todayLessonPriority(left, now);
  const rightPriority = todayLessonPriority(right, now);
  return leftPriority.group - rightPriority.group
    || leftPriority.distance - rightPriority.distance
    || leftPriority.start - rightPriority.start;
}

function lessonCreditUnits(lesson = {}) {
  const duration = Math.max(1, Number(lesson.durationMinutes) || lessonDuration(lesson));
  const ticketUnit = Math.max(1, Number(lesson.ticketLessonMinutes) || duration);
  return Math.max(1, Math.ceil(duration / ticketUnit));
}

function lessonDurationUsageLabel(lesson = {}) {
  const duration = Math.max(1, Number(lesson.durationMinutes) || lessonDuration(lesson));
  const units = lessonCreditUnits(lesson);
  return `${duration}분${units > 1 ? ` · ${units}회 사용` : ""}`;
}

function coachFutureRoundLabel(lesson = {}) {
  // 주간 일부 조회만으로 첫 회차를 만들지 않는다. 남은 전체 차감 단위가
  // exact 회원/회원권별로 맞는 경우에만 미래 순서를 표시한다.
  if (!state.liveLessonsLoaded || lesson.serverStatus !== "scheduled" || lesson.lessonSource !== "regular") return "";
  const identity = (row) => String(row.serverLessonId || "");
  const records = (row) => Array.isArray(row.v2Participants) ? row.v2Participants : [];
  const pending = (record) => !record.recordStatus || record.recordStatus === "draft";
  const validCounts = (record) => [record.totalSessions, record.usedSessions, record.remainingSessions]
    .every((value) => Number.isSafeInteger(value) && value >= 0)
    && record.totalSessions > 0 && record.remainingSessions > 0
    && record.totalSessions === record.usedSessions + record.remainingSessions;
  const sameCounts = (left, right) => ["totalSessions", "usedSessions", "remainingSessions"]
    .every((key) => left[key] === right[key]);
  const targetRecords = records(lesson);
  if (!identity(lesson) || !targetRecords.length || targetRecords.some((record) => (
    !record.userId || !record.ticketId || !pending(record) || !validCounts(record)
  )) || new Set(targetRecords.map((record) => record.userId)).size !== targetRecords.length) return "";
  const workspace = scheduleV2CoachWorkspace();
  const labels = [];
  for (const participant of targetRecords) {
    const matching = (row) => records(row).filter((record) => record.userId === participant.userId && record.ticketId === participant.ticketId);
    const rows = (state.liveLessons || []).filter((row) => row.serverStatus === "scheduled" && matching(row).length);
    if (!rows.length || rows.some((row) => matching(row).length !== 1
      || !pending(matching(row)[0]) || !sameCounts(matching(row)[0], participant)
      || row.lessonSource !== "regular" || !identity(row))) return "";
    const tickets = (workspace?.tickets || []).filter((ticket) => ticket.id === participant.ticketId);
    if (tickets.length > 1 || (tickets.length === 1 && !sameCounts(tickets[0], participant))) return "";
    // 타 회원권의 분 단위를 첫 참가자 회원권에서 빌려오지 않는다.
    const unit = tickets.length === 1 ? tickets[0].lessonMinutes
      : lesson.ticketId === participant.ticketId ? lesson.ticketLessonMinutes : 0;
    if (!Number.isSafeInteger(unit) || unit <= 0) return "";
    const occurrences = coachDisplayLessons(rows);
    const ids = new Set();
    const entries = [];
    for (const row of occurrences) {
      const id = identity(row);
      const duration = Number(row.durationMinutes);
      const time = String(row.time || "");
      const date = String(row.lessonDate || "");
      if (ids.has(id) || !/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^([01]\d|2[0-3]):[0-5]\d$/.test(time)
        || !Number.isSafeInteger(duration) || duration <= 0 || !row.coachRoleId
        || (row.ticketId === participant.ticketId && row.ticketLessonMinutes !== unit)) return "";
      ids.add(id);
      const start = Number(time.slice(0, 2)) * 60 + Number(time.slice(3));
      entries.push({ id, date, start, end: start + duration, units: Math.ceil(duration / unit), row });
    }
    entries.sort((left, right) => left.date.localeCompare(right.date) || left.start - right.start || left.id.localeCompare(right.id));
    if (entries.some((entry, index) => entry.end > 1440 || (index > 0
      && entries[index - 1].date === entry.date && entries[index - 1].end > entry.start))) return "";
    if (entries.reduce((sum, entry) => sum + entry.units, 0) !== participant.remainingSessions) return "";
    const index = entries.findIndex((entry) => entry.id === identity(lesson));
    if (index < 0) return "";
    const current = entries[index];
    const sourceSegments = current.row.displaySegments || [current.row];
    if (!sourceSegments.some((row) => row.id === lesson.id && row.lessonDate === lesson.lessonDate
      && row.time === lesson.time && row.serverRevision === lesson.serverRevision
      && row.coachRoleId === lesson.coachRoleId)) return "";
    const first = participant.usedSessions + entries.slice(0, index).reduce((sum, entry) => sum + entry.units, 0) + 1;
    const last = first + current.units - 1;
    labels.push(`${first === last ? first : `${first}~${last}`}/${participant.totalSessions}회차`);
  }
  const uniqueLabels = [...new Set(labels)];
  return uniqueLabels.length === 1 ? uniqueLabels[0] : `회원별 ${uniqueLabels.join(" · ")}`;
}

function coachScheduleRoundLabel(lesson = {}) {
  const finalRecords = (Array.isArray(lesson.v2Participants) ? lesson.v2Participants : [])
    .filter((record) => String(record.recordStatus || record.record_status || "").toLowerCase() === "final");
  const sessionStates = finalRecords.map(coachTicketSessionSnapshot).filter((state) => state.confirmed);
  if (sessionStates.length) {
    const labels = [...new Set(sessionStates.map((state) => {
      const snapshot = state.snapshot;
      const round = snapshot.ticketDeductedSessions > 1
        ? `${snapshot.usedBefore + 1}~${snapshot.usedAfter}`
        : `${snapshot.usedAfter}`;
      return `${round}/${snapshot.totalSessions}회차`;
    }))];
    return labels.length === 1 ? `이번 수업 ${labels[0]}` : `회원별 ${labels.join(" · ")}`;
  }
  const finalized = finalRecords.length > 0
    || ["completed", "no_show", "absence", "absent", "cancelled", "holiday"]
      .includes(String(lesson.serverStatus || "").toLowerCase());
  if (finalized) return coachTicketSessionSnapshot(lesson).label;
  return coachFutureRoundLabel(lesson);
}

function coachScheduleExceptionLabel(lesson = {}) {
  if (lesson.releasedOriginLabel) return lesson.releasedOriginLabel;
  const context = `${lesson.lessonSource || ""} ${lesson.type || ""} ${lesson.changeNote || ""} ${lesson.task || ""}`;
  let detail = "";
  if ((lesson.originalCoachRoleId && lesson.coachRoleId && lesson.originalCoachRoleId !== lesson.coachRoleId) || /대타/.test(context)) detail = "대타";
  else if (/코치\s*변경/.test(context)) detail = "코치 변경";
  else if (/시간\s*변경|변경\s*완료/.test(context)) detail = "시간 변경";
  const cardState = coachLessonCardState(lesson);
  const stateLabel = cardState.id === "scheduled" ? "" : cardState.label;
  return stateLabel ? `${stateLabel}${detail ? ` · ${detail}` : ""}` : detail;
}

function coachLessonCardState(lesson = {}, now = new Date()) {
  const participants = Array.isArray(lesson.v2Participants) ? lesson.v2Participants : [];
  const sameDayAbsences = Array.isArray(lesson.memberSameDayAbsences) ? lesson.memberSameDayAbsences : [];
  const pendingAbsences = sameDayAbsences.filter((request) => request.status === "pending_approval");
  const announcedAbsences = sameDayAbsences.filter((request) => request.status === "announced");
  if (pendingAbsences.length) {
    return {
      id: "same_day_absence_pending",
      label: `${pendingAbsences.length}명 불참 승인 대기`,
      actionLabel: "승인 확인",
      needsFeedback: false,
      resolved: false,
      className: "record-approval outcome-absence",
    };
  }
  const processing = coachLessonProcessingState(lesson, now);
  const deducted = Number(lesson.deductedSessions) > 0
    || participants.some((participant) => Number(participant.deductedSessions) > 0);
  const className = {
    released: "record-neutral",
    approval: "record-approval",
    processing_required: "record-problem",
    confirmation_needed: "record-problem",
    completed: "record-complete",
    no_show: "record-problem outcome-no-show",
    absence: "record-neutral outcome-absence",
    cancelled: "record-neutral",
    holiday: "record-neutral",
  }[processing.id] || "record-planned";
  const label = processing.id === "released"
    ? "차감 없음 · 예약 가능"
    : processing.id === "no_show"
      ? `노쇼 · ${deducted ? "1회 차감" : "차감 없음"}`
      : processing.id === "absence"
        ? `불참 · ${deducted ? "1회 차감" : "차감 없음"}`
        : processing.contextLabel
          ? `${processing.contextLabel} · ${processing.label}`
          : processing.label;
  return {
    ...processing,
    label: announcedAbsences.length
      ? `${announcedAbsences.length}명 불참 예정${processing.id === "completed" || processing.id === "absence" ? "" : ` · ${label}`}`
      : label,
    className: announcedAbsences.length && processing.id === "absence" ? "record-neutral outcome-absence" : className,
  };
}

async function reviewMemberSameDayAbsence(requestId, approve, button, operationKind = "same_day") {
  if (!requestId || !window.TennisNoteDataClient?.rpc || button?.disabled) return;
  const originalLabel = button?.textContent || "처리";
  if (button) {
    button.disabled = true;
    button.textContent = "처리 중";
  }
  try {
    await window.TennisNoteDataClient.rpc(operationKind === "future_group"
      ? "tn_review_member_future_group_absence"
      : "tn_review_member_same_day_absence", {
      target_request_id: requestId,
      target_approve: approve === true,
      target_note: "",
      target_operation_key: `coach_absence_review:${operationKind}:${requestId}:${approve ? "approve" : "reject"}`,
    });
    coachScheduleV2WorkspaceCache = null;
    await syncCoachLessonsFromServer();
    renderAll();
    saveSnapshot();
    showToast(approve ? "회원 불참 신청을 승인했습니다." : "회원 불참 신청을 거절했습니다.");
  } catch (error) {
    const code = String(error?.payload?.message || error?.payload?.code || error?.message || "");
    const messages = {
      same_day_absence_review_forbidden: "이 수업의 담당 코치 또는 관리자만 처리할 수 있습니다.",
      same_day_absence_request_not_actionable: "이미 다른 기기에서 처리된 요청입니다. 최신 상태를 다시 확인해 주세요.",
      same_day_absence_lesson_started: "이미 시작한 수업은 불참 승인으로 처리할 수 없습니다.",
      same_day_absence_ticket_units_unavailable: "회원권 잔여 횟수가 부족합니다. 관리자에게 확인해 주세요.",
    };
    showToast(messages[code] || "불참 요청을 처리하지 못했습니다. 최신 상태를 다시 확인해 주세요.");
  } finally {
    if (button?.isConnected) {
      button.disabled = false;
      button.textContent = originalLabel;
    }
  }
}

function coachLessonStateClass(lesson = {}) {
  return coachLessonCardState(lesson).className;
}

function coachLessonVisualKind(lesson = {}) {
  const source = String(lesson.lessonSource || lesson.lesson_source || "").toLowerCase();
  if (lesson.releasedMakeupSlot || lesson.status === "available") return "released";
  if (["no_show", "cancelled_late"].includes(String(lesson.serverStatus || lesson.status || "").toLowerCase())) return "noShow";
  if (source === "makeup" || String(lesson.type || "").includes("보강")) return "makeup";
  if (source === "one_day") return "coupon";
  if (source === "coupon" || String(lesson.type || "").includes("쿠폰")) return "coupon";
  if (lessonDuration(lesson) === 30) return "regular30";
  return "regular";
}

function coachScheduleLessonActionAttrs(lesson = {}) {
  const segmentAttrs = coachDisplaySegmentAttrs(lesson);
  if (lesson.oneDayBooking) {
    return `disabled aria-label="${lesson.member || "원데이"} 원데이 예약"`;
  }
  if (!canProcessLesson(lesson) && !canRescheduleLesson(lesson)) {
    return `disabled aria-label="${lesson.member || "회원"} 다른 코치 수업 읽기 전용"`;
  }
  if (lesson.releasedMakeupSlot) {
    if (lesson.historicalReleasedSlot) {
      return `disabled aria-label="${lesson.member || "회원"} 과거 정규 불참 기록"`;
    }
    return `data-restore-absence-id="${lesson.entitlementId || ""}" aria-label="${lesson.member || "회원"} 정규수업 복원"`;
  }
  return `data-edit-lesson-id="${lesson.id}"${segmentAttrs}`;
}

function coachLessonColorStyle(lesson, policy) {
  const kind = coachLessonVisualKind(lesson);
  if (kind === "released") return "--lesson-color:#111827";
  const changed = ["makeup", "coupon"].includes(kind);
  const fallback = { regular: "#2f6fc4", regular30: "#2f6fc4", makeup: "#7357ad", coupon: "#7357ad", noShow: "#7357ad" };
  const custom = (policy?.lessonColorRules || []).find((rule) => rule.match && `${lesson.type || ""} ${lesson.lessonSource || ""}`.includes(rule.match));
  const saved = changed
    ? policy?.lessonColors?.changed || ""
    : custom?.color || policy?.lessonColors?.[kind] || "";
  const color = /^#[0-9a-f]{6}$/i.test(saved) ? saved : fallback[kind];
  return `--lesson-color:${color}`;
}

function currentCoachProfile() {
  ensureMemberLists();
  const name = currentCoachName();
  return state.coachProfiles[name] || state.coachProfiles["노 코치"] || {};
}

// Session-only choice: never restored from a persisted coach snapshot.
let coachSettlementSelection = null;

function coachSettlementCurrentMonth(now = new Date()) {
  const parts = new Intl.DateTimeFormat("en", { timeZone: "Asia/Seoul", year: "numeric", month: "2-digit" }).formatToParts(now);
  return `${parts.find((part) => part.type === "year").value}-${parts.find((part) => part.type === "month").value}`;
}

function selectCoachSettlementMonth(value) {
  const currentMonth = coachSettlementCurrentMonth();
  coachSettlementSelection = /^\d{4}-(0[1-9]|1[0-2])$/.test(String(value || ""))
    ? { month: value, currentMonth, coachRoleId: state.coach?.coachRoleId || "" }
    : null;
  return coachSettlementMonth();
}

function coachSettlementMonth() {
  const currentMonth = coachSettlementCurrentMonth();
  const choice = coachSettlementSelection;
  if (choice && (choice.currentMonth !== currentMonth || choice.coachRoleId !== (state.coach?.coachRoleId || ""))) coachSettlementSelection = null;
  state.settlementMonth = coachSettlementSelection?.month || currentMonth;
  return state.settlementMonth;
}

function formatCoachWon(value) {
  return `${new Intl.NumberFormat("ko-KR").format(Math.max(0, Math.round(Number(value) || 0)))}원`;
}

function coachSettlementRuleLabel(settlement = {}) {
  if (settlement.ruleType === "effective_periods") return "수업·결제 기준일별 조건 · 월 합계에서 원 단위 반올림" + (settlement.confirmationReady ? "" : " · 새 계산은 미리보기이며 기존 확정 내역은 유지됩니다");
  if (settlement.ruleType === "hourly") return `시급 ${formatCoachWon(settlement.hourlyRate)}`;
  const rate = Math.round((Number(settlement.ruleRate) || 0) * 100);
  const basis = settlement.settlementBasis === "actual_paid_inc_vat" ? "실결제" : "정산 기준가";
  const calculation = settlement.calculationMode === "monthly_payment" ? "월 결제액" : "진행 횟수";
  return `${calculation} · ${basis}의 ${rate}%`;
}

function normalizedCoachSettlementMemberName(value = "") {
  return String(value || "").replace(/\s+/g, " ").trim().toLowerCase();
}

function coachSettlementRowsForMember(member = {}) {
  const settlementRows = Array.isArray(state.coachSettlement?.rows) ? state.coachSettlement.rows : [];
  if (state.coachSettlement?.calculationVersion === "r3_effective_settlement_v2") {
    const exactUserId = String(member.serverUserId || member.userId || "");
    return exactUserId ? settlementRows.filter((row) => row.userId === exactUserId) : [];
  }
  const memberNames = member.isGroupDisplay
    ? [member.groupMemberName, member.displayName]
    : [member.displayName, member.name];
  const normalizedNames = new Set(memberNames.map(normalizedCoachSettlementMemberName).filter(Boolean));
  if (!normalizedNames.size) return [];
  return settlementRows.filter((row) => normalizedNames.has(normalizedCoachSettlementMemberName(row.memberName)));
}

function coachMemberSettlementSummary(member = {}) {
  const rows = coachSettlementRowsForMember(member);
  if (!rows.length) {
    return {
      linked: false,
      sessions: 0,
      amount: 0,
      label: state.coachSettlementLoading ? "정산 확인 중" : "정산 연결 확인 필요",
    };
  }
  const sessions = rows.reduce((sum, row) => sum + (Number(row.settledSessions) || 0), 0);
  const amount = rows.reduce((sum, row) => sum + (Number(row.estimatedSettlement) || 0), 0);
  return {
    linked: true,
    sessions,
    amount,
    label: `${sessions}회 · ${formatCoachWon(amount)}`,
  };
}

function renderVisibleMemberSettlement() {
  const target = $("#memberDetailSettlementValue");
  if (!target || !state.viewingMemberDetailId) return;
  const member = findMemberDetail(state.viewingMemberDetailId, state.viewingMemberGroupName);
  if (!member) return;
  const summary = coachMemberSettlementSummary(member);
  target.textContent = summary.label;
  target.dataset.linked = String(summary.linked);
}

function coachSettlementReconciliationScope() {
  return {
    branchId: String(state.coach?.branchId || "").trim(),
    coachRoleId: String(state.coach?.coachRoleId || "").trim(),
    settlementMonth: `${coachSettlementMonth()}-01`,
  };
}

function coachSettlementReconciliationScopeSignature(scope = coachSettlementReconciliationScope()) {
  return [scope.branchId, scope.coachRoleId, scope.settlementMonth].join(":");
}

// In-memory continuation fence only; never persist session or identity evidence.
function coachSettlementReconciliationContinuation(scope = coachSettlementReconciliationScope()) {
  const client = window.TennisNoteDataClient;
  const token = client?.getSession?.()?.access_token || "";
  const profileId = String(state.liveProfileId || "");
  const authUserId = String(state.coach?.authUserId || "");
  const signature = coachSettlementReconciliationScopeSignature(scope);
  if (!client?.rpc || !token || !profileId || !authUserId || state.dataMode !== "live"
    || state.coach?.role !== "coach" || !scope.branchId || !scope.coachRoleId) return null;
  return () => window.TennisNoteDataClient === client
    && token === (client.getSession?.()?.access_token || "")
    && profileId === String(state.liveProfileId || "")
    && authUserId === String(state.coach?.authUserId || "")
    && state.dataMode === "live" && state.coach?.role === "coach"
    && signature === coachSettlementReconciliationScopeSignature();
}

function coachSettlementReconciliationScopeMatches(value, scope = coachSettlementReconciliationScope()) {
  const received = value?.scope || {};
  return String(received.branchId || "") === scope.branchId
    && String(received.coachRoleId || "") === scope.coachRoleId
    && String(received.settlementMonth || "").slice(0, 10) === scope.settlementMonth;
}

function normalizeCoachSettlementReconciliationReason(value = "") {
  return String(value || "")
    .normalize("NFKC")
    .replace(/[\u200B-\u200F\u202A-\u202E\u2060\u2066-\u2069\uFEFF]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function coachSettlementReconciliationReasonError(value = "") {
  const reason = normalizeCoachSettlementReconciliationReason(value);
  const length = Array.from(reason).length;
  if (length < 2 || length > 240) return "이의 사유를 2~240자로 입력해 주세요.";
  if (
    /[<>\u0000-\u001F\u007F]/.test(reason)
    || reason.includes("@")
    || /(?:https?:\/\/|www\.|javascript:|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i.test(reason)
    || /\d(?:[\s().+\-]*\d){6,}/.test(reason)
  ) return "개인정보나 연락처·링크를 제외하고 확인할 항목만 적어 주세요.";
  return "";
}

function coachSettlementReconciliationPayloadIsExact(value, scope = coachSettlementReconciliationScope()) {
  if (!value || typeof value !== "object" || Array.isArray(value) || !coachSettlementReconciliationScopeMatches(value, scope)) return false;
  const remoteState = String(value.state || "").toUpperCase();
  if (remoteState === "EMPTY") {
    return value.snapshot == null && value.confirmation == null && value.reconciliation == null;
  }
  if (!["PENDING", "ACKNOWLEDGED", "DISPUTED"].includes(remoteState)) return false;
  const snapshot = value.snapshot || {};
  const confirmation = value.confirmation || {};
  const reconciliation = value.reconciliation;
  const totals = snapshot.totals || {};
  const displayedTotalsAreExact = [
    totals.settledSessions,
    totals.settledMinutes,
    totals.totalSettlementAmount,
  ].every((item) => typeof item === "number" && Number.isFinite(item) && item >= 0);
  const exactSnapshot = Boolean(
    snapshot.snapshotId
    && Number.isInteger(snapshot.revision)
    && snapshot.revision > 0
    && String(snapshot.status || "").toLowerCase() === "calculated"
    && ["r3_monthly_settlement_v1", "r3_effective_settlement_v2"].includes(String(snapshot.calculationVersion || ""))
    && /^[0-9a-f]{64}$/i.test(String(snapshot.sourceFingerprint || ""))
    && displayedTotalsAreExact
    && confirmation.confirmationId
    && String(confirmation.status || "").toLowerCase() === "confirmed"
    && String(confirmation.confirmationVersion || "") === "r3_monthly_settlement_confirmation_v1"
    && !Number.isNaN(Date.parse(String(confirmation.confirmedAt || "")))
  );
  if (!exactSnapshot) return false;
  if (remoteState === "PENDING") return reconciliation == null;
  const responseReason = normalizeCoachSettlementReconciliationReason(reconciliation?.reason || "");
  const responseIsExact = remoteState === "ACKNOWLEDGED"
    ? !responseReason
    : !coachSettlementReconciliationReasonError(responseReason);
  return Boolean(
    reconciliation?.reconciliationId
    && String(reconciliation.status || "").toUpperCase() === remoteState
    && String(reconciliation.responseVersion || "") === "r3_monthly_settlement_coach_reconciliation_v1"
    && !Number.isNaN(Date.parse(String(reconciliation.respondedAt || "")))
    && responseIsExact
  );
}

function coachSettlementReconciliationErrorContract(error) {
  const raw = String(error?.payload?.message || error?.payload?.code || error?.message || "").toLowerCase();
  if (raw.includes("reason_length") || raw.includes("reason_sensitive") || raw.includes("acknowledgement_reason")) {
    return {
      state: "PENDING",
      message: "이의 사유를 안전한 내용으로 수정한 뒤 다시 저장해 주세요.",
      validation: raw.includes("reason_sensitive")
        ? "개인정보나 연락처·링크를 제외하고 확인할 항목만 적어 주세요."
        : "이의 사유를 2~240자로 입력해 주세요.",
    };
  }
  if (raw.includes("stale") || raw.includes("revision") || raw.includes("source_mismatch") || raw.includes("source_fingerprint")) {
    return {
      state: "STALE",
      message: "관리자 확정 계산본이 변경되었습니다. 최신 상태를 다시 확인해 주세요.",
      validation: "",
    };
  }
  if (
    raw.includes("conflict")
    || raw.includes("operation_key_reused")
    || raw.includes("scope_mismatch")
    || raw.includes("already")
  ) {
    return {
      state: "CONFLICT",
      message: "다른 화면의 응답과 상태가 겹쳤습니다. 서버 상태를 다시 확인해 주세요.",
      validation: "",
    };
  }
  if (raw.includes("approved_coach_scope_required") || raw.includes("authentication_required") || raw.includes("forbidden")) {
    return {
      state: "ERROR",
      message: "현재 담당 코치 권한과 지점을 확인할 수 없습니다. 다시 로그인한 뒤 확인해 주세요.",
      validation: "",
    };
  }
  if (raw.includes("pgrst202") || raw.includes("tn_coach_monthly_settlement_reconciliation")) {
    return {
      state: "ERROR",
      message: "코치 정산 확인 기능을 업데이트하는 중입니다. 잠시 후 다시 확인해 주세요.",
      validation: "",
    };
  }
  return {
    state: "ERROR",
    message: "확정 정산 상태를 불러오지 못했습니다. 네트워크를 확인하고 다시 시도해 주세요.",
    validation: "",
  };
}

function resetCoachSettlementReconciliation() {
  state.coachSettlementReconciliationRequestId += 1;
  state.coachSettlementReconciliation = null;
  state.coachSettlementReconciliationUiState = "EMPTY";
  state.coachSettlementReconciliationLoading = false;
  state.coachSettlementReconciliationSubmitting = false;
  state.coachSettlementReconciliationMessage = "";
  state.coachSettlementReconciliationValidation = "";
  state.coachSettlementReconciliationChoice = "";
  state.coachSettlementReconciliationReason = "";
  state.coachSettlementReconciliationOperation = null;
}

function coachSettlementReconciliationStateLabel(value = state.coachSettlementReconciliationUiState) {
  return ({
    EMPTY: "확정 대기",
    LOADING: "확인 중",
    PENDING: "응답 대기",
    ACKNOWLEDGED: "확인 완료",
    DISPUTED: "이의 접수",
    STALE: "다시 확인 필요",
    CONFLICT: "상태 확인 필요",
    ERROR: "불러오기 실패",
  })[String(value || "").toUpperCase()] || "확정 대기";
}

function coachSettlementReconciliationTimeLabel(value = "") {
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime())
    ? "시각 확인 필요"
    : new Intl.DateTimeFormat("ko-KR", {
      year: "numeric",
      month: "numeric",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    }).format(parsed);
}

function coachSettlementReconciliationDefaultMessage(uiState) {
  return ({
    EMPTY: "관리자가 이 월의 정산을 확정하면 여기에서 응답할 수 있습니다.",
    LOADING: "관리자가 확정한 월 정산을 확인하고 있습니다.",
    PENDING: "관리자 확정 계산본입니다. 월·횟수·정산액을 확인한 뒤 한 번만 응답해 주세요.",
    ACKNOWLEDGED: "관리자 확정 정산을 확인했다고 응답했습니다.",
    DISPUTED: "이의 사유를 관리자에게 전달했습니다.",
    STALE: "관리자 확정 계산본이 변경되었습니다. 최신 상태를 다시 확인해 주세요.",
    CONFLICT: "다른 화면의 응답과 상태가 겹쳤습니다. 서버 상태를 다시 확인해 주세요.",
    ERROR: "확정 정산 상태를 불러오지 못했습니다. 다시 확인해 주세요.",
  })[uiState] || "관리자 확정 정산을 확인하고 있습니다.";
}

function renderCoachSettlementReconciliation() {
  const section = $("#coachSettlementReconciliation");
  if (!section) return;
  const uiState = String(state.coachSettlementReconciliationUiState || "EMPTY").toUpperCase();
  const payload = state.coachSettlementReconciliation || {};
  const snapshot = payload.snapshot || null;
  const confirmation = payload.confirmation || null;
  const reconciliation = payload.reconciliation || null;
  const payloadIsExact = coachSettlementReconciliationPayloadIsExact(payload);
  const busy = state.coachSettlementReconciliationLoading || state.coachSettlementReconciliationSubmitting;
  const monthInput = $("#coachSettlementMonth");
  if (monthInput) monthInput.disabled = busy;
  section.dataset.state = uiState;
  section.setAttribute("aria-busy", String(busy));
  const badge = $("#coachSettlementReconciliationStateBadge");
  if (badge) badge.textContent = coachSettlementReconciliationStateLabel(uiState);
  const message = $("#coachSettlementReconciliationMessage");
  if (message) message.textContent = state.coachSettlementReconciliationMessage || coachSettlementReconciliationDefaultMessage(uiState);

  const summary = $("#coachSettlementReconciliationSummary");
  if (summary) {
    summary.innerHTML = "";
    summary.hidden = !payloadIsExact || !snapshot || !confirmation;
    if (payloadIsExact && snapshot && confirmation) {
      const appendSummary = (label, value, detail, className = "") => {
        const item = document.createElement("div");
        if (className) item.className = className;
        const labelNode = document.createElement("span");
        const valueNode = document.createElement("strong");
        const detailNode = document.createElement("small");
        labelNode.textContent = label;
        valueNode.textContent = value;
        detailNode.textContent = detail;
        item.append(labelNode, valueNode, detailNode);
        summary.appendChild(item);
      };
      const month = String(payload.scope?.settlementMonth || "").slice(0, 7);
      const [year, monthNumber] = month.split("-");
      appendSummary("확정 월", year && monthNumber ? `${Number(year)}년 ${Number(monthNumber)}월` : "월 확인 필요", `${Number(snapshot.revision) || 0}차 계산본`);
      appendSummary("정산 진행", `${Number(snapshot.totals?.settledSessions) || 0}회`, `${Number(snapshot.totals?.settledMinutes) || 0}분`);
      appendSummary("확정 정산액", formatCoachWon(snapshot.totals?.totalSettlementAmount), `관리자 확인 ${coachSettlementReconciliationTimeLabel(confirmation.confirmedAt)}`);
      if (uiState === "DISPUTED" && reconciliation?.reason) {
        appendSummary("이의 사유", String(reconciliation.reason), `응답 ${coachSettlementReconciliationTimeLabel(reconciliation.respondedAt)}`, "coach-settlement-reconciliation-summary-reason");
      } else if (uiState === "ACKNOWLEDGED") {
        appendSummary("코치 응답", "확인했습니다", coachSettlementReconciliationTimeLabel(reconciliation?.respondedAt), "coach-settlement-reconciliation-summary-response");
      }
    }
  }

  const form = $("#coachSettlementReconciliationForm");
  const canRespond = uiState === "PENDING"
    && payloadIsExact
    && !payload.reconciliation
    && Boolean(coachSettlementReconciliationContinuation());
  if (form) {
    form.hidden = !canRespond;
    form.querySelectorAll('input[name="coachSettlementReconciliationChoice"]').forEach((input) => {
      input.checked = input.value === state.coachSettlementReconciliationChoice;
      input.disabled = busy;
    });
  }
  const reasonField = $("#coachSettlementReconciliationReasonField");
  if (reasonField) reasonField.hidden = !canRespond || state.coachSettlementReconciliationChoice !== "disputed";
  const reasonInput = $("#coachSettlementReconciliationReason");
  if (reasonInput) {
    if (reasonInput.value !== state.coachSettlementReconciliationReason) reasonInput.value = state.coachSettlementReconciliationReason;
    reasonInput.disabled = busy;
  }
  const validation = $("#coachSettlementReconciliationValidation");
  if (validation) {
    validation.hidden = !state.coachSettlementReconciliationValidation;
    validation.textContent = state.coachSettlementReconciliationValidation;
  }
  const submit = $("#coachSettlementReconciliationSubmit");
  if (submit) {
    const reasonError = state.coachSettlementReconciliationChoice === "disputed"
      ? coachSettlementReconciliationReasonError(state.coachSettlementReconciliationReason)
      : "";
    submit.textContent = state.coachSettlementReconciliationSubmitting ? "응답 저장 중" : "응답 저장";
    submit.disabled = !canRespond
      || busy
      || !["acknowledged", "disputed"].includes(state.coachSettlementReconciliationChoice)
      || Boolean(reasonError);
  }
  const retry = $("#coachSettlementReconciliationRetry");
  if (retry) {
    retry.hidden = !["STALE", "CONFLICT", "ERROR"].includes(uiState);
    retry.disabled = busy;
  }
}

async function readCoachSettlementReconciliation(scope = coachSettlementReconciliationScope()) {
  return window.TennisNoteDataClient.rpc("tn_coach_monthly_settlement_reconciliation_state", {
    target_branch_id: scope.branchId,
    target_coach_role_id: scope.coachRoleId,
    target_month: scope.settlementMonth,
  });
}

async function syncCoachSettlementReconciliationFromServer() {
  const scope = coachSettlementReconciliationScope();
  if (state.coachSettlementReconciliationSubmitting) return false;
  const continuationIsCurrent = coachSettlementReconciliationContinuation(scope);
  if (!continuationIsCurrent) {
    resetCoachSettlementReconciliation();
    state.coachSettlementReconciliationUiState = "ERROR";
    state.coachSettlementReconciliationMessage = "현재 담당 코치 권한과 지점을 확인한 뒤 다시 시도해 주세요.";
    state.coachSettlementReconciliationValidation = "";
    renderCoachSettlementReconciliation();
    return false;
  }
  const requestId = ++state.coachSettlementReconciliationRequestId;
  const readIsCurrent = () => requestId === state.coachSettlementReconciliationRequestId && continuationIsCurrent();
  const previousScope = state.coachSettlementReconciliation?.scope || {};
  const previousSignature = [previousScope.branchId, previousScope.coachRoleId, String(previousScope.settlementMonth || "").slice(0, 10)].join(":");
  const nextSignature = coachSettlementReconciliationScopeSignature(scope);
  state.coachSettlementReconciliationLoading = true;
  state.coachSettlementReconciliationUiState = "LOADING";
  state.coachSettlementReconciliationMessage = "";
  state.coachSettlementReconciliationValidation = "";
  renderCoachSettlementReconciliation();
  try {
    const raw = await readCoachSettlementReconciliation(scope);
    const result = Array.isArray(raw) ? raw[0] || null : raw;
    if (!readIsCurrent()) return false;
    if (!coachSettlementReconciliationPayloadIsExact(result, scope)) throw new Error("settlement_reconciliation_scope_mismatch");
    const remoteState = String(result.state || "").toUpperCase();
    if (previousSignature && previousSignature !== nextSignature) {
      state.coachSettlementReconciliationChoice = "";
      state.coachSettlementReconciliationReason = "";
      state.coachSettlementReconciliationOperation = null;
    }
    state.coachSettlementReconciliation = result;
    state.coachSettlementReconciliationUiState = remoteState;
    state.coachSettlementReconciliationMessage = "";
    if (["ACKNOWLEDGED", "DISPUTED"].includes(remoteState)) {
      state.coachSettlementReconciliationChoice = "";
      state.coachSettlementReconciliationReason = "";
      state.coachSettlementReconciliationOperation = null;
    }
    return true;
  } catch (error) {
    if (!readIsCurrent()) return false;
    const contract = coachSettlementReconciliationErrorContract(error);
    state.coachSettlementReconciliation = null;
    state.coachSettlementReconciliationUiState = contract.state;
    state.coachSettlementReconciliationMessage = contract.message;
    state.coachSettlementReconciliationValidation = contract.validation;
    return false;
  } finally {
    if (requestId === state.coachSettlementReconciliationRequestId) {
      if (!continuationIsCurrent()) resetCoachSettlementReconciliation();
      state.coachSettlementReconciliationLoading = false;
      renderCoachSettlementReconciliation();
      saveSnapshot();
    }
  }
}

function coachSettlementReconciliationResponseMatches(value, expected, targetStatus, targetReason, scope) {
  if (!coachSettlementReconciliationPayloadIsExact(value, scope)) return false;
  const snapshot = value.snapshot || {};
  const confirmation = value.confirmation || {};
  const reconciliation = value.reconciliation || {};
  return String(value.state || "").toUpperCase() === targetStatus.toUpperCase()
    && String(snapshot.snapshotId || "") === String(expected.snapshotId || "")
    && Number(snapshot.revision || 0) === Number(expected.revision || 0)
    && String(snapshot.sourceFingerprint || "") === String(expected.sourceFingerprint || "")
    && String(confirmation.confirmationId || "") === String(expected.confirmationId || "")
    && String(reconciliation.status || "").toLowerCase() === targetStatus
    && normalizeCoachSettlementReconciliationReason(reconciliation.reason || "") === targetReason;
}

function coachSettlementReconciliationOperationKey(expected, targetStatus, targetReason) {
  const signature = [
    expected.confirmationId,
    expected.snapshotId,
    expected.revision,
    expected.sourceFingerprint,
    targetStatus,
    targetReason,
  ].join(":");
  if (state.coachSettlementReconciliationOperation?.signature !== signature) {
    const random = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
    state.coachSettlementReconciliationOperation = {
      signature,
      key: `settlement-coach-response:${expected.confirmationId}:${random}`.slice(0, 120),
    };
  }
  return state.coachSettlementReconciliationOperation.key;
}

function finishCoachSettlementReconciliation(readback, recoveredAfterResponseLoss = false) {
  state.coachSettlementReconciliation = readback;
  state.coachSettlementReconciliationUiState = String(readback.state || "").toUpperCase();
  state.coachSettlementReconciliationMessage = recoveredAfterResponseLoss
    ? "응답이 끊겼지만 서버 기록을 다시 읽어 완료 상태를 확인했습니다."
    : state.coachSettlementReconciliationUiState === "DISPUTED"
      ? "이의 사유를 관리자에게 전달했습니다."
      : "관리자 확정 정산을 확인했다고 응답했습니다.";
  state.coachSettlementReconciliationValidation = "";
  state.coachSettlementReconciliationChoice = "";
  state.coachSettlementReconciliationReason = "";
  state.coachSettlementReconciliationOperation = null;
}

async function submitCoachSettlementReconciliation() {
  if (state.coachSettlementReconciliationSubmitting || state.coachSettlementReconciliationLoading) return false;
  const scope = coachSettlementReconciliationScope();
  const continuationIsCurrent = coachSettlementReconciliationContinuation(scope);
  if (!continuationIsCurrent) {
    resetCoachSettlementReconciliation();
    state.coachSettlementReconciliationUiState = "ERROR";
    state.coachSettlementReconciliationMessage = "현재 담당 코치 권한과 지점을 확인한 뒤 다시 시도해 주세요.";
    renderCoachSettlementReconciliation();
    return false;
  }
  const payload = state.coachSettlementReconciliation;
  const targetStatus = String(state.coachSettlementReconciliationChoice || "");
  const targetReason = targetStatus === "disputed"
    ? normalizeCoachSettlementReconciliationReason(state.coachSettlementReconciliationReason)
    : "";
  if (
    state.coachSettlementReconciliationUiState !== "PENDING"
    || !coachSettlementReconciliationPayloadIsExact(payload, scope)
    || payload.reconciliation
  ) return false;
  if (!["acknowledged", "disputed"].includes(targetStatus)) {
    state.coachSettlementReconciliationValidation = "확인 또는 이의 중 하나를 선택해 주세요.";
    renderCoachSettlementReconciliation();
    return false;
  }
  const reasonError = targetStatus === "disputed" ? coachSettlementReconciliationReasonError(targetReason) : "";
  if (reasonError) {
    state.coachSettlementReconciliationValidation = reasonError;
    renderCoachSettlementReconciliation();
    $("#coachSettlementReconciliationReason")?.focus();
    return false;
  }
  const expected = {
    confirmationId: payload.confirmation.confirmationId,
    snapshotId: payload.snapshot.snapshotId,
    revision: Number(payload.snapshot.revision),
    sourceFingerprint: payload.snapshot.sourceFingerprint,
  };
  const operationKey = coachSettlementReconciliationOperationKey(expected, targetStatus, targetReason);
  const submitRequestId = ++state.coachSettlementReconciliationRequestId;
  const submitIsCurrent = () => submitRequestId === state.coachSettlementReconciliationRequestId
    && continuationIsCurrent();
  state.coachSettlementReconciliationSubmitting = true;
  state.coachSettlementReconciliationMessage = "확정 계산본과 담당 범위를 서버에서 다시 확인하고 있습니다.";
  state.coachSettlementReconciliationValidation = "";
  renderCoachSettlementReconciliation();
  try {
    const rawResponse = await window.TennisNoteDataClient.rpc("tn_coach_respond_monthly_settlement_confirmation", {
      target_confirmation_id: expected.confirmationId,
      target_snapshot_id: expected.snapshotId,
      target_branch_id: scope.branchId,
      target_coach_role_id: scope.coachRoleId,
      target_month: scope.settlementMonth,
      expected_snapshot_revision: expected.revision,
      expected_source_fingerprint: expected.sourceFingerprint,
      target_status: targetStatus,
      target_reason: targetReason || null,
      target_operation_key: operationKey,
    });
    const response = Array.isArray(rawResponse) ? rawResponse[0] || null : rawResponse;
    if (!submitIsCurrent()) return false;
    if (!coachSettlementReconciliationResponseMatches(response, expected, targetStatus, targetReason, scope)) {
      throw new Error("settlement_reconciliation_response_mismatch");
    }
    const rawReadback = await readCoachSettlementReconciliation(scope);
    const readback = Array.isArray(rawReadback) ? rawReadback[0] || null : rawReadback;
    if (!submitIsCurrent()) return false;
    if (!coachSettlementReconciliationResponseMatches(readback, expected, targetStatus, targetReason, scope)) {
      throw new Error("settlement_reconciliation_readback_mismatch");
    }
    finishCoachSettlementReconciliation(readback, false);
    return true;
  } catch (error) {
    if (!submitIsCurrent()) return false;
    let recovered = null;
    try {
      const rawRecovered = await readCoachSettlementReconciliation(scope);
      recovered = Array.isArray(rawRecovered) ? rawRecovered[0] || null : rawRecovered;
    } catch (_) {
      recovered = null;
    }
    if (!submitIsCurrent()) return false;
    if (coachSettlementReconciliationResponseMatches(recovered, expected, targetStatus, targetReason, scope)) {
      finishCoachSettlementReconciliation(recovered, true);
      return true;
    }
    if (
      recovered
      && coachSettlementReconciliationPayloadIsExact(recovered, scope)
      && ["ACKNOWLEDGED", "DISPUTED"].includes(String(recovered.state || "").toUpperCase())
    ) {
      state.coachSettlementReconciliation = recovered;
      state.coachSettlementReconciliationUiState = "CONFLICT";
      state.coachSettlementReconciliationMessage = "다른 화면에서 이미 응답했습니다. 서버에 저장된 상태를 다시 확인해 주세요.";
      state.coachSettlementReconciliationValidation = "";
      state.coachSettlementReconciliationChoice = "";
      state.coachSettlementReconciliationReason = "";
      state.coachSettlementReconciliationOperation = null;
      return false;
    }
    if (recovered && coachSettlementReconciliationPayloadIsExact(recovered, scope)) {
      state.coachSettlementReconciliation = recovered;
    }
    const contract = coachSettlementReconciliationErrorContract(error);
    state.coachSettlementReconciliationUiState = contract.state;
    state.coachSettlementReconciliationMessage = contract.message;
    state.coachSettlementReconciliationValidation = contract.validation;
    return false;
  } finally {
    if (submitRequestId === state.coachSettlementReconciliationRequestId) {
      if (!continuationIsCurrent()) resetCoachSettlementReconciliation();
      state.coachSettlementReconciliationSubmitting = false;
      renderCoachSettlementReconciliation();
      saveSnapshot();
    }
  }
}

function renderCoachSettlement() {
  const monthInput = $("#coachSettlementMonth");
  if (monthInput && monthInput.value !== coachSettlementMonth()) monthInput.value = coachSettlementMonth();
  const settlement = state.coachSettlement || {};
  const status = $("#coachSettlementStatus");
  if (status) {
    status.hidden = !state.coachSettlementLoading && !state.coachSettlementError;
    status.dataset.tone = state.coachSettlementError ? "danger" : "wait";
    status.textContent = state.coachSettlementError || (state.coachSettlementLoading ? "정산 자료를 불러오는 중입니다." : "");
  }
  const retryButton = $("#refreshCoachSettlement");
  if (retryButton) retryButton.hidden = !state.coachSettlementError;
  const unavailable = state.coachSettlementLoading || state.coachSettlementError || !state.coachSettlement;
  if ($("#coachRevenueAmount")) $("#coachRevenueAmount").textContent = unavailable ? "—" : formatCoachWon(settlement.revenueAmount);
  if ($("#coachRevenueCount")) {
    const refundedAmount = Number(settlement.refundedAmount) || 0;
    $("#coachRevenueCount").textContent = `결제 ${Number(settlement.paymentCount) || 0}건${refundedAmount ? ` · 환불 조정 ${formatCoachWon(refundedAmount)}` : ""}`;
  }
  if ($("#coachSettledSessions")) $("#coachSettledSessions").textContent = unavailable ? "확인 필요" : `${Number(settlement.settledSessions) || 0}회`;
  if ($("#coachEstimatedSettlement")) $("#coachEstimatedSettlement").textContent = unavailable ? "—" : formatCoachWon(settlement.estimatedSettlement);
  if ($("#coachSettlementRule")) {
    const substitute = Number(settlement.substituteSettlement) || 0;
    $("#coachSettlementRule").textContent = settlement.ruleType
      ? `${coachSettlementRuleLabel(settlement)}${substitute ? ` · 대타 ${formatCoachWon(substitute)}` : ""}`
      : "정산 규칙 확인 중";
  }
  const compactAmount = $("#coachSettlementCompactAmount");
  const compactMeta = $("#coachSettlementCompactMeta");
  if (compactAmount) {
    compactAmount.textContent = state.coachSettlementLoading
      ? "확인 중"
      : state.coachSettlementError
        ? "다시 확인"
        : formatCoachWon(settlement.estimatedSettlement);
  }
  if (compactMeta) {
    compactMeta.textContent = state.coachSettlementError
      ? "정산 자료를 불러오지 못했습니다. 눌러서 다시 시도하세요."
      : state.coachSettlementLoading
        ? "정산 자료를 불러오는 중입니다."
        : `결제 ${Number(settlement.paymentCount) || 0}건 · 수업 ${Number(settlement.settledSessions) || 0}회${Number(settlement.refundedAmount) ? ` · 환불 ${formatCoachWon(settlement.refundedAmount)}` : ""}`;
  }
  const rows = Array.isArray(settlement.rows) ? settlement.rows : [];
  const rowsTarget = $("#coachSettlementRows");
  if (rowsTarget) {
    rowsTarget.innerHTML = rows.length
      ? rows.map((row) => `
        <article>
          <div>
            <strong>${escapeHtml(row.memberName || "회원")}</strong>
            <span>${escapeHtml(row.productName || "회원권")} · ${escapeHtml(String(row.method || "결제수단 미입력"))}${Number(row.refundedAmount) ? ` · 환불 ${formatCoachWon(row.refundedAmount)} 조정` : ""}</span>
          </div>
          <div>
            <b>${formatCoachWon(row.estimatedSettlement)}</b>
            <small>매출 ${formatCoachWon(row.amount)}${Number(row.grossAmount) > Number(row.amount) ? ` (원결제 ${formatCoachWon(row.grossAmount)})` : ""} · 정산 ${Number(row.settledSessions) || 0}/${Number(row.totalSessions) || 0}회</small>
          </div>
        </article>`).join("")
      : coachEmptyState({
        title: state.coachSettlementLoading ? "정산 자료를 확인하고 있습니다." : state.coachSettlementError ? "계산 근거 확인이 필요합니다." : "선택한 달의 정산 대상이 없습니다.",
        description: state.coachSettlementError || "관리자 결제 귀속과 수업 완료·적용기간을 확인해 주세요.",
      });
  }
  renderCoachSettlementReconciliation();
  renderVisibleMemberSettlement();
}

