function lessonChartParticipantKey(participant = {}, index = 0) {
  return `${participant.userId || participant.name || "member"}:${participant.ticketId || index}`;
}

function lessonChartDraftFor(lesson = {}, participant = {}, index = 0) {
  const lessonDrafts = state.lessonChartDrafts?.[lesson.id] || {};
  return lessonDrafts[lessonChartParticipantKey(participant, index)] || null;
}

function lessonGroupFeedbackCommonDraft(lesson = {}) {
  return state.lessonChartDrafts?.[lesson.id]?.__groupCommon || null;
}

function lessonGroupFeedbackParticipantUsesException(lesson = {}, participant = {}, index = 0) {
  const draft = lessonChartDraftFor(lesson, participant, index);
  if (typeof draft?.usesException === "boolean") return draft.usesException;
  const serverDraft = String(participant.recordStatus || participant.record_status || "") === "draft" ? participant : null;
  return Boolean(serverDraft?.coachComment || serverDraft?.coach_comment || serverDraft?.nextCurriculumSkillLabel || serverDraft?.next_curriculum_skill_label);
}

function lessonParticipantNeedsFeedback(participant = {}) {
  const recordStatus = String(participant.recordStatus || participant.record_status || "").toLowerCase();
  const absenceStatus = String(participant.sameDayAbsence?.status || "").toLowerCase();
  return recordStatus !== "final" && !["announced", "pending_approval"].includes(absenceStatus);
}

function lessonChartDraftResults(lesson = {}) {
  return completionParticipantsForLesson(lesson)
    .map((participant, index) => ({ participant, index }))
    .filter(({ participant }) => lessonParticipantNeedsFeedback(participant))
    .map(({ participant, index }) => {
    const draft = lessonChartDraftFor(lesson, participant, index) || {};
    return {
      userId: participant.userId || "",
      ticketId: participant.ticketId || "",
      name: participant.name || `회원 ${index + 1}`,
      ticketName: participant.ticketName || lesson.ticket || "회원권",
      totalSessions: Number(participant.totalSessions) || Number(lesson.totalSessions) || 0,
      usedSessions: Number(participant.usedSessions) || 0,
      remainingSessions: Number(participant.remainingSessions) || Number(lesson.remaining) || 0,
      coachComment: draft.coachComment || "",
      nextCurriculumId: draft.nextCurriculumId || "",
      usesException: Boolean(draft.usesException),
    };
  });
}

function lessonChartParticipantDefaults(lesson, participant, index) {
  const recentLog = recentLogForParticipant(participant, lesson);
  const recentResult = participantLogResult(recentLog, participant);
  const localDraft = lessonChartDraftFor(lesson, participant, index);
  const serverDraft = String(participant.recordStatus || participant.record_status || "") === "draft" ? participant : null;
  const todayGoalId = recentResult?.nextCurriculumId || recentLog?.nextCurriculumId || recentLog?.curriculumId || "";
  const nextCurriculumId = localDraft?.nextCurriculumId
    ?? serverDraft?.nextCurriculumSkillLabel
    ?? serverDraft?.next_curriculum_skill_label
    ?? "";
  const comment = localDraft?.coachComment ?? serverDraft?.coachComment ?? serverDraft?.coach_comment ?? "";
  return {
    comment,
    nextCurriculumId,
    todayGoalId,
    todayGoal: todayGoalId ? selectedCurriculum(todayGoalId)?.title || "선택 안 됨" : "선택 안 됨",
  };
}

function lessonChartFinalized(lesson = {}) {
  const participants = completionParticipantsForLesson(lesson);
  if (participants.length && participants.every((participant) => String(participant.recordStatus || participant.record_status || "") === "final")) return true;
  return ["completed", "no_show", "cancelled"].includes(String(lesson.serverStatus || lesson.status || "").toLowerCase());
}

function lessonGroupDeductionSummary(lesson = {}, participants = []) {
  if (participants.length < 2 || !lessonChartFinalized(lesson)) return "";
  const deducted = participants.reduce((total, participant) => (
    total + (Number(participant.deductedSessions ?? participant.deducted_sessions) || 0)
  ), 0);
  const deductionRequested = participants.some((participant) => participant.deductionRequested === true || participant.deduction_requested === true);
  if (deductionRequested && deducted === 0) return `${participants.length}명 기록 완료 · 차감 확인 필요`;
  if (!deductionRequested && deducted === 0) return `${participants.length}명 완료 · 차감 없음`;
  return deducted === 1
    ? `${participants.length}명 완료 · 공유 회원권 1회 차감`
    : `${participants.length}명 완료 · 회원권 ${deducted}회 차감`;
}

function captureLessonTabInputs(lesson) {
  const panel = $('#lessonEditModalContent [data-lesson-tab-panel="feedback"]');
  if (panel && !panel.hidden) {
    lesson.feedbackTabInputs = [...panel.querySelectorAll("input,textarea,select")].map((node) => ({ value: node.value, checked: node.checked }));
    if (!lessonChartFinalized(lesson)) captureLessonChartDraft(lesson.id);
  }
  if (lesson.selectedSecondaryAction === "schedule" && $("#editLessonDay")) {
    lesson.scheduleEditDraft = { day: $("#editLessonDay").value, time: $("#editLessonTime").value, reason: $("#editLessonReason").value };
  }
  if ($("#coachAttendanceReason")) lesson.attendanceChoice = { ...(lesson.attendanceChoice || {}), reason: $("#coachAttendanceReason").value };
}

function coachAttendancePreviewMatches(lesson) {
  const draft = lesson.attendanceChoice || {};
  const preview = draft.preview;
  const expected = completionParticipantsForLesson(lesson).map((p) => `${p.userId}:${p.ticketId}`).sort();
  const actual = (preview?.participants || []).map((p) => `${p.userId}:${p.ticketId}`).sort();
  return preview?.contractVersion === 1 && preview.lessonId === lesson.serverLessonId
    && preview.outcome === draft.outcome && preview.deduct === draft.deduct
    && typeof preview.revision === "string" && Boolean(preview.revision)
    && expected.length > 0 && new Set(actual).size === actual.length
    && JSON.stringify(expected) === JSON.stringify(actual);
}

function coachAttendanceChoiceMarkup(lesson) {
  const draft = lesson.attendanceChoice || {};
  const busy = Boolean(lesson.attendanceInFlight);
  const ready = draft.contractReady === true && coachAttendancePreviewMatches(lesson) && !draft.loading;
  const options = (field, values) => `<div class="lesson-attendance-options" role="group" aria-label="${field === "outcome" ? "출결 상태" : "횟수 차감"}">${values.map(([value, label]) => `<button class="small-button" type="button" aria-pressed="${draft[field] === value}" data-attendance-choice="${field}" data-choice-value="${value}" data-lesson-id="${escapeHtml(lesson.id)}" ${busy || draft.contractReady !== true ? "disabled" : ""}>${label}</button>`).join("")}</div>`;
  return `<div class="lesson-edit-mini" data-lesson-action-form="attendance">
    <strong>불참·노쇼</strong>
    <span>출결 상태</span>${options("outcome", [["absence", "불참"], ["no_show", "노쇼"]])}
    <span>횟수 차감</span>${options("deduct", [[true, "차감함"], [false, "차감 안 함"]])}
    <label><span>사유 (2자 이상)</span><input id="coachAttendanceReason" type="text" minlength="2" maxlength="200" value="${escapeHtml(draft.reason || "")}" ${busy ? "disabled" : ""} /></label>
    <div class="lesson-attendance-preview" data-lesson-action-result aria-live="polite">${draft.loading ? "서버에서 처리 결과를 확인하고 있습니다." : ready
      ? draft.preview.participants.map((p) => `<p>${escapeHtml(completionParticipantsForLesson(lesson).find((v) => v.userId === p.userId)?.name || "회원")} · ${draft.outcome === "absence" ? "불참" : "노쇼"} · ${p.deductedSessions}회 차감<br>잔여 ${p.remainingBefore}회 → ${p.remainingAfter}회 · ${p.makeupCreated ? "기존 정책에 따라 보강권 생성" : "보강권 생성 없음"}</p>`).join("")
      : escapeHtml(draft.error || "출결과 차감 여부를 각각 선택해 주세요. 서버 계약을 확인하기 전에는 저장할 수 없습니다.")}</div>
    <div class="actions"><button class="small-button" type="button" data-back-lesson-actions="${escapeHtml(lesson.id)}" ${busy ? "disabled" : ""}>처리 선택</button><button class="approve-button" type="button" data-process-attendance="${escapeHtml(lesson.id)}" data-outcome="${escapeHtml(draft.outcome || "")}" data-deduct="${draft.deduct}" ${!ready || busy ? "disabled" : ""}>${busy ? "처리 중" : "저장"}</button></div>
  </div>`;
}

async function selectCoachAttendanceChoice(lessonId, field, value) {
  const lesson = ensureCoachLessonRecord(lessonId);
  if (!lesson || lesson.attendanceInFlight || !["outcome", "deduct", "contract"].includes(field)) return;
  const probing = field === "contract";
  if (!probing && lesson.attendanceChoice?.contractReady !== true) return;
  captureLessonTabInputs(lesson);
  const draft = lesson.attendanceChoice ||= {};
  if (probing) draft.contractReady = false;
  else draft[field] = field === "deduct" ? value === "true" : value;
  // Changing the outcome never silently changes the independently chosen deduction.
  draft.preview = null;
  draft.error = "";
  const sequence = draft.sequence = (draft.sequence || 0) + 1;
  draft.loading = probing || (["absence", "no_show"].includes(draft.outcome) && typeof draft.deduct === "boolean");
  renderLessonEditModal();
  if (!draft.loading) return;
  try {
    const client = window.TennisNoteDataClient;
    if (!client?.rpc || !client.getSession?.()?.access_token) throw new Error("login_required");
    const preview = await client.rpc("tn_preview_coach_attendance_choice", {
      target_lesson_id: lesson.serverLessonId,
      target_outcome: probing ? "absence" : draft.outcome,
      target_deduct: probing ? false : draft.deduct,
    });
    if (sequence !== draft.sequence) return;
    const candidate = { ...lesson, attendanceChoice: { ...draft, preview,
      outcome: probing ? "absence" : draft.outcome, deduct: probing ? false : draft.deduct } };
    if (!coachAttendancePreviewMatches(candidate)) throw new Error("exact_preview_mismatch");
    draft.contractReady = true;
    // A read-only capability probe must not select an attendance policy for the coach.
    draft.preview = probing ? null : preview;
  } catch (error) {
    if (sequence !== draft.sequence) return;
    draft.preview = null;
    draft.contractReady = false;
    const code = String(error?.payload?.message || error?.payload?.code || error?.message || "server_error");
    draft.error = code.includes("existing_member_request")
      ? "회원이 이미 불참 요청을 보냈습니다. 요청 내역에서 먼저 확인해 주세요."
      : code.includes("already_processed")
        ? "이미 처리되었거나 확정 중인 수업입니다. 최신 상태를 확인해 주세요."
        : code.includes("group_policy_unknown")
          ? "그룹 회원권의 차감 정책을 확인할 수 없어 처리할 수 없습니다. 관리자에게 문의해 주세요."
          : code.includes("ticket_") || code.includes("exact_ticket")
            ? "이 수업의 정확한 회원권 또는 차감 가능 횟수를 확인할 수 없습니다."
            : code.includes("forbidden")
              ? "본인이 담당하는 수업만 처리할 수 있습니다."
              : "서버의 출결 선택 계약 또는 최신 수업·회원권 상태를 확인할 수 없습니다. 새로고침 후 다시 선택해 주세요.";
  }
  if (sequence === draft.sequence) {
    draft.loading = false;
    if (state.editingLessonId === lesson.id) { captureLessonTabInputs(lesson); renderLessonEditModal(); }
  }
}

