  const ticketUnit = Math.max(1, Number(entitlementGuard.ticket?.lessonMinutes) || Number(draft.durationMinutes) || 20);
  const completionUnits = Math.max(1, Math.ceil((Number(draft.durationMinutes) || 20) / ticketUnit));
